// Акафісти з AlexandrKozlovskiy/OrthodoxCalendar (Apache-2.0), Київський ізвод: транслітерація правилами віра.укр.
// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святителю Нектарію Пентапольському, Егінському чудотворцю","e":"Akathist to St Nectarios of Pentapolis, Wonderworker of Aegina","secs":[{"h":"Кондак 1","ps":["Взбра́нний Некта́ріє Пентапо́ля митрополи́ті і Єгинський чудотво́рче, прино́сим ті проше́нія о боля́щих сро́дниках на́ших: ізря́ден бо яви́лся єси́ ціли́тель раковия я́зви і про́чих неду́гов, всей вселе́нній благода́ть да́руя, сего́ ра́ди єди́німи усти́ і єди́нім се́рдцем воспіва́єм ті при́сно:","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Ікос 1","ps":["А́нгела храни́теля во святі́м креще́нії обріти́й, от млади́х ногте́й равноа́нгельськаго житія́ возжела́л єси́, о́тче наш Некта́ріє; ни́ні же со А́нгели зрі́нієм Сла́ви Бо́жия наслажда́яйся, моли́ всіх А́нгелов Влади́ку о пою́щих ті сицева́я:","Ра́дуйся, вінча́нних роди́телей пло́де благослове́нний;","ра́дуйся, от чре́ва ма́тері Бо́гом освяще́нний.","Ра́дуйся, ізді́тська нави́кший послуша́нію;","ра́дуйся, от ю́ности ізучи́вий Писа́нія.","Ра́дуйся, Бо́жиїх слове́с одушевле́нная кни́го;","ра́дуйся, жива́я боголю́бія скрижа́ль.","Ра́дуйся, Бо́гом ізбра́нний за кро́тость і смире́ніє;","ра́дуйся, дом оста́вивий духо́внаго ра́ди уче́нія.","Ра́дуйся, я́ко тебе́ ра́ди бу́ря зі́льна на мо́рі утиши́ся;","ра́дуйся, я́ко по́ясом твої́м надломленная мачта укріпи́ся.","Ра́дуйся, о́рля юноє, іму́ще крилі́ у́мния моли́тви;","ра́дуйся, єле́ні, взиска́вий істо́чники покая́нія.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 2","ps":["Ви́дящи тя на возду́сі моля́щася, черниця ні́кая престрашна бисть, Боголю́бче; ти же дар моли́тви сокрива́я, уста́ ді́ви кля́твою запечатлі́л єси́ Го́споду в се́рдці воспі́в: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Христо́в моли́твою стяжа́л єси́, святи́й Некта́ріє, во є́же разумі́ти, что єсть во́ля Бо́жия, блага́я, уго́дная і соверше́нная; научи́ і нас на вся́ком мі́сті воздіва́ти руки́ к Бо́гу без гні́ва і сомні́нія, да приї́меши от нас похва́льная:","Ра́дуйся, во юдо́лі плаче́вні восхожде́нія положи́вий;","ра́дуйся, плоди́ Ду́хи ізрасти́вий.","Ра́дуйся, ча́до гори́ Афо́нськия;","ра́дуйся, ключу́ моли́тви Ісу́сови.","Ра́дуйся, древляго благоче́стія світи́ло;","ра́дуйся, гра́де Святи́я Тро́йці.","Ра́дуйся, благода́тію осіне́нний;","ра́дуйся, Херуви́ме о́гненний.","Ра́дуйся, соль землі́ обетованния;","ра́дуйся, слеза́ми сі́явий, пожавий ра́достію.","Ра́дуйся, на не́мже процвіте́ святи́ня Христа́;","ра́дуйся, я́ко Бог благоді́йствова тя.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго облече́нний, о́тче Некта́ріє, си́лу слове́с Христо́вих утверди́л єси́: во Ца́рствії Моє́м,– Той рече́,– ні же́няться, ніже́ посяга́ють, но я́ко А́нгели на небесі́, ви́ну пою́ть: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи Пречи́стая Богоро́диця в услуженії все во́їнство небе́сноє, тебі́, уго́дниче, а́ки А́нгела во пло́ті, воспевателя чуде́с Свої́х поста́ви: ми же, Марі́їн омофо́р над тобо́ю зря́ще, со стра́хом і любо́вію припа́даєм ті:","Ра́дуйся, та́йний ізбра́нниче Богома́тере;","ра́дуйся, велі́ній Єя́ ісполни́телю.","Ра́дуйся, ду́ха кро́тости от Чи́стия Голуби́ці прия́вий;","ра́дуйся, в пі́сніх духо́вних Присноді́ву просла́вивий.","Ра́дуйся, уча́й угожда́ти не́ба і землі́ Цари́це;","ра́дуйся, моли́твами Ма́тере ми́лость у Си́на обріти́й.","Ра́дуйся, мі́рило пра́ведности і му́дрости пала́то;","ра́дуйся, висото́ рассужденія і смире́нія глубино́.","Ра́дуйся, Єгинський кри́не, некта́р покая́нія точа́щий;","ра́дуйся, Єде́мськая пчело́, ме́дом богосло́вія нас снабдіва́ющая.","Ра́дуйся, мирова́рнице, ми́ро ізлива́ющая;","ра́дуйся, ча́ше духовного омове́нія.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 4","ps":["Раковую я́зву кровоточащу на гру́ди імі́я, ієре́й хра́ма твоєго́, Некта́ріє, см'яте́ся, єгда́ ти я́влься облобиза́ єго́, а́ки во пло́ті сий; он же ісціле́ніє получи́в, тебі́ неви́диму би́вшу, со слеза́ми возопи́ Бо́гові: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша мно́зі о ди́внім ісціле́нії, при жи́зні тобо́ю содеянном, єгда́ во страні́ Канадстей, святі́й Литургі́ї служиме, в Ду́сі яви́лся єси́, чудотво́рче Некта́ріє, і расслаблена ні́коєго му́жа воздви́гл єси́, к Ча́ші єго́ призива́я; той же здрав бисть, ві́си Єгинськия дости́г і, тя во пло́ті узрі́в, велегла́сно взива́ше:","Ра́дуйся, врачу́ гостеприїмний, Греції похвало́;","ра́дуйся, Никола́я Чудотво́рця сла́ву стяжа́вий.","Ра́дуйся, кла́дезю благости́ні;","ра́дуйся, милосе́рдий самарянине.","Ра́дуйся, да́ром чуде́с обогащенний;","ра́дуйся, посіща́яй лю́ди смире́нния.","Ра́дуйся, утіша́яй нас чудеси́ нело́жними;","ра́дуйся, я́ко невозмо́жная други́м тебі́ возмо́жна.","Ра́дуйся, я́ко ско́рби на́ша на ра́дость прелага́єши;","ра́дуйся, ти бо от оче́й на́ших сле́зи отира́єши.","Ра́дуйся, одержи́мих бі́си свободи́телю;","ра́дуйся, раковия я́зви ісціли́телю.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю покая́нія возше́л єси́, о́тче, над вселе́нній, лучи́ сокруше́нія о людськи́х беззако́ніях ви́ну іспуща́яй; озари́ уми́ на́ша к зрі́нію гріх на́ших, да уми́лостивим Влади́ку пі́нієм: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша отрокови́ці чи́стия Архієре́я своєго́, в лі́поті душі́ і ті́ла Бо́гу предстоя́ща, і позна́во в нем вели́каго моли́твенника і чудотво́рця, согла́сно возгласи́ша ті, святи́телю Некта́ріє:","Ра́дуйся, Христа́ при́сноє жили́ще;","ра́дуйся, Ду́ха ди́вноє сокро́вище.","Ра́дуйся, ца́рськоє свяще́ніє Вели́каго Архієре́я;","ра́дуйся, призва́нний к Престо́лу Ві́чнаго Царя́.","Ра́дуйся, Пло́ті Христо́ві сотелесниче;","ра́дуйся, Кро́ве Святи́я прича́стниче.","Ра́дуйся, глашатаю покая́нія;","ра́дуйся, хода́таю о нас пред Бо́гом.","Ра́дуйся, Некта́ріє, А́нгели веселя́яй;","ра́дуйся, пла́меню, де́мони пожига́яй.","Ра́дуйся, пучи́но щедро́т;","ра́дуйся, мо́ре чуде́с пресла́вних.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 6","ps":["Пропові́дниче Єди́наго Блага́го, Некта́ріє блаже́нний, тя, смири́вшася под крі́пкую ру́ку Бо́жию, Той превознесе́; в страстном мо́рі вла́ющихся не забу́ди чад твої́х, но на бре́зі смире́нія поста́ви я, да возвеличать Бо́га твоєго́, воспіва́я: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшу сві́ту блаже́нств Христо́вих, от степе́ні в степе́нь восте́кл єси́, богому́дре Некта́ріє: кро́тостію і ми́ром, воздержа́нієм і любо́вію ду́шу свою́ просвіти́л єси́, да от нас ни́ні слишиши сицева́я:","Ра́дуйся, носи́вий ри́зу смире́нія;","ра́дуйся, оби́ди покривавий проще́нієм.","Ра́дуйся, наслажда́яйся о мно́жестві ми́ра;","ра́дуйся, наслі́дуяй зе́млю кро́тких.","Ра́дуйся, фіяле покаяннаго пла́ча;","ра́дуйся, чистоти́ серде́чния зерца́ло.","Ра́дуйся, і́менем Ісу́совим насище́нний;","ра́дуйся, вода́ми Писа́ній напоє́нний.","Ра́дуйся, ми́лость і суд возвісти́вий;","ра́дуйся, любо́вію вражду́ упраздни́вий.","Ра́дуйся, благочести́вий житіє́м;","ра́дуйся, гони́мий пра́вди ра́ди.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 7","ps":["Хотя́ челові́к Бо́жий соверше́н би́ти, Некта́ріє пра́ведне, путь непоро́чних ізбра́л єси́: на Єгинстем о́строві жите́йськоє мо́ре, а́ки в ковче́зі, препла́вая, побіди́тельная воспіва́л єси́ Го́сподеві: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго Заві́та учи́тель ізря́ден яви́лся єси́, сло́во Бо́жиє житіє́м свої́м пропові́давий: я́ко ність на́ша брань проти́ву пло́ті і кро́ве, но миродержателем тьми ві́ка сего́. Ми же о Го́споді возмога́я, вопіє́м ті, держа́вне Некта́ріє:","Ра́дуйся, до́блій во́їне Ісу́са Христа́;","ра́дуйся, язво духово́м зло́би поднебе́сним.","Ра́дуйся, вся ору́жія Бо́жия восприя́вий;","ра́дуйся, препоя́савий чре́сла і́стиною.","Ра́дуйся, я́ко но́зі твої́ красни́ благові́стієм ми́ра;","ра́дуйся, я́ко на версі́ твоє́м утвержде́н шлем спасе́нія.","Ра́дуйся, щиті́ ві́ри, і́мже ві́рнії огражда́ються;","ра́дуйся, мечу́ обоюдоо́стрий, є́ресі посяцяяй.","Ра́дуйся, побіди́телю, от дре́ва жи́зні вкуша́яй;","ра́дуйся, челові́че Бо́жий, стра́нний сме́рті втори́я.","Ра́дуйся, свиді́телю ві́ри істинниє;","ра́дуйся, ра́йськая вітв спасе́нія.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 8","ps":["Стра́нноє обрі́теся в тебі́ соверше́нство, то́чію соверше́нним в любве́ доступноє; усоверши́ любо́вію душі́ на́ша, любвеобильне Некта́ріє, да в му́жа соверше́нна дости́гше, поє́м Бо́гові: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ в ни́жніх, смире́нним послі́дуя, во ви́шніх с Бо́гом, си́річ с Любо́вію, пребива́я; да́руй нам, о, неботаї́нниче Некта́ріє, любве́ позна́ніє, во є́же пі́ти ті сицева́я:","Ра́дуйся, я́ко плі́нником содеялся єси́ любве́ Бо́жия;","ра́дуйся, я́ко чад свої́х любо́вію пліни́л єси́.","Ра́дуйся, ви́ю под і́го Спа́сово подклони́вий;","ра́дуйся, бремена́ бли́жніх носи́вий.","Ра́дуйся, в любве́ укорененний;","ра́дуйся, в ми́лості утвержде́нний.","Ра́дуйся, широту́ і долготу́ Креста́ разуміва́яй;","ра́дуйся, висоту́ і глубину́ Дре́ва постигаяй.","Ра́дуйся, разумниче любве́, ра́зум превосходя́щая;","ра́дуйся, полноти́ Бо́жия вмісти́лище.","Ра́дуйся, в умі́ держа́й єли́ка і́стинна, пра́ведна і честна́;","ра́дуйся, се́рдцем люб'я́й єли́ка пречи́ста, доброхва́льна і прелюбе́зна.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє і челові́чеськоє удиви́ся о́бразу, вели́кий Некта́ріє, в тебі́ явле́нному: я́ко ність во Христі́ ні іуде́й, ні е́ллин, ні раб, ні свобо́дь, ні му́жеск пол, ні же́нський, но но́ва твар, Іскупи́телю тва́рі пою́щая: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния умолко́ша, житію́ твоєму́, святи́й о́тче Некта́ріє, див'я́щеся, ка́ко свят бил єси́, грі́шним ся іменова́вий; духо́вен бил єси́, із землі́ перстния взя́тий: по сме́рті вознесе́н бил єси́, при жи́зні умо́м до а́да низшедий; ми же отве́рзше уста́, а́ки ді́ти вопіє́м:","Ра́дуйся, главо́, ві́ру возви́сившая;","ра́дуйся, уста́, безбо́жіє посрамившия.","Ра́дуйся, о́ко, Богові́дінієм просвіще́нноє;","ра́дуйся, десни́це, могу́ществом Єго́ укрепленная.","Ра́дуйся, смиря́яй кичливия уми́;","ра́дуйся, сокруша́яй го́рдая се́рдця.","Ра́дуйся, яви́вий си́лу в не́мощі;","ра́дуйся, в слеза́х наше́дий ра́дость.","Ра́дуйся, уме́рий і живи́й;","ра́дуйся, земни́й і небе́сний.","Ра́дуйся, гору́шноє сі́м'я живота́;","ра́дуйся, зрі́лий кла́се Воскресе́нія.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, я́ко ді́ву, єдинему Жениху́ ту обручи́л єси́; ни́ні же вшед в неві́стник Христо́в с ли́ки ді́вственних, Некта́ріє сла́вне, поє́ши піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ всім прибегающим к тебі́, достохва́льне Некта́ріє, і́маши бо благода́ть немощни́я врачева́ти і к небе́сному наслі́дію возводи́ти: нас у́бо, чад твої́х, уврачу́й і в Ца́рствіє Христо́во возведи́, да вседу́шно рече́м ті сицева́я:","Ра́дуйся, ста́рче благода́тний;","ра́дуйся, ю́ниць путево́ждь преізря́дний.","Ра́дуйся, невинний па́стирю невинних ове́ць;","ра́дуйся, му́дрий собира́телю ді́вственних жемчужин.","Ра́дуйся, вселе́нния духо́вний окорми́телю;","ра́дуйся, Євхари́стії пла́менний служи́телю.","Ра́дуйся, гла́се смире́ннаго Христа́;","ра́дуйся, глаго́лі зиждительнаго Ду́ха.","Ра́дуйся, в терпі́нії іскушенний;","ра́дуйся, скорбми́ очище́нний.","Ра́дуйся, побо́рниче Бо́жия пра́вди;","ра́дуйся, наслі́дниче Христо́ви сла́ви.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 11","ps":["Пі́ніє Богома́тері приноси́л єси́, уго́дниче Бо́жий, Ма́терію Сві́та Ді́ву імену́я, ни́ні же соверше́нне просвіти́лся єси́ разумі́нієм та́йни воплоще́нія, вознося́ го́ре глас: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том Боже́ственния сла́ви просвіща́єма зрим тя, Некта́ріє, в черто́зі сла́ви: просвіти́ одія́ніє душ на́ших Тро́їчеським сія́нієм, да воспіва́єм ті непреста́нно:","Ра́дуйся, ка́меню драги́й Царе́ви дияди́ми;","ра́дуйся, мо́лніє Носи́маго на Серафи́міх.","Ра́дуйся, я́ко сві́тла за́повідь, просвіти́вшая о́чі твоя́;","ра́дуйся, я́ко возлюби́л єси́ ю па́че зла́та і топа́зія.","Ра́дуйся, сребро́ разжже́но, очище́но седьмери́цею;","ра́дуйся, гу́сли духо́вния, Спасова цівни́це.","Ра́дуйся, в се́рдці і́м'я Бо́жиє написа́вий;","ра́дуйся, любо́вію по́двиг ві́ри оправда́вий.","Ра́дуйся, святи́ню Ду́ха носи́вий;","ра́дуйся, освяти́вий душі́, растлі́нния страстьми́.","Ра́дуйся, пра́ведностію, а́ки виссо́ном убеленний;","ра́дуйся, Тро́йці позна́нієм озаре́нний.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 12","ps":["Благода́ть, от Бо́га ті да́нную, умножа́я умно́жил єси́, ра́бе Бо́жий, благи́й і ві́рний Некта́ріє, ті́мже і нас ку́плю духо́вную ді́яти сотвори́, да обрі́тше ли́хву, Христу́ воспої́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ чудеса́, пречу́дне Некта́ріє, ві́ми, я́ко Христо́с в тя бога́тно всели́ся, сего́ ра́ди чудодейну десни́цю Єго́ на нас низведи́, глаго́лющих си́це:","Ра́дуйся, преє́мниче дре́вніх отце́в;","ра́дуйся, но́вий уго́дниче Христо́в.","Ра́дуйся, Вели́кия Це́ркве красото́;","ра́дуйся, всеми́рная наде́ждо.","Ра́дуйся, себі́ уничиживий, Бо́гом просла́вленний;","ра́дуйся, в послі́дніх ходи́вий, пе́рвим поста́вленний.","Ра́дуйся, діла́ оби́телі то́чію знавий, єго́же зна́єть вселе́нная;","ра́дуйся, чужди́й до́льнія сла́ви, небе́сною мздо́ю почте́нний.","Ра́дуйся, і́же по кончи́ні недви́жим лежа́й, неду́жна восстави;","ра́дуйся, і́же мно́гим яви́вийся, плач о кончи́ні уста́ви.","Ра́дуйся, дві златни́ци, мона́шества і свяще́нства, от Бо́га получи́вий;","ра́дуйся, с ли́хвою цільби́ і чуде́с зла́то Христу́ возврати́вий.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 13","ps":["О, свяще́нная главо́, ди́вний врачу́ Архієре́ю Бо́жий Некта́ріє! Прийми́ ни́ні ма́лоє, оба́че те́плоє моле́ніє чад твої́х, благода́ті су́щей в тебі́ ві́рующих. Да́руй нам неду́гов ісціле́ніє і от ві́чния ізба́ви поги́белі, да Христу́ Спа́су на́шему взива́єм с ра́достію: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела храни́теля во святі́м креще́нії обріти́й, от млади́х ногте́й равноа́нгельськаго житія́ возжела́л єси́, о́тче наш Некта́ріє; ни́ні же со А́нгели зрі́нієм Сла́ви Бо́жия наслажда́яйся, моли́ всіх А́нгелов Влади́ку о пою́щих ті сицева́я:","Ра́дуйся, вінча́нних роди́телей пло́де благослове́нний;","ра́дуйся, от чре́ва ма́тері Бо́гом освяще́нний.","Ра́дуйся, ізді́тська нави́кший послуша́нію;","ра́дуйся, от ю́ности ізучи́вий Писа́нія.","Ра́дуйся, Бо́жиїх слове́с одушевле́нная кни́го;","ра́дуйся, жива́я боголю́бія скрижа́ль.","Ра́дуйся, Бо́гом ізбра́нний за кро́тость і смире́ніє;","ра́дуйся, дом оста́вивий духо́внаго ра́ди уче́нія.","Ра́дуйся, я́ко тебе́ ра́ди бу́ря зі́льна на мо́рі утиши́ся;","ра́дуйся, я́ко по́ясом твої́м надломленная мачта укріпи́ся.","Ра́дуйся, о́рля юноє, іму́ще крилі́ у́мния моли́тви;","ра́дуйся, єле́ні, взиска́вий істо́чники покая́нія.","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Кондак 1","ps":["Взбра́нний Некта́ріє Пентапо́ля митрополи́ті і Єгинський чудотво́рче, прино́сим ті проше́нія о боля́щих сро́дниках на́ших: ізря́ден бо яви́лся єси́ ціли́тель раковия я́зви і про́чих неду́гов, всей вселе́нній благода́ть да́руя, сего́ ра́ди єди́німи усти́ і єди́нім се́рдцем воспіва́єм ті при́сно:","Ра́дуйся, Некта́ріє, Архієре́ю Бо́жий."]},{"h":"Молитва","ps":["О, мироточи́вая главо́, святи́телю Некта́ріє, архієре́ю Бо́жий! Во времена́ вели́каго отступле́нія, не́честію мир плени́вшу, благоче́стієм просія́л єси́ і главу́ прего́рдаго Денни́ці, уязвля́ющаго нас, сокруши́л єси́. Сего́ ра́ди дарова́ ті Христо́с врачева́ти я́зви неісце́льни, за беззако́нія на́ша нас порази́вшия. Ві́руєм: возлюби́ тя Бог пра́веднаго, да тебе́ ра́ди нас, грі́шних, поми́луєть, от кля́тви разріши́ть, от неду́г ізба́вить, і по всей вселе́нній стра́шно і сла́вно бу́деть і́м'я Єго́, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О, святи́телю Некта́ріє, о́тче Богому́дрий! Прийми́, блюсти́телю ві́ри правосла́вния, іспові́даніє усте́н люде́й христоімени́тих, со́бранних днесь в хра́мі благода́тію Бо́жиєю, в тебі́ живу́щею. Вість бо дости́же до преді́л Россі́йських, я́ко ти, ве́лій во святи́х уго́дниче Христо́в, во всіх конці́х вселе́нния призива́ющим і́м'я твоє́ явля́єшися і от ра́ковия болі́зні ісціле́ніє да́руєши. Сли́шахом об ієре́є, тебі́ тезоімени́том і храм во і́м'я твоє́ созида́вшем со скорбми́ ве́ліїми. Ра́ковою у́бо я́звою грудно́ю пораже́н бі, кро́ві на всяк день точа́щейся, і стражда́ше лю́ті, ді́ла же своєго́ свята́го не оставля́ше. Внеза́пу ти, святи́телю многоми́лостиво, с Небесе́ сшед, єму́ во хра́мі предста́л єси́ во ви́димом о́бразе. Он же непщу́я тя собра́та єди́на от сме́ртних би́ти, проша́ше моли́тв твої́х і рече́: «Боля́й єсьм вельми́, оба́че хощу́ святи́й олта́р назда́ти, да поне́ єди́ножди святу́ю Літургі́ю вку́пі с прихожа́ни совершу́; послі́жде і умре́ти гото́в єсьм, смерть бо м'я не страши́ть». Ти же, о́тче, безпло́тен сий, слеза́ми лице́ своє́ ороша́ше! І об'є́м страда́льця, лобиза́ше і глаго́ля: «Не тужи́, ча́до моє́, я́ко, болі́знію іспи́тан, здрав бу́деши. Всі у́бо о чудеси́ сем ві́дати і́муть». Он же, ісціле́н бив, а́біє разумі́, с кім бесі́доваше, тебі́ неви́диму би́вшу. О, вели́кий уго́дниче Христо́в Некта́ріє! Храм о́ний сверше́н єсть ни́ні, і чудеса́ твої́ а́ки мо́ре преізлива́ющеєся умно́жишася! Ми же позна́хом, я́ко моли́тві пра́ведника до́лжно поспешеству́ємой би́ти усе́рдієм на́шим к слу́жбі Бо́жієй і реши́мостью за Христа́ умира́ти, да здра́ві обря́щемся. Мо́лять тя, о́тче пра́ведний, боля́щая ча́да твоя́: да соверша́ється с на́ми во́ля Бо́жия, блага́я, уго́дная і соверше́нная, не хотя́щи сме́рті грі́шнику, но є́же обрати́тися і жи́ву би́ти єму́. Ти же, провозві́стниче во́лі Бо́жієй, ісціли́ ни благода́тним явле́нієм свої́м, да вели́к бу́деть Бог на Небесі́ і на землі́ во ві́ки віко́в! Амі́нь."]},{"h":"Тропар, глас 4","ps":["Преподо́бничеськи пожи́в, я́ко му́дрий ієра́рх, / просла́вил єси́ Го́спода / доброді́тельним житіє́м, Некта́ріє преподо́бне. / Ті́мже, Уті́шителя просла́влен си́лою, / Боже́ственними мощми́ твої́ми, / де́мони отго́ниши і боля́щия ісціля́єши, // ві́рою приходя́щия ті."]},{"h":"Кондак, глас 2","ps":["Боже́ственний гром, труба́ духо́вная, ві́ри насади́телю і отсіка́телю єресе́й, Тро́йці уго́дниче, вели́кий святи́телю Некта́ріє, со А́нгели предстоя́ при́сно, моли́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Некта́ріє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому преподобному Паїсію Святогорцю","e":"Akathist to our Venerable Father Paisios the Athonite","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго Панагу́ди подви́жника і арома́тницю благоуха́нную, Каппадокі́йськоє прозябе́ніє і предста́теля неуси́пнаго, да воспої́м согла́сно. А́нгельському бо житію́ подража́я, Тро́йці Святі́й благоугоди́, тім і зове́м:","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Ікос 1","ps":["А́нгел показа́лся єси́ во уді́лі Богоро́диці ізбра́ннім, і нам хода́тай теплі́йший пред Бо́гом, Паї́сіє о́тче, ті́мже та́ко тя воспіва́єм:","Ра́дуйся, Каппадокі́ї доброво́нноє ми́ро,","ра́дуйся, ви́шняго жи́тельства о́браз яви́вий,","ра́дуйся, Асі́ї Ма́лия процвіте́ніє,","ра́дуйся, свята́го Арсе́нія похвале́ніє,","ра́дуйся, во фарасіо́тіх приснопіва́ємий,","ра́дуйся, іноку́ющих пра́вило,","ра́дуйся, ве́ліє Елла́ди і ві́ри храни́ло,","ра́дуйся, Каппадокі́йськаго ро́да світи́ло,","ра́дуйся, Византі́ї боже́ственная о́трасле,","ра́дуйся, добро́то Афо́на і о́рле,","ра́дуйся, земни́й а́нгеле, ве́стниче на землі́,","ра́дуйся, челові́че небе́сний, пребива́яй на Небесі́.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 2","ps":["Ви́дяще, я́ко от руки́ свяще́ннаго Арсе́нія во Фара́сі Каппадоки́йстей, роди́тельнице святи́х, Креще́ніє прия́л єси́, і я́ко сего́ моли́тва многопло́дну тя о́трасль Ма́лия Асі́ї і Елла́ди яви́, тя прославля́єм по достоя́нію, Бо́гові пле́щуще: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́я і познава́я страда́нія із оте́чествія проізгна́нних, стра́нствуя і печа́ля о до́ма роди́тельськаго разоре́нії, во ві́рі укріпи́лся єси́ і богоразу́мія прия́л єси́ світ от благода́ті Бо́жия, Паї́сіє свя́те. Сего́ ра́ди і ми, взира́юще на чудеса́ твоя́, восклиця́єм ті такова́я:","Ра́дуйся, Ісу́сових благослове́ній стяжа́телю,","ра́дуйся, уде́ла Богома́терняго боже́ственний світода́телю,","ра́дуйся, ві́трило многому́дрих благодія́ній,","ра́дуйся, арома́тнице Ви́шняго дарова́ній,","ра́дуйся, Бо́жия Ду́ха блаже́ннійшеє сія́ніє,","ра́дуйся, доброді́телей несказа́нноє благоуха́ніє,","ра́дуйся, Афо́нськая лі́торасле прекра́сная,","ра́дуйся, а́ки купі́ль Силоа́мськая, врачу́яй вся́кия стра́сти,","ра́дуйся, Пресвяти́я служи́телю преблаже́нний,","ра́дуйся, Святи́я Го́ри вождю́ і кли́че побі́дний,","ра́дуйся, поста́ і моли́тви ді́лателю неусипа́ємий,","ра́дуйся, засту́пниче стра́ждущих і опеча́ленних.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́ємих му́чеников чтя житія́ і разумі́я, ти душе́ю блаже́нною к непреста́нному славосло́вію Всетворця́ восходи́л єси́. Ми же сіє́ воспомина́юще, вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["«Аз єсьм Воскресе́ніє і Живо́т. Ві́руяй в М'я не у́мреть во ві́ки». Сі́ї словеса́ от Небе́снаго Жениха́ усли́шав і іспо́лнь сий сві́та боже́ственна, неві́рія пре́лесть низве́ргл єси́. Сего́ ра́ди благода́рственно вопіє́м ті та́ко:","Ра́дуйся, во о́трочестві безбо́жия сі́ті препре́вий,","ра́дуйся, я́ві Христа́ узрі́вий,","ра́дуйся, оби́телі Стоміо́нськия устрої́телю,","ра́дуйся, Кони́тських єретико́в побіди́телю,","ра́дуйся, ми́лостині пото́че неісчерпа́ємий,","ра́дуйся, не́бесним сія́нієм укріпля́ємий,","ра́дуйся, Сина́йськия гори́ подви́жниче,","ра́дуйся, оби́телі великому́ченици Єкатери́ни моли́твенниче,","ра́дуйся, му́дростію ді́ві сей подража́телю,","ра́дуйся, святи́м Галактіо́ну і Єписти́мії соседа́телю,","ра́дуйся, са́де, прозяби́й от гори́ Мойсе́єви ка́мене,","ра́дуйся, моли́тви а́нгельськия на землі́ воспіва́ніє.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 4","ps":["Раче́ніє боже́ственноє к Богома́тері, чисті́йший о́тче, поне́же імі́я, Сію́ Предста́тельницю неуси́пную і Храни́тельницю стяжа́. Сего́ ра́ди і ми, дарова́ній твої́х жела́юще приобщи́тися, о тебі́ поє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша і́м'я твоє́ земні́ї конці́, Паї́сіє свя́тче, ти бо, я́ко со́лнце блиста́яй во времена́ послі́дняя і Правосла́віє утвержда́яй і́менем Го́спода Ісу́са Христа́, показа́лся єси́. Ми же, єдиноми́сленні пам'яту́юще боже́ственная уче́нія твоя́, приноша́єм ті рече́нія такова́я:","Ра́дуйся, люби́мче ізря́днійший Пресвяти́я,","ра́дуйся, ни ущедря́яй Ма́тере Бо́жия кри́не,","ра́дуйся, сомоли́твенниче Херуви́мом,","ра́дуйся, єдинонра́вниче Серафи́мом,","ра́дуйся, укріпле́ніє Правосла́вія,","ра́дуйся, у́тваре преізбра́нная,","ра́дуйся, чернори́зцев огра́до і оте́чествія хране́ніє,","ра́дуйся, Ко́ници о́трасле, Стоміо́на же заступле́ніє,","ра́дуйся, я́ко лоза́ Богома́тере, благовре́менний плод принося́й,","ра́дуйся, вертогра́ді покая́нія благоуха́яй,","ра́дуйся, бесі́дуяй Бо́жиїми словеси́,","ра́дуйся, умаще́ніє я́звам гре́шничим.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 5","ps":["Богоприя́тну любо́в я́ко стяжа́вий, же́ртву ся бра́тіям возложи́ і благослове́нієм Пречи́стия оделя́ше всіх. Такова́го ся отверже́нія ра́ди ни́ні со А́нгели Христа́ прославля́єши, ми же, в па́м'ять твою́ призива́ємії, вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя ду́шу за бли́жняго полага́юща, блаже́нне Паї́сіє, к тебі́ прибіга́єм: ми́лостив бу́ди нам і, Влади́ці Христу́ предстоя́, Того́ умоли́, да отжене́ть ум помрача́ющую гріхо́вную тьму от моле́бними пі́сньми хва́лящих тя сицеви́ми:","Ра́дуйся, Панагу́ди до́блественний ратобо́рче,","ра́дуйся, Богоро́диці песносло́вче,","ра́дуйся, путево́дная заблу́ждшим звіздо́,","ра́дуйся, Афо́нськая зову́щая к Бо́гу трубо́,","ра́дуйся, утіше́ніє пла́чущих,","ра́дуйся, помо́щниче стра́ждущих,","ра́дуйся, печа́льних боже́ственноє укріпле́ніє,","ра́дуйся, не оставля́яй і́ноков попече́нієм,","ра́дуйся, у Ми́лостивия за ни предста́телю,","ра́дуйся, неду́жних безме́зднейший врачева́телю,","ра́дуйся, подвиза́ющихся направля́яй,","ра́дуйся, ізря́дне Врата́рницю Богоро́дицю восхваля́яй.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 6","ps":["Пропові́дник богоно́сен єси́ і столп ві́ри, да́ри Ду́ха Свята́го нам іспроша́яй, тім і ми тебе́ ра́ди, ста́рче преди́вний, немо́лчно поє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в я́ко лампа́да неугаси́мая сві́том Трисо́лнечнаго Божества́, покая́нія наста́вник яви́ся, Паї́сіє свя́те. Ми же, твої́ми предста́тельстви сви́шнєє утіше́ніє і благода́ті позна́ніє приє́млющії, хва́лим тя, вопію́ще:","Ра́дуйся, ковче́же себі́ отверже́нія і воздержа́нія,","ра́дуйся, Уті́шителя благода́ть на нас ізлива́яй,","ра́дуйся, Со́лнця-Христа́ малове́рним провозвісти́вий,","ра́дуйся, ми́лостію Человіколю́бця всіх удовли́вий,","ра́дуйся, о ми́рі моли́твою ви́ну благоуха́яй,","ра́дуйся, я́ко вино́ сла́дкоє, ду́ші ра́достію ісполня́яй,","ра́дуйся, Богома́тере сла́віє ізбра́нний,","ра́дуйся, приноша́яй сле́зи Христу́ я́ко ши́пок доброуха́нний,","ра́дуйся, Фове́ри предста́тельство і могу́чеє возглаше́ніє,","ра́дуйся, открове́нія громогла́сноє возвіще́ніє,","ра́дуйся, Та́йній Ве́чері чи́стою душе́ю приобща́вийся,","ра́дуйся, помисло́в іспові́данію прилежа́вий.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 7","ps":["Хотя́щу тебе́ Спа́су послі́довати, му́ченичеськаго житія́ ревни́тель показа́лся єси́, душе́ю нескве́рною же і ті́лом, і любо́вію боже́ственною ко Христу́. Сего́ ра́ди тя велича́єм, всесогла́сно пою́ще Бо́гові: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє одолі́ніє на неви́димия і ви́димия враги́ показа́вий, єго́же моли́твою і любо́вію стяжа́, і всеору́жіє смире́нія взем, істреби́л єси́ бісо́вськия ко́ви і тща́нія, Бо́гові же благода́рственная возопи́. Тім і ми прино́сим ті сицева́я:","Ра́дуйся, сві́та боже́ственноє храни́лище,","ра́дуйся, благоутро́бія Христо́ва вмісти́лище,","ра́дуйся, псалти́ри Дави́дови пі́ніє,","ра́дуйся, свята́го Арсе́нія умоле́ніє,","ра́дуйся, грі́шников ісправля́яй і ободря́яй,","ра́дуйся, ми́лованіє у Богоро́диці іспроша́яй,","ра́дуйся, главо́ подви́жников венцено́сная,","ра́дуйся, сі́не стра́ждущим росоно́сная,","ра́дуйся, водо́ живи́тельная претика́ющимся,","ра́дуйся, мо́сте, в жизнь ізводя́й утопа́ющих,","ра́дуйся, сто́лпе грі́шником па́дшим і укріпле́ніє,","ра́дуйся, разсла́бленним ти́хий о́дре і упокоє́ніє.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 8","ps":["Стра́нен бив в ми́рі, Паї́сіє, Го́спода возлюби́в і стра́сті твоя́ укроти́в Бо́жиєю благода́тію, ни́ні же я́ко зарни́ця облистава́єши о тебі́ вопію́щих немо́лчноє: Аллилу́я."]},{"h":"Ікос 8","ps":["Всяк, к тебі́ притека́яй, ніколи́же, о́тче Паї́сіє, неуті́шен оти́де. Но прося́й благода́ті дарова́ніє прийма́ше. Сего́ ра́ди і ми воспіва́єм ті сицева́я:","Ра́дуйся, лучено́сная омраче́нним звіздо́,","ра́дуйся, ка́ющихся наста́вниче і главо́,","ра́дуйся, афо́нськия бра́тії тяготи́ взе́мляй,","ра́дуйся, Всесвяти́я са́да цві́те преукраше́нний,","ра́дуйся, о благости́ні Христо́ві сладковеща́ніє,","ра́дуйся, моли́тви небе́сния мироуха́ніє,","ра́дуйся, ми́рові Мессі́ю провозвіща́яй,","ра́дуйся, піснь арха́нгелову ко Пресвяті́й воспіва́яй,","ра́дуйся, наде́ждою, ми́лостію і любо́вію пламене́яй,","ра́дуйся, во вра́жієй бра́ні боже́ственноє омове́ніє,","ра́дуйся, прия́вий дарова́ніє проро́чеськоє,","ра́дуйся, благоутро́бієм Отцю́ Небе́сному подо́бниче.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 9","ps":["Вся́кому єстеству́ пропові́дал єси́ сло́во, апо́столом уподобля́яся, раче́нієм же і любо́вію к бли́жнім просія́л єси́ я́ко со́лнце на землі́, прославля́я Святу́ю Тро́йцю: Аллилу́я."]},{"h":"Ікос 9","ps":["Слез пото́ки от душі́ мироточа́, се́рдцем о челові́ціх, стра́ждущих душе́ю і ті́лом, боля́ше. Сего́ ра́ди ни́ні і ми от душ на́ших піснопі́нія ті возсила́єм, в смире́нії вопію́ще прилі́жно:","Ра́дуйся, Єва́нгелія служи́телю неутоми́мий,","ра́дуйся, сві́щниче Трисо́лнечнаго Божества́ неугаси́мий,","ра́дуйся, я́ко по́стничества риста́лище соверши́вий,","ра́дуйся, я́ко смире́нієм кра́йнім іни́х предвари́вий,","ра́дуйся, во Афо́ні ві́ри сія́ніє,","ра́дуйся, Всесвяти́я сла́дкоє воспіва́ніє,","ра́дуйся, учи́телю сла́вний дія́нія же і зрі́нія,","ра́дуйся, я́ко велему́дре пости́же боже́ственноє виді́ніє,","ра́дуйся, Пречи́стия вертогра́да неусипа́ємий ді́лателю,","ра́дуйся, святи́м Лукиллія́ну, Пантелеї́мону і Євфи́мії собесе́дателю,","ра́дуйся, я́ко глас Богоотрокови́ці слу́хом усли́шал єси́,","ра́дуйся, я́ко Ту я́ві, а́ки на Ієрусали́мстій іко́ні, узрі́л єси́.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 10","ps":["Вели́чествіє со Елла́дою Каппадокі́ї і те́плий засту́пник єси́, Паї́сіє свя́те. Доброді́телей бо лі́ствицю богоуго́дно соверши́, к Тро́йці Святі́й непреста́нно поя́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ві́рним, о́тче Паї́сіє, а́нгельськоє бо житіє́ возлюби́в, по́двиги свої́ми Святі́й Тро́йці неуста́ннаго предстоя́нія ско́ро дости́же. Сего́ ра́ди пі́нія благода́рственная возсила́юще із глубини́ серде́ць і душ на́ших, смире́нно взива́єм:","Ра́дуйся, от Афо́на богоявле́нно ми́ру сія́яй,","ра́дуйся, краснопе́снивий гла́се, Сло́во провозвіща́яй,","ра́дуйся, многоча́дне, ми́луяй челові́чеськая боле́нія,","ра́дуйся, ослепле́нним стезе́й ісправле́ніє,","ра́дуйся, Неневе́стней Неві́сті ра́дованіє принося́й,","ра́дуйся, к Ца́рству Небе́сному путь удовля́яй,","ра́дуйся, кади́лу Ду́ха Бо́жия соіме́нне,","ра́дуйся, я́ко і зрак твой нам подає́ть утіше́ніє,","ра́дуйся, я́ко в ми́ра конці́х віща́нієм предвари́вий,","ра́дуйся, змі́я главу́ моли́твою сокруши́вий,","ра́дуйся, моле́нія і́менем Ісу́совим і среди́ ми́ра ді́лателю неуста́нний,","ра́дуйся, к Бо́жієй Ма́тері стяжа́вий любо́в несказа́нну.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 11","ps":["Пі́ніє Зижди́телю і Присноді́ві к боре́нієм я́же в нощі́ і во дні соплета́ше смире́нно, тім ся Бо́жия Ду́ха сосу́д показу́я. Ми же, Тро́йці Святі́й припа́дающе, тебе́ ра́ди поє́м і вопіє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ і мироуха́ніє благоче́стія, і любве́, і самоотверже́нія неісче́тнаго, і ісціле́ній то́чить свята́я па́м'ять твоя́, преподо́бне. Сего́ ра́ди потща́хомся всі моле́бними гла́си тебі́ возопи́ти:","Ра́дуйся, я́ко вся́кому указу́яй путь на небеса́,","ра́дуйся, я́ко ра́дости всіх ісполня́ють медото́чная твоя́ словеса́,","ра́дуйся, ізоби́льная от Афо́на ріко́ іскипа́ющая,","ра́дуйся, звіздо́ от Святи́я Го́ри, ві́рним путь озаря́ющая,","ра́дуйся, при́сноє за ни у Богоотрокови́ці хода́тайство,","ра́дуйся, а́нгельському житію́ прилежа́щим предста́тельство,","ра́дуйся, доброді́телей плодоно́снейшая лозо́,","ра́дуйся, о ми́рі к Престо́лу достига́ющая слезо́,","ра́дуйся, но́вий апо́столе, к ві́рі Христо́ві вся призива́яй,","ра́дуйся, Правосла́вія гла́се, мно́зі возсозида́яй,","ра́дуйся, дре́во всепло́дноє, Ма́терію Небе́сною напоя́ємоє,","ра́дуйся, елли́нов зна́м'я, в подсо́лнечній распростира́ємоє.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия істо́к тя позна́хом, о́тче, по успе́нії твоє́м, в не́мже ли́ци а́нгельстії весе́лія ісполня́хуся. Тім і ми, хода́тая о спасе́нії на́шем улучи́ти сподо́бльшіїся, ра́дуємся, взива́юще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще бе́здну чуде́с твої́х і терпели́вния твоя́ по́двиги, свя́те, от серде́ць ті сплета́єм а́нгельськая піснопі́нія, па́м'ять твою́ почита́єм благогові́йно і вопіє́м такова́я:","Ра́дуйся, наде́жди оте́чествію забве́нному ве́стниче,","ра́дуйся, о свобожде́нії Святи́я Софі́ї і гра́да Вели́каго пропові́дниче,","ра́дуйся, Царгра́д во упова́ніє но́воє ди́вно предуказа́вий,","ра́дуйся, хода́таю уде́ла сла́внаго от стран свої́х проізгна́нним,","ра́дуйся, не то́кмо єдиноплеме́нних путеводя́й, но і от іни́х язи́к приходя́щих,","ра́дуйся, я́ко сино́в Россі́йськия Це́ркве зіло́ люб'я́, благоуве́тливо прийма́ше,","ра́дуйся, пліне́нних о́тчин прореки́й обновле́ніє,","ра́дуйся, ми́ру блиста́ніє, ві́ри немо́лчноє возглаше́ніє,","ра́дуйся, я́ко зна́менія време́н разуме́вий,","ра́дуйся, Открове́нія Іоа́ннова таї́нниче богодухнове́нний,","ра́дуйся, я́ко апо́стол, явле́й обітова́нія,","ра́дуйся, ізбавле́нія Асі́ї Ма́лия упова́ніє.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 13","ps":["О преподо́бне о́тче Паї́сіє, новоцве́те благоуха́нний, ізра́стший во времена́ послі́дняя, умоли́ Христа́ Бо́га спасти́ся душа́м о тебі́ воспіва́ющих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел показа́лся єси́ во уді́лі Богоро́диці ізбра́ннім, і нам хода́тай теплі́йший пред Бо́гом, Паї́сіє о́тче, ті́мже та́ко тя воспіва́єм:","Ра́дуйся, Каппадокі́ї доброво́нноє ми́ро,","ра́дуйся, ви́шняго жи́тельства о́браз яви́вий,","ра́дуйся, Асі́ї Ма́лия процвіте́ніє,","ра́дуйся, свята́го Арсе́нія похвале́ніє,","ра́дуйся, во фарасіо́тіх приснопіва́ємий,","ра́дуйся, іноку́ющих пра́вило,","ра́дуйся, ве́ліє Елла́ди і ві́ри храни́ло,","ра́дуйся, Каппадокі́йськаго ро́да світи́ло,","ра́дуйся, Византі́ї боже́ственная о́трасле,","ра́дуйся, добро́то Афо́на і о́рле,","ра́дуйся, земни́й а́нгеле, ве́стниче на землі́,","ра́дуйся, челові́че небе́сний, пребива́яй на Небесі́.","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Кондак 1","ps":["Ізбра́ннаго Панагу́ди подви́жника і арома́тницю благоуха́нную, Каппадокі́йськоє прозябе́ніє і предста́теля неуси́пнаго, да воспої́м согла́сно. А́нгельському бо житію́ подража́я, Тро́йці Святі́й благоугоди́, тім і зове́м:","Ра́дуйся, преподо́бне Паї́сіє, ди́вний наро́да Бо́жия уті́шителю."]},{"h":"Молитва","ps":["О святи́й преподо́бний і богоно́сний о́тче наш Паї́сіє, возлю́бленний наш покрови́телю і богому́дрий наста́вниче, лі́ствицею доброді́телей от землі́ в Небе́сноє Ца́рство восше́дий і благода́ть прия́вий во є́же хода́тайствовати о нас пред Престо́лом Всеми́лостиваго Го́спода на́шего. Мо́лим тя отврати́ти ни от путі́ гріхо́внаго і научи́ти ни Го́сподеві соверше́нни плоди́ покая́нія і обновле́нія во Христі́ душ на́ших приноси́ти.","Ти, святи́й о́тче, во дні житія́ земна́го мно́зі тя́жки болі́зні і неду́ги неісці́льния уврачева́вий і душі́ гріхми́ і скорбми́ стра́ждущих ісціли́вий, ни́ні предстоя́ Бо́гу, Того́ милосе́рдіє к нам приклони́, да твоєго́ предста́тельства ра́ди любо́вію чту́щих святу́ю па́м'ять твою́ ісціли́ть, да́руєть крі́пость во іскуше́ніїх, му́жество в борбі́ с ду́хом зло́би, і́щущим ві́чній поги́белі на́шей, да да́руєть нам проще́ніє всіх на́ших гріхо́в, ї́хже от ю́ности на́шея да́же до настоя́щаго дне по́мислом, сло́вом і ді́лом соверши́хом, да научи́ть ни, я́же нам подоба́єть твори́ти, я́ко да ви́ну Єму́ і бли́жнім с любо́вію і смире́нієм послу́жим.","Єй, о́тче святи́й, наста́ви нас, во о́браз житія́ твоєго́, і́же любве́ і милосе́рдія іспо́лнено бисть, уз гріхо́внаго жи́тельства разріши́вшеся, к Небе́сним Черто́гам взи́ти, іді́же да восхва́лим Всемилосе́рднаго Триіпоста́снаго Го́спода на́шего во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Боже́ственния любве́ огнь приє́мий, / превосходя́щим по́двигом вда́лся єси́ весь Бо́гові, / і утіше́ніє мно́гим лю́дем бил єси́, / словеси́ боже́ственними наказу́яй, / моли́твами чудотворя́й, / Паї́сіє Богоно́се, / і ни́ні мо́лишися непреста́нно // о всем ми́рі, преподо́бне."]},{"h":"Кондак, глас 8","ps":["А́нгельськи на землі́ пожи́вий, / любо́вію просія́л єси́, преподо́бне Паї́сіє, / мона́хов вели́коє утвержде́ніє, / ві́рних к житію́ свято́му вождь, / вселе́нния же утіше́ніє сладча́йшеє показа́лся єси́, / сего́ ра́ди зове́м ті: // ра́дуйся, о́тче всеми́рний."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Паї́сіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст великомученику Іоанну Новому, Сочавському","e":"Akathist to the Great Martyr John the New of Suceava","secs":[{"h":"Кондак 1","ps":["Ізбра́нному защи́тнику, побори́телю і низложителю нече́стія, новоявленному му́ченику і честно́му во́їну Христо́ву, я́ко со́лнце Восто́чній Це́ркві возсія́вшему, і весе́лія ві́рних іспо́лнившему, ни́ні от всея́ душі́ благода́рственная і похва́льная пі́нія прино́сим, с любо́вію пою́ще:","Ра́дуйся, Іоа́нне, великому́чениче Христо́в."]},{"h":"Ікос 1","ps":["А́нгелом возлю́блено бисть богоуго́дноє житіє́ твоє́, страда́нія Христо́ва нося́щу ті, Іоа́нне. І́бо в тілесі́ сий, житіє́ а́нгельськоє на землі́ пожи́л єси́, ми́лостинями і непреста́нними моли́твами, та́же і страда́нії. Ті́мже ми по достоя́нію сія́ похва́льная прино́сим ті:","Ра́дуйся, я́ко поще́нії і непреста́нними твої́ми моли́твами уподо́бился єси́ А́нгелом;","ра́дуйся, я́ко ми́лостинями і слеза́ми твої́ми ужаси́л єси́ де́монов.","Ра́дуйся, я́ко уті́шил єси́ скорб'я́щия;","ра́дуйся, я́ко помога́л єси́ боля́щим.","Ра́дуйся, я́ко в ме́ртвенном тілесі́ показа́лся єси́ земни́й А́нгел;","ра́дуйся, я́ко мудрова́нієм бил єси́ челові́к небе́сний.","Ра́дуйся, я́ко от благові́рних роди́телей проізше́л єси́;","ра́дуйся, я́ко правосла́вную ві́ру в коне́ць сохрани́л єси́.","Ра́дуйся, от сла́внаго гра́да Трапезунда проізрастший;","ра́дуйся, я́ко вся́кими доброді́телями соверше́нно удобри́лся єси́.","Ра́дуйся, я́ко купе́ць іску́сен на мо́рі показа́лся єси́;","ра́дуйся, я́ко купечество твоєя́ душі́ до́брі упра́вил єси́.","Ра́дуйся, Іоа́нне, великому́чениче Христо́в."]},{"h":"Кондак 2","ps":["Ви́дя, му́чениче Христо́в, лука́вство дия́воле, іноверним возникшеє на тя, во є́же би удали́ти тя от правосла́вния ві́ри, но да́нною ті от Бо́га прему́дростію, позна́л єси́ кова́рства волхва́, бла́гостію Ви́шняго не уловле́н о́ними, преби́л єси́ і та́ко воспі́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом, просвіще́нним сви́ше, позна́вши, треблаже́нне, наноси́мую на тя єретико́м Реїзом клевету́, к єпа́рху Белграда язичнику, а́ки би ти ізво́лил отступи́ти от і́стинния христия́нськия ві́ри; і а́ще о́ний вся́ким о́бразом преклоняше тя, но ти ніка́коже побіди́м преби́л єси́. Ті́мже по достоя́нію сли́ши на́ми приноси́мая сія́:","Ра́дуйся, я́ко лжи́ваго Реїза обличи́л єси́;","ра́дуйся, подо́бно столпу́ непоколеби́м преби́л єси́.","Ра́дуйся, я́ко ле́сти єпа́рха нівочто́же вміни́л єси́;","ра́дуйся, я́ко ві́рних в благоче́стії укріпи́л єси́.","Ра́дуйся, я́ко пожре́ти со́лнцю і денни́це не восхоті́л єси́;","ра́дуйся, я́ко сим нечести́вому жрецю́ поруга́лся єси́.","Ра́дуйся, я́ко Созда́теля сих Єди́наго Бо́га в Тро́йці пропові́дал єси́;","ра́дуйся, я́ко христия́нськия ві́ри не поху́лил єси́.","Ра́дуйся, я́ко о́ная світи́ла твар би́ти, а не бо́ги рекл єси́;","ра́дуйся, сего́ ра́ди от тиран умученний.","Ра́дуйся, я́ко єпа́рха пред всі́ми обличи́вий;","ра́дуйся, того́ к благоче́стію преклони́ти тщавийся.","Ра́дуйся, Іоа́нне, великому́чениче Христо́в."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Свята́го Ду́ха укріпле́н сий, со мно́гим дерзнове́нієм віща́л єси́ іге́мону, во́їне Ісу́сов: не наді́йся, о тирані, я́ко когда́-ли́бо от Христа́ моєго́ отпаду́, і тва́ри па́че не́жели Созда́телю поклоню́ся! Да не бу́деть сіє́, до́ндеже диха́ніє моє́ іспущу́, ті́мже ве́ліїм гла́сом возопи́л єси́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в ли́ці твоє́м, страстоте́рпче Христо́в, весе́ліє, єгда́ глаго́лал єси́ к єпа́рху сія́, і не бі в тебі́ опасства, ні боя́зні. Он же не моги́й терпі́ти сего́, возгорі́ся я́ростію, повелі́ принести́ мно́гія палиці і обнажи́ти тя; ти же я́ко ін обрі́лся єси́, сего́ ра́ди і ми вопіє́м ті сія́:","Ра́дуйся, я́ко, єгда́ уви́діл єси́ палиці, не убоя́лся;","ра́дуйся, я́ко от виді́нія сих па́че і па́че тирану воспротивился єси́.","Ра́дуйся, я́ко ве́тхия оде́жди на землі́ совле́клся єси́;","ра́дуйся, я́ко в порфи́ру нетлі́нія на небесі́ обле́клся єси́.","Ра́дуйся, я́ко сме́ртних муче́ній не устраши́лся єси́;","ра́дуйся, я́ко небреже́нієм о сих мучи́тель зіло́ му́чим бисть.","Ра́дуйся, я́ко сим єго́ пред предстоя́щими обличи́л єси́;","ра́дуйся, я́ко раба́ Бо́жия себі́ би́ти іспові́дал єси́.","Ра́дуйся, я́ко содержа́й отеческиє уче́нія;","ра́дуйся, я́ко же́ртви ігемонових бого́в не прия́л єси́.","Ра́дуйся, я́ко нечести́ву без закосні́нія му́чити тя рекл єси́;","ра́дуйся, я́ко ті́ми муче́нії в Ца́рство Небе́сноє посла́ тя.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й нанесе́ на тя, о многострада́льче, єгда́ ізре́кл єси́, я́ко Творцю́ поклоню́ся, а не созда́нію, і, єгда́ нечести́вий мучи́тель твоя́ глаго́ли усли́ша, є́же би преклони́ти тя к своєму́ хоті́нію отча́яся, дивнім і юро́дивим гні́вом возгорі́ся і нача́т тя му́чити. Ти же, му́чениче Христо́в, му́жественні терп'я́щи, укріпля́ющу тя Бо́гу с весе́лієм піл єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша ві́рнії, я́ко бисть се́рдце твоє́ адама́нтово, єгда́ любве́ ра́ди Жела́ємаго тобо́ю пострада́л єси́, блаже́нне му́чениче Христо́в, нівочто́же вміни́в муче́нія, благода́тію Христо́вою укріпля́єм, гнів мучи́теля а́ки ядови́таго а́спида попра́в, і на тяжчайшия муче́нія ра́достно поте́кл єси́; сего́ ра́ди сли́шиши от нас сія́:","Ра́дуйся, я́ко растягоша тя на землі́ на муче́нія обнаже́нна;","ра́дуйся, я́ко у́мния о́чі го́ре на не́бо імі́вий.","Ра́дуйся, єгда́ суковатими па́лицями без ми́лости біє́н бив, не ізнемо́гл єси́;","ра́дуйся, я́ко мучи́телі лю́ті мучившії тя ослабі́ша.","Ра́дуйся, я́ко раздробле́ніє твоєго́ тілесе́ до́блественне стерпевий;","ра́дуйся, я́ко сим мучи́теля на гнів подви́гнувий.","Ра́дуйся, я́ко от многобієнія к палицям прилипающая плоть твоя́ го́ре возноша́шеся;","ра́дуйся, я́ко сим собра́л єси́ на удивле́ніє А́нгелов.","Ра́дуйся, кро́вію твоє́ю зе́млю обагривий;","ра́дуйся, сатану́ нога́ми попра́вий.","Ра́дуйся, за сіє́ Влади́ці Христа́ возблагодаривий;","ра́дуйся, я́ко Он тя і на тяжчайшия муче́нія укріпи́л єсть.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́, путеводи́вшей дре́вле волхво́в к пра́ведному Со́лнцю, подо́бен бил єси́, великому́чениче Христо́в, приводя́ к позна́нію і́стиннаго Бо́га, Єму́же ти моли́лся єси́, мучи́тель же па́че гні́ва іспо́лнися і лю́ті тя му́чиша, я́ко і муче́нія му́жественні претерпіва́я, із глубини́ се́рдця взива́л єси́ Христу́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя ві́рнії, по повелі́нію ігемонову, вери́гами свя́зана, во́їне Христо́в Іоа́нне, вве́ржена в темни́цю, оста́виша тя на тяжчайшия муче́нія, і всю плоть твою́ от біє́нія раздробле́ну, ве́лією ско́рбію об'яти би́вше, в други́й день па́ки тя на суд предста́виша і пред мучи́телем стал єси́ лице́м весе́лий, нечести́вий же зіло́ удиви́ся і ужасе́ся, сего́ ра́ди і ми тя ублажа́юще зове́м:","Ра́дуйся, я́ко сим дия́вола устраши́л єси́;","ра́дуйся, я́ко в темни́ці заключе́нний обита́вий.","Ра́дуйся, я́ко по сих в пресві́тлий рай всели́лся єси́;","ра́дуйся, я́ко, тяжча́йшими ра́нами по всему́ тілесі́ ураненний, весе́лий обрі́лся єси́.","Ра́дуйся, я́ко неі́стовий мучи́тель сему́ удиви́ся;","ра́дуйся, о ісціле́нії ран на твоє́м тілесі́ небреги́й.","Ра́дуйся, я́ко челові́к твой вні́шній разруши́ся;","ра́дуйся, я́ко вну́тренній обнови́ся.","Ра́дуйся, я́ко тяжчайшия муче́нія на тя мучи́телем вимисленна;","ра́дуйся, о́ния с любовю приє́мий.","Ра́дуйся, я́ко сим душа́ твоя́ красні́йше процвіте́.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 6","ps":["Пропові́дал єси́, достосла́вне му́чениче Христо́в, хотя́щую прийти́ на тя Бо́жию благода́ть, о ней же ми́слію внима́я, до́блественне терпі́л єси́ страда́нія, строга́ніє і растерза́ніє пло́ті твоєя́, сего́ ра́ди мно́жає іспо́лнися гні́ва юродив тиран, я́ко дикий звір воскрича́, повелі́ жесточа́йше му́чити тя і без ми́лости би́ти; сему́ же би́вшу, вопія́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий му́ченичеським по́двигом, страстоте́рпче Христо́в Іоа́нне, та́ко бо бил єси́ му́чим, я́ко і вну́тренняя разсі́деся, і ізнемого́ша мучи́телі от неми́лостивих ударе́ній, єди́ни по други́м преміня́єми; ти же, до́блій во́їне, не преміни́л єси́ ра́зума к рачи́телю своєму́ Го́споду Ісу́су, но па́че моли́лся єси́, да да́руєть ті до конця́ терпі́ти. Ми же, моли́твами твої́ми защищающієся, вопіє́м ті сія́:","Ра́дуйся, я́ко ти, за Христа́ без ми́лости мучимий, не пременился єси́ в терпі́нії;","ра́дуйся, я́ко бію́щії тя пременяхуся.","Ра́дуйся, я́ко умо́м в Бо́зі, укріпля́ющем тя, стоя́л єси́;","ра́дуйся, я́ко Христо́с благода́тію Свята́го Ду́ха сви́ше посіти́ тя.","Ра́дуйся, я́ко всі на позо́рищі собра́вшіїся за суровство́ мучи́теля укори́ша;","ра́дуйся, я́ко тебі́ с Небесе́ нерукотворе́нная оде́жда ізткася.","Ра́дуйся, я́ко і мучащії тя мучи́телі ізнемого́ша,","ра́дуйся, я́ко ви́дівшії тя мно́гія печа́лі іспо́лнишася.","Ра́дуйся, я́зви Христо́ви на ті́лі своє́м носи́вий;","ра́дуйся, я́ко Христо́с неув'ядаєм віне́ць на небесі́ тебі́ угото́ва.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 7","ps":["Хотя́ше, треблаже́нне му́чениче, мучи́тель к своєму́ хоті́нію приклонити тя, не імі́я же люті́йших муче́ній, повелі́ привести́ свирі́паго коня́, і святи́я твоя́ но́зі ко о́шибу єго́ крі́пко прив'яза́ти, і по всіх у́лицях гра́да влачити. Тебі́ же, во́їне Христо́в, влачиму би́вшу, позо́р бил єси́ А́нгелом і челові́ком, пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя по благоче́стії ревни́теля ви́дя нечести́вий, уми́сли необи́чну на тя му́ку, страстоте́рпче Христо́в: влачиму бо ті би́стро су́щу, ча́сти от тілесе́ твоєго́ на ка́меніх отреваємі, оставахуся, глава́ сокрушашеся; ві́рнії же, видевшиє тя, ве́ліїм сожаленієм об'яти би́вше, ти же, го́ре ум к Бо́гу імі́яй, в та́йні моли́лся єси́. Сего́ ра́ди і ми раби́ твої́ удивля́шеся, сія́ похва́льная воспису́єм ті:","Ра́дуйся, я́ко муче́нієм твої́м бил єси́ пропові́дник Святи́я Тро́йці,","ра́дуйся, я́ко крі́пким терпі́нієм твої́м бил єси́ благи́я ві́ри основа́ніє.","Ра́дуйся, я́ко бил єси́ возже́н огне́м неізрече́нния к Бо́гу любве́;","ра́дуйся, я́ко Єго́ ра́ди претерпі́л єси́ раздробле́ніє твоєя́ пло́ті.","Ра́дуйся, я́ко бил єси́ позо́р умиле́нія ві́рним;","ра́дуйся, я́ко глава́ твоя́ влачи́ма, Христа́ ра́ди, о ка́меніє сокрушашеся.","Ра́дуйся, я́ко моли́твами твої́ми глава́ невидимого врага́ сотре́ся,","ра́дуйся, я́ко істе́кшею ті кро́вію земля́ обагри́ся.","Ра́дуйся, я́ко Христо́с во Ца́рствії Небе́снім віне́ць нетлі́нія тебі́ дарова́;","ра́дуйся, я́ко Єго́ ра́ди на землі́ пострада́л єси́.","Ра́дуйся, я́ко с Ним на Небесі́ ца́рствуєши.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 8","ps":["Стра́нную си́лу проклятий род іуде́йський ви́дів в тебі́, му́чениче Христо́в, єгда́ свирі́пим ко́нем влачаше тя по улиці: єди́ни посмевашася ті, друзі́ї скривляху лиця́ своя́, є́же імі́яху в рука́х мета́ша в тя, о́вії же посміва́хуся, неподо́бния ді́яху. Ти же, до́блій во́їне Христо́в, со благодаре́нієм терпі́л єси́, укріпля́ющему тя Бо́гу непреста́нно поя́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ Ісу́са імі́я в блаже́нній душі́ і у́ме твоє́м, страстоте́рпче, і наконе́ць тече́нія по́двига твоєго́ дости́гши, єди́н от насмехающихся тебі́ іуде́й потече́ во свой дом, взем меч обнаже́н і о́ним честну́ю і святу́ю главу́ твою́ отсіче́ і сим сві́тлую твою́ ду́шу в ру́ці тобо́ю рачи́маго Христа́ предаде́. Ті́мже і от нас сли́шиши сія́:","Ра́дуйся, я́ко от іуде́й посмія́ніє і поруга́нія Христа́ ра́ди прия́л єси́;","ра́дуйся, я́ко сим поруганному і́ми Ісу́су послі́довал єси́.","Ра́дуйся, я́ко от іуде́й бил єси́ ударя́єм;","ра́дуйся, я́ко же і Христо́с нас ра́ди грі́шних, ти же Христа́ ра́ди муки́ до́блі терпі́л єси́.","Ра́дуйся, я́ко проклятий род мече́м главу́ твою́ отсіче́;","ра́дуйся, я́ко Ісу́с пресві́тлим вінце́м главу́ твою́ увінча́.","Ра́дуйся, я́ко с му́ченици ку́пно во оби́теліх небе́сних прославля́єшися;","ра́дуйся, я́ко ми ві́рнії імі́єм тя при́снаго хода́тая к Бо́гу.","Ра́дуйся, я́ко моле́нія твоя́ суть прия́тна Бо́гу;","ра́дуйся, я́ко па́м'ять твоя́ в Це́ркві Христо́вой честна́ єсть.","Ра́дуйся, я́ко і́м'я твоє́ услажда́єть всіх, правосла́вную ві́ру почита́ющих.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 9","ps":["Ви́дівше ві́рнії по отсіче́нії честни́я глави́ твоєя́ і ізше́ствії святи́я твоєя́ душі́ от ті́ла, пресла́вне му́чениче, лежа́щую плоть твою́ со отсеченною главо́ю, непогребенную і презираємую, сожалеваху; наста́вшей же нощі́ пресла́внаго чудесе́, столп до небесе́ над твої́ми святи́ми моща́ми ви́дін бисть: свіщи́ горя́ху і му́жіє в ри́зи белиє облече́нни кадя́ще о́крест тілесе́ твоєго́, пою́ще неізрече́нния і свяще́нния словеса́, с ни́ми же і ти воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я красноречива не мо́гуть ізрещи́ пі́ніє, от А́нгел би́вшеє поємо о́крест святи́х твої́х моще́й, треблаже́нне му́чениче; єди́н же от іуде́й сіє́ сли́шаще, помишля́ше земни́х би́ти челові́к, напряже́ лук пусти́ стрілу́, но нічто́же у́спе окая́нний сей, всім бо бисть сожаленія зрі́лище. Тім же і ми о сицево́м чудеси́ удивишеся зове́м ті:","Ра́дуйся, досто́йні надгро́бнаго а́нгельськаго пі́нія;","ра́дуйся, я́ко Христо́с с Небесе́ призрі́ на святи́я твоя́ мо́щі.","Ра́дуйся, я́ко ви́дін бисть над твої́ми святи́ми моща́ми столп о́гненний до небесе́;","ра́дуйся, я́ко сей мно́гих ужаси́.","Ра́дуйся, я́ко о́ний іудеян Бо́жиїм мщенієм нака́зан бисть;","ра́дуйся, я́ко сіє́ во ве́лію сла́ву святи́х твої́х моще́й соді́яся.","Ра́дуйся, я́ко лю́діє на позо́р о́наго іудеянина стеко́шася;","ра́дуйся, я́ко по іспові́данії єго́ пред всі́ми от наказа́нія спасе́ся.","Ра́дуйся, я́ко уві́давши мучи́тель о чудеси́ сем, зіло́ ужасе́ся;","ра́дуйся, я́ко христия́нам сего́ ра́ди погребсти́ тя повелі́.","Ра́дуйся, я́ко це́рков прия́т погребе́нноє, честно́є ті́ло твоє́;","ра́дуйся, я́ко свята́я душа́ твоя́ во оби́теліх небе́сних всели́ся.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 10","ps":["Хотя́шеся, многострада́льне му́чениче Христо́в, оклеветателю і преда́телю твоєму́ честно́є і многострада́льноє ті́ло твоє́ похи́тити і во своє́ оте́чество принести́, но ти, во́їне Христо́в, ско́ро ієре́ю о́ния це́ркві во сні яви́лся і о сем возвісти́л єси́ єму́; он же к це́ркві прите́к і честни́я твоєя́ мо́щі із рук єго́ от'ят, с ра́достію поя́: Аллилу́я."]},{"h":"Ікос 10","ps":["Єгда́, му́чениче Христо́в, честни́я і святи́я твоя́ мо́щі от іноро́дних Бо́жиїм про́мислом спасо́шася, во олтарі́ поста́влени би́ша близ святи́я трапе́зи, іді́же А́гнець всегда́ за спасе́ніє на́ше жре́ться, Єму́ же і ти же́ртва жива́я принесла́ся єси́. Ві́рнії же о сем уведавше, просла́виша всеще́драго Бо́га, прославля́ющаго святи́я Своя́, с ни́ми же і ми похва́льния пі́нія сі́ї прино́сим ті:","Ра́дуйся, я́ко святи́я твоя́ мо́щі неукрадени і невреди́ми преби́ша;","ра́дуйся, я́ко інові́рний посра́млен і тощ прогна́ся.","Ра́дуйся, я́ко ієреями Це́ркві честни́я твоя́ мо́щі во олтари́ положени́ би́ша;","ра́дуйся, я́ко о сем возра́довашася ві́рнії.","Ра́дуйся, я́ко і́ми непреста́нно чудеса́ содіва́ються;","ра́дуйся, я́ко і́ми і де́мони от мно́гих ізгоними бива́ють.","Ра́дуйся, я́ко столп о́гненний с небесе́ над ни́ми явля́шеся;","ра́дуйся, я́ко снисходиша к ним А́нгели.","Ра́дуйся, мно́жицею благоуха́ніє от о́них ісхо́дить;","ра́дуйся, я́ко вся́кия болі́зні тобо́ю ісціля́ються.","Ра́дуйся, я́ко о содіва́ємих тобо́ю чуде́с вість повсю́ду про́йде;","ра́дуйся, я́ко до коне́ць землі́, Бо́гу та́ко благоволи́вшу, твоя́ вість дости́же.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 11","ps":["Пі́нія похвальнаго ність по достоя́нію похвали́ти благолі́піє благода́ті чуде́с, я́коже от честни́х і святи́х твої́х моще́й бива́ють, достойнославне му́чениче Христо́в; не то́чію бо лю́діє, но і цари́ і кня́зі чтуть і поклоня́ються і лобиза́ють тя с любо́вію. Ти же, я́ко іми́й дерзнове́ніє к Бо́гу і Влади́ці всіх, іспроси́ нам всім в сей жи́зні тіле́снаго здра́вія, в бу́дущем же ві́ці душе́внаго спасе́нія, любо́вію с тобо́ю пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная свіща́ суть честни́я і святи́я твоя́ мо́щі, многострада́льне му́чениче Христо́в Іоа́нне, на сві́щниці Це́ркви Христо́ви поста́влени, просвіща́ющия мно́гоє вре́м'я мі́сто, на не́мже страда́л єси́, также благослове́нієм Бо́жиїм, тща́нієм же благочести́ваго господаря пренесенна в Молдовлахію, непреста́нно сві́тять, і всім с ві́рою і любо́вію прибегающим ко о́нім лучи́ чуде́с ізлива́ють. Ми же сія́ благода́ті прича́стници би́вше, прино́сим ті сія́:","Ра́дуйся, луче́ невече́рняго і ми́сленнаго сві́та;","ра́дуйся, я́ко всю поднебе́сную просвіща́єши.","Ра́дуйся, пресві́тлия денни́це невече́рняго дне;","ра́дуйся, я́ко і от нас ізволе́нієм Бо́жиїм бил єси́ удале́нний.","Ра́дуйся, я́ко і та́мо мно́гоє вре́м'я луча́ми благода́ті Христо́ви просвіща́л єси́;","ра́дуйся, я́ко смотре́нієм Бо́жиїм обра́тно па́ки к нам прише́л єси́.","Ра́дуйся, сми́рно, Це́рков Христо́ву облагоухающая:","ра́дуйся, я́ко всіх приходя́щих к святи́м твої́м моща́м небе́снаго твоєго́ благоуха́нія сподобляєши.","Ра́дуйся, сосу́де ми́ра Христо́ва неістощаєм і неізче́тних болі́зней врачева́ній содержа́щ;","ра́дуйся, всім просящим благ ізобильних пода́телю.","Ра́дуйся, я́ко благода́ть і сла́ва Царя́ Небе́снаго на тя ізлія́ся;","ра́дуйся, я́ко і ти благода́ть ісціле́ній от всіх болі́зней ізоби́льно всім подає́ши.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 12","ps":["Благода́ть прия́л єси́ от Бо́га, всехва́льне і многострада́льне му́чениче, ісціля́ти вся́кия болі́зні і неду́ги душевниє і тіле́сниє. Тім же ни́ні предстоя́щи Христу́, во страданях твої́х укріпи́вшему тя, не преста́ни ходатайствовать всім нам прося́щи тіле́снаго здра́вія і душе́внаго спасе́нія, со благогові́нієм і любо́вію чту́щих святу́ю па́м'ять твою́, пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м, почита́єм, сла́вим, ублажа́єм многоболі́зненния страда́нія твоя́, терпі́ніє до конця́, до́блественне, под'єм і тве́рдость адамантову несравне́нно превзошед, я́же показа́л єси́ в тілесі́ твоє́м, за ня́же подвигополо́жник Христо́с Госпо́дь на землі́ і на Небесі́ просла́ви і нам недосто́йним дарова́ тя, свя́те побідоно́сче, великому́чениче Христо́в Іоа́нне, вопію́ще ті, треблаже́нне, сія́:","Ра́дуйся, я́ко і на мі́сті пребива́єши і обита́єши с во́ї небе́сними;","ра́дуйся, я́ко провожден бил єси́ десни́цею Царя́ Христа́ со сла́вою і че́стію пресла́вно вінча́лся єси́.","Ра́дуйся, я́ко по многостраданії твоє́м прия́ тя Госпо́дь во упокоє́нія ві́чная;","ра́дуйся, я́ко сокро́вище некра́домоє на Небесі́ приобрі́л єси́.","Ра́дуйся, я́ко мзда твоя́ мно́га во сві́тлостіх святи́х тебі́ угото́вася;","ра́дуйся, во іскуше́ніях і ну́ждах те́плий предста́телю.","Ра́дуйся, ра́дости і ві́чния сла́ви всещедрейший нам хода́таю;","ра́дуйся, я́ко тобо́ю наді́ємся получи́ти ві́чная бла́га.","Ра́дуйся, Іоа́нне великому́чениче Христо́в."]},{"h":"Кондак 13","ps":["О, многострада́льче святи́й, великому́чениче і побідоно́сче Христо́в Іоа́нне. Прийми́ сіє́ от скве́рних усте́н на́ших со умиле́нієм приноси́моє Ті моле́ніє і от всіх неду́г душе́вних і тіле́сних, от враг ви́димих і неви́димих, і от ві́чния муки́, благоприя́тними моли́твами Твої́ми нас ізба́ви, да с тобо́ю ку́пно в бу́дущем ві́ці во оби́теліх святи́х поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом возлю́блено бисть богоуго́дноє житіє́ твоє́, страда́нія Христо́ва нося́щу ті, Іоа́нне. І́бо в тілесі́ сий, житіє́ а́нгельськоє на землі́ пожи́л єси́, ми́лостинями і непреста́нними моли́твами, та́же і страда́нії. Ті́мже ми по достоя́нію сія́ похва́льная прино́сим ті:","Ра́дуйся, я́ко поще́нії і непреста́нними твої́ми моли́твами уподо́бился єси́ А́нгелом;","ра́дуйся, я́ко ми́лостинями і слеза́ми твої́ми ужаси́л єси́ де́монов.","Ра́дуйся, я́ко уті́шил єси́ скорб'я́щия;","ра́дуйся, я́ко помога́л єси́ боля́щим.","Ра́дуйся, я́ко в ме́ртвенном тілесі́ показа́лся єси́ земни́й А́нгел;","ра́дуйся, я́ко мудрова́нієм бил єси́ челові́к небе́сний.","Ра́дуйся, я́ко от благові́рних роди́телей проізше́л єси́;","ра́дуйся, я́ко правосла́вную ві́ру в коне́ць сохрани́л єси́.","Ра́дуйся, от сла́внаго гра́да Трапезунда проізрастший;","ра́дуйся, я́ко вся́кими доброді́телями соверше́нно удобри́лся єси́.","Ра́дуйся, я́ко купе́ць іску́сен на мо́рі показа́лся єси́;","ра́дуйся, я́ко купечество твоєя́ душі́ до́брі упра́вил єси́.","Ра́дуйся, Іоа́нне, великому́чениче Христо́в."]},{"h":"Кондак 1","ps":["Ізбра́нному защи́тнику, побори́телю і низложителю нече́стія, новоявленному му́ченику і честно́му во́їну Христо́ву, я́ко со́лнце Восто́чній Це́ркві возсія́вшему, і весе́лія ві́рних іспо́лнившему, ни́ні от всея́ душі́ благода́рственная і похва́льная пі́нія прино́сим, с любо́вію пою́ще:","Ра́дуйся, Іоа́нне, великому́чениче Христо́в."]},{"h":"Молитва","ps":["Святи́й, сла́вний і всехва́льний великому́чениче Христо́в Іоа́нне, несумненний хода́таю на́шего спасе́нія. Мо́лим тя раби́ твої́, собра́нії днесь в Боже́ственнім твоє́м хра́ме і ра́ці святи́х моще́й поклоняющієся; ми́лостив бу́ди я́коже нам, та́ко і дале́че отстоящим і на по́мощ тя призива́ющим і му́ченичеськия твоя́ страда́нія похвала́ми ублажающим. Іспроси́ нам всім у многоми́лостиваго Го́спода Бо́га і Спа́са на́шего Ісу́са Христа́ проще́нія і оставле́нія гріхо́в, до сего́ дне і часа́ соді́янних на́ми. Сохрани́ нас невреди́мих от всіх ко́зней лука́ваго і ненаві́тну жизнь на́шу соблюди́ от всіх зол душе́вних і тіле́сних, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Житіє́ на землі́ до́брі окормля́я, страда́льче, / ми́лостинями, і ча́стими моли́твами, і слеза́ми, / па́ки же ко страда́нію му́жеськи устреми́вся, / пе́рськоє обличи́л єси́ нече́стіє. / Ті́мже Це́ркве бил єси́ утвержде́ніє / і христия́н похвало́, // Іоа́нне приснопа́м'ятне."]},{"h":"Кондак, глас 4","ps":["Морську́ю пла́вая пучи́ну ку́плею, / от восто́ка тща́лся єси́ к сі́веру, / но Бо́гу призва́вшу тя, / я́коже Матфе́й ми́тницю, ти же ку́плю оста́вль / і Тому́ послі́довал єси́ кро́вію му́ченія, / вре́менними іскупи́в непроходи́мая, // і віне́ць прия́л єси́ непобіди́мий."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й Іоа́нне, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ // претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст святому преподобному Стиліану Пафлагонському","e":"Akathist to our Venerable Father Stylianos of Paphlagonia","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і уго́дниче Христо́в, ско́рий помо́щниче і моли́твенниче наш, преподо́бне о́тче Стилія́не, прославля́я просла́вльшаго тя Го́спода, похва́льная пі́нія прино́сим ті, чту́щії святу́ю па́м'ять твою́. Ти же, предстоя́ пред Престо́лом Вседержи́теля, воздви́гни о нас, грі́шних, многомо́щния моли́тви твоя́, взива́ющих ті:","Ра́дуйся, преподо́бне о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Созда́тель єще́ от утро́би ма́тернія ізбра́ тя, преподо́бне Стилія́не, чу́дним житіє́м свої́м на землі́ прославля́ти Тро́йцю Святу́ю, по блаже́нній же кончи́ні твоє́й учини́ тя со святи́ми А́нгели воспіва́ти Єму́ піснь сладча́йшую на небесі́. Ми же, таково́му Бо́жию благоволе́нію о тебі́ ра́дуяся, пісносло́вим тя:","Ра́дуйся, Святи́я Це́ркви похвало́.","Ра́дуйся, Пафлаго́нії крі́пкий сто́лпе.","Ра́дуйся, до́браго воспита́нія цві́те благоуха́нний.","Ра́дуйся, Боже́ственнаго ізбра́нія сосу́де благослове́нний.","Ра́дуйся, Го́спода от ю́ности возлюби́вий.","Ра́дуйся, ві́ру і любо́во в се́рдці своє́м возрасти́вий.","Ра́дуйся, целому́дріє душі́ своєя́ сохрани́вий.","Ра́дуйся, смире́ніє вели́коє стяжа́вий.","Ра́дуйся, пусти́ні вели́кий моли́твенниче.","Ра́дуйся, благода́тний і́ноков путевождю́ і наста́вниче.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя чистоту́ се́рдця твоєго́, о́тче Стилія́не, Всеви́дець Госпо́дь іспо́лни ду́шу твою́ благода́ті Своєя́ і освяти́ ю в сосу́д Ду́ха Свята́го, да ви́дящії тя восхва́лять Бо́га Вседержи́теля і, взе́мши на ра́мо ки́йждо крест свой, во слід Єму́ гряде́ть, воспіва́я: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом, просвіще́нним от Го́спода, іспо́лнен бив, преподо́бне, не попусти́л єси́ страсте́м в душі́ твоє́й воцари́тися, си́лою Бо́жиєю вся хи́трости тлі́ннаго і вре́меннаго житія́ отража́я. Ті́мже, усе́рдіє твоє́ похваля́юще, вопіє́м ті:","Ра́дуйся, землі́ Пафлаго́нськия похвало́.","Ра́дуйся, Це́ркви Христо́ви зерца́ло.","Ра́дуйся, на землі́, я́ко на небесі́ пожи́вий.","Ра́дуйся, невозвра́тно за Го́сподом послі́довавий.","Ра́дуйся, моли́тви, поста́ і воздержа́нія храни́телю.","Ра́дуйся, і́стиннаго богопочита́нія насади́телю.","Ра́дуйся, смире́нієм мир душі́ своєя́ стяжа́вий.","Ра́дуйся, тлі́нная і вре́менная ми́ра сего́ презрі́вий.","Ра́дуйся, от Го́спода дар чудотворе́нія получи́вий.","Ра́дуйся, врага́ злоко́зненнаго низложи́вий.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственния любве́, є́юже іспо́лнено бисть се́рдце твоє́, укріпля́ємий, свя́те Стилія́не, вся імі́нія твоя́ ни́щей бра́тії разда́л єси́ і, ко бра́тії і́ночеськой сопричте́нний, сла́дці воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці своє́м жела́ніє ве́ліє к непреста́нному восхожде́нію лі́ствицею духо́вною і уєдине́ніє возлюби́в, бра́тію свою́ оста́вил єси́, подви́жниче многотру́дний, і в пеще́ру пресели́вся, дні і но́щі в славосло́вії Бо́га пребива́л єси́. Таково́му твоєму́ дерзнове́нію див'я́щеся, восхваля́єм тя:","Ра́дуйся, Го́спода всім се́рдцем возлюби́вий.","Ра́дуйся, Ца́рствія Небе́снаго взиска́вий.","Ра́дуйся, му́дре ко спасе́нію стопи́ своя́ напра́вивий.","Ра́дуйся, Бо́га доброді́тельним житіє́м просла́вивий.","Ра́дуйся, вели́ких дарова́ній вмісти́лище.","Ра́дуйся, трезві́нія і воздержа́нія храни́лище.","Ра́дуйся, я́ко житію́ безпло́тних поревнова́л єси́.","Ра́дуйся, я́ко по́двигом дре́вніх отце́в пустинножи́телей подража́л єси́.","Ра́дуйся, Боже́ственною благода́тію сердця́ моля́щихся тебі́ напая́яй.","Ра́дуйся, благода́тния ісціле́нія ді́тем ма́лим істоча́яй.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю по́мислов і страсте́й безбі́дно претерпі́л єси́, о́тче преподо́бне, і приста́нище ти́хоє Христа́ обрі́л єси́, Єму́же во мно́зі долготерпі́нії нелі́ностно рабо́тая воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о богоуго́днім житії́ твоє́м, о́тче Стилія́не, мно́гія стра́ждущия і немощни́я к пеще́рі твоє́й прихожда́ху і, наставле́нієм твої́м внима́я, в і́стинній ві́рі укріпля́хуся, в печа́ліх утіше́ніє обріта́ху і во грісі́х сле́зноє покая́ніє приноша́ху. Сего́ ра́ди ублажа́єм тя:","Ра́дуйся, світи́льниче присногоря́щий, путь спасе́нія освеща́яй.","Ра́дуйся, кри́не пусти́нний, свя́тостію благоуха́яй.","Ра́дуйся, ра́бе Госпо́день, благи́й і ві́рний.","Ра́дуйся, небе́сними дарова́нії обогаще́нний.","Ра́дуйся, я́ко пред Престо́лом Царя́ Небе́снаго предстої́ши.","Ра́дуйся, я́ко Бо́гу моли́тви о нас прино́сиши.","Ра́дуйся, Го́спода кро́ткий і смире́нний служи́телю.","Ра́дуйся, за́повідей Бо́жиїх ре́вностний ісполни́телю.","Ра́дуйся, я́ко милосе́рдіє Отця́ Небе́снаго к нам приклоня́єши.","Ра́дуйся, я́ко любо́вію к Бо́гу сердця́ на́ша ісполня́єши.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́, преподо́бне о́тче, сві́том благочести́ваго житія́ твоєго́ пусти́ню освяща́я і вся приходя́щия к тебі́ уче́нієм Христо́вим просвіща́я і ві́ровати во Єди́наго і́стиннаго Бо́га науча́я, да ку́пно с тобо́ю воспіва́ють: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше, я́ко ча́да ма́лия незло́биви суть, і словесе́м Єва́нгельським внима́я: «Амі́нь глаго́лю вам, а́ще не обратіте́ся і бу́дете я́ко ді́ти, не вни́дете в Ца́рство Небе́сноє», ві́ру такову́ю стяжа́л єси́, преподо́бне о́тче, і благода́ть от Го́спода моли́тися о ча́діх восприя́л єси́. Ми же, воспіва́я вели́чія Бо́жия, на тебі́ явле́нная, глаго́лем ті си́це:","Ра́дуйся, младе́нцев бла́гостний попечи́телю.","Ра́дуйся, ма́терей болі́знующих о ча́діх свої́х уті́шителю.","Ра́дуйся, возложе́нієм рук не́мощі младе́нцев ісцеля́вий.","Ра́дуйся, ві́ру чи́стую і і́скреннюю в себі́ стяжа́вий.","Ра́дуйся, я́ко ча́дом ма́лим покрови́тельствуєши.","Ра́дуйся, я́ко за безча́дних роди́телей о дарова́нії їм чад Бо́га умоля́єши.","Ра́дуйся, душе́вния і тіле́сния неду́ги ісціля́яй.","Ра́дуйся, ко благочести́вому житію́ побужда́яй.","Ра́дуйся, те́плий наш моли́твенниче.","Ра́дуйся, ми́лостивий наш засту́пниче.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дником єва́нгельськия кро́тости бил єси́, преподо́бне о́тче, о́бразом житія́ твоєго́ всім показу́я, я́ко вся возмо́жна челові́ку о укріпля́ющем Бо́зі, Єго́же благода́тію і на́ша сердця́ во і́стинній ві́рі укріпи́ і бу́ди нам ско́рий помо́щник і те́плий моли́твенник, вопію́щим о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ я́ко світи́льник, на сві́щниці церко́вній поста́вленний, свя́те Стилія́не, да всі ви́дящії мно́гая чудеса́ ісціле́ній тобо́ю твори́мая і при́сно явля́ємая, восхва́лять Бо́га, ди́внаго во святи́х Свої́х, тебі́ же воспою́ть сицева́я:","Ра́дуйся, равноа́нгельний слуго́ Госпо́день.","Ра́дуйся, обита́лище Ду́ха Свята́го.","Ра́дуйся, благоче́стієм себі́ украси́вий.","Ра́дуйся, в сосу́д благоуха́нний ду́шу твою́ обрати́вий.","Ра́дуйся, я́ко на землі́ і́м'я твоє́ прославля́ється.","Ра́дуйся, я́ко сла́достію небе́сною наслажда́єшися.","Ра́дуйся, жа́жду духо́вную утоли́вий.","Ра́дуйся, на небесі́х оби́тель себі́ сотвори́вий.","Ра́дуйся, я́ко со А́нгели Го́спода воспіва́єши.","Ра́дуйся, я́ко в ли́ці преподо́бних пребива́єши.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ яви́ти ми́ру но́ваго істо́чника ми́лости Своєя́ неоскудева́ющия, Христе́ Бо́же наш, дарова́л єси́ нам предста́теля і моли́твенника к Тебі́ дерзнове́ннаго – преподо́бнаго Стилія́на, да Тя, Всеблага́го Бо́га на́шего сла́в'яще, во умиле́нії серде́чнім зове́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго хода́тая і засту́пника і́мами тя пред Бо́гом, блаже́нне Стилія́не, ти бо душе́ю кро́ткою і ми́лостивою непреста́нно мо́лишися Го́сподеві, о є́же ниспосла́ти благода́тную по́мощ всім лю́дем, сла́в'ящим Єго́, Всеблага́го Отця́ на́шего Небе́снаго, і вопію́щим ті си́це:","Ра́дуйся, арома́ти ра́йськими благоуха́яй.","Ра́дуйся, неісчерпа́ємий істо́чниче ісціле́ній.","Ра́дуйся, усе́рдний о нас моли́твенниче.","Ра́дуйся, оби́димих крі́пкий засту́пниче.","Ра́дуйся, доброді́тельнаго житія́ учи́телю.","Ра́дуйся, немощни́х іску́сний ціли́телю.","Ра́дуйся, в любві́ к Бо́гу пламене́вий.","Ра́дуйся, небе́сних благ возжелі́вий.","Ра́дуйся, пра́ведности нас науча́яй.","Ра́дуйся, люби́ти Бо́га і бли́жняго своєго́ нас наставля́яй.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нника і прише́льця помишля́л єси́ себе́ би́ти в ми́рі сем, преблаже́нне о́тче, оте́чествія го́рняго взиску́я і Небе́снаго Ієрусали́ма граждани́ном би́ти жела́я, в не́мже ни́ні сла́дці воспіва́єши Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь распали́лся єси́ любо́вію к Сладча́йшему Ісу́су, преподо́бне о́тче, дні і но́щі в моли́тві і по́двигах пребива́я і, Ду́ха Свята́го іспо́лнився, всему́ ми́ру моли́твенник ізря́ден показа́лся єси́, рі́ки чуде́с істоча́яй. Сего́ ра́ди, почита́я святу́ю па́м'ять твою́, во умиле́нії зове́м:","Ра́дуйся, на по́мощ тя призива́ющих спаса́яй.","Ра́дуйся, неду́жних і стра́ждущих ісціля́яй.","Ра́дуйся, вра́жиїх стріл прогони́телю.","Ра́дуйся, дия́вольських наві́тов разори́телю.","Ра́дуйся, я́ко А́нгели труди́ твої́ми возвесели́л єси́.","Ра́дуйся, я́ко дия́вола по́двигами твої́ми посрами́л єси́.","Ра́дуйся, непоколеби́мий сто́лпе і́ночествующих.","Ра́дуйся, ми́лостивий покрови́телю в супру́жестві живу́щих.","Ра́дуйся, при́сний о нас к Бо́гу моли́твенниче.","Ра́дуйся, в біда́х ско́рий наш засту́пниче.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ удиви́л єси́, преди́вне о́тче, єди́наго бо Бо́га возлюби́в, в пусти́ні взиска́л єси́ Того́ равноа́нгельним житіє́м твої́м, ни́ні же на небесі́х блаже́нства ра́йськаго наслажда́єшися і воспіва́єши Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния не мо́гуть по достоя́нію воспі́ти вся по́двиги і труди́ твоя́, преподо́бне о́тче, во сла́ву Го́спода тобо́ю твори́мия. Ми же, душа́ми умиля́яся, богоуго́дноє житіє́ твоє́ восхваля́єм пі́нії такови́ми:","Ра́дуйся, і́стинному служе́нію Бо́гу нас науча́яй.","Ра́дуйся, сердця́ на́ша ра́дости ісполня́яй.","Ра́дуйся, я́ко безро́потному несе́нію креста́ нас науча́єши.","Ра́дуйся, я́ко неду́ги на́ша душе́вния і тіле́сния ісціля́єши.","Ра́дуйся, благоче́стія вода́ми жа́ждущия спасе́нія напоі́вий.","Ра́дуйся, сві́том Богопозна́нія ві́рния просвіти́вий.","Ра́дуйся, во бранеіх со страстьми́ помо́щниче.","Ра́дуйся, младе́нцев от неду́гов защи́тниче.","Ра́дуйся, лампа́до любве́ неугаси́мая.","Ра́дуйся, лі́ствице на небеса́ возводя́щая.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щії от разли́чних напа́стей, бід і скорбе́й, тебі́, преподо́бне о́тче, предста́теля крі́пкаго і побо́рника непости́днаго імі́ють: прия́л бо єси́ от Бо́га благода́ть во вся́ких біда́х заступа́ти призива́ющия на по́мощ і́м'я твоє́, да моли́твами твої́ми огражда́єми, благода́рно воспіва́єм о тебі́ Спаси́телю на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рдая і огражде́ніє крі́пкоє яви́лся єси́ ми́ру, преподо́бне о́тче Стилія́не, хода́тайством бо твої́м Це́рков Свята́я укріпля́ється, мир водворя́ється і вся во бла́го устроя́ється. Сего́ ра́ди прийми́ от нас сицева́я:","Ра́дуйся, от па́губних єресе́й отвраща́яй.","Ра́дуйся, о́чі на́ша душе́вния просвіща́яй.","Ра́дуйся, я́ко благода́тію Бо́жиєю сердця́ на́ша укріпля́єши.","Ра́дуйся, я́ко о проще́нії гріхо́в на́ших Го́спода умоля́єши.","Ра́дуйся, спасе́нію душ на́ших посо́бствуяй.","Ра́дуйся, на путь пра́ведний нас направля́яй.","Ра́дуйся, от ко́зней вра́жиїх защи́тниче.","Ра́дуйся, на Стра́шнім Суді́ засту́пниче.","Ра́дуйся, щедро́т Бо́жиїх ми́лостивий пода́телю.","Ра́дуйся, у Престо́ла Вседержи́теля предста́телю.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Піснь хвале́бную прино́сим ті, преблаже́нне о́тче, почита́ющії святу́ю па́м'ять твою́, ти же усе́рдно моли́ Святу́ю Тро́йцю о є́же ізба́витися нам от паде́ній гріхо́вних і жизнь ві́чную наслі́довати, да непреста́нно зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник, от І́стиннаго Сві́та озаря́ємий, су́щим на землі́ явля́єшися, преподо́бне о́тче Стилія́не, сердца́ бо ві́рних просвіща́єши і к ра́зуму Боже́ственному вся наставля́єши, да со умиле́нієм зову́ть ті сицева́я:","Ра́дуйся, на землі́ я́ко А́нгел пожи́вий.","Ра́дуйся, на небесі́ со святи́ми пребива́яй.","Ра́дуйся, Го́споду житіє́м свої́м угоди́вий.","Ра́дуйся, после́дователем стопа́м Єго́ себі́ показа́вий.","Ра́дуйся, я́ко віне́ць безсме́ртія от Бо́га прия́л єси́.","Ра́дуйся, я́ко ра́йськоє блаже́нство со святи́ми унаслі́довал єси́.","Ра́дуйся, во бді́нії пребива́ти нас наставля́яй.","Ра́дуйся, моли́твенно нас покрива́яй.","Ра́дуйся, в тя́жких обстоя́ніїх наш помо́щниче.","Ра́дуйся, си́рих і немощни́х засту́пниче.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть да́нную ті от Го́спода ві́ми, преподо́бне о́тче, во є́же не то́кмо неду́жния младе́нці ісціля́ти і засту́пником і покрови́телем їм би́ти, оба́че і всему́ христия́нському ро́ду ми́лости своя́ низпосила́ти; ві́руєм, я́ко і по сме́рті вся сія́ твори́ши всім, с ві́рою к чудотво́рним іко́нам твої́м припа́дающим, Бо́гу же о тебі́ вопію́щим: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще сла́вноє житіє́ твоє́ і о блаже́ннім отше́ствії твоє́м на небеса́ ра́дующеся, пречу́дне о́тче Стилія́не, ублажа́єм тя, я́ко уго́дника Бо́жия і ди́внаго чудотво́рця. Ти же, Бо́гу предстоя́, при́сно помина́й нас, соверша́ющих любо́вію па́м'ять твою́ і со умиле́нієм зову́щих ті такова́я:","Ра́дуйся, житіє́ твоє́ благочести́во сконча́вий.","Ра́дуйся, в ра́дость Го́спода твоєго́ вше́дий.","Ра́дуйся, Го́рняго Ієрусали́ма честні́йший граждани́не.","Ра́дуйся, ра́йських оби́телей досто́йний обита́телю.","Ра́дуйся, чту́щих тя благода́тний наста́вниче.","Ра́дуйся, притека́ющих к тебі́ бла́гостний покрови́телю.","Ра́дуйся, младе́нцев ціли́телю.","Ра́дуйся, ю́них наста́вниче.","Ра́дуйся, всіх призива́ющих тя ми́луяй і пита́яй.","Ра́дуйся, і по кончи́ні твоє́й ісціле́нія оби́льно істоча́яй.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О всехва́льний і преди́вний уго́дниче Христо́в, преподо́бне о́тче Стилія́не! Прийми́ сіє́ ма́лоє моле́ніє, от усе́рдія на́шего в похвалу́ тебі́ приноси́моє, і покри́й моли́твами твої́ми всіх притека́ющих к тебі́ с ві́рою і любо́вію, да покая́ніє на́ше приі́мше, Госпо́дь і Бог наш прости́ть нам вся гріхи́ на́ша і соприча́стники Ца́рствія Своєго́ соді́лаєть, да ви́ну с тобо́ю і со всі́ми святи́ми воспіва́єм Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Созда́тель єще́ от утро́би ма́тернія ізбра́ тя, преподо́бне Стилія́не, чу́дним житіє́м свої́м на землі́ прославля́ти Тро́йцю Святу́ю, по блаже́нній же кончи́ні твоє́й учини́ тя со святи́ми А́нгели воспіва́ти Єму́ піснь сладча́йшую на небесі́. Ми же, таково́му Бо́жию благоволе́нію о тебі́ ра́дуяся, пісносло́вим тя:","Ра́дуйся, Святи́я Це́ркви похвало́.","Ра́дуйся, Пафлаго́нії крі́пкий сто́лпе.","Ра́дуйся, до́браго воспита́нія цві́те благоуха́нний.","Ра́дуйся, Боже́ственнаго ізбра́нія сосу́де благослове́нний.","Ра́дуйся, Го́спода от ю́ности возлюби́вий.","Ра́дуйся, ві́ру і любо́во в се́рдці своє́м возрасти́вий.","Ра́дуйся, целому́дріє душі́ своєя́ сохрани́вий.","Ра́дуйся, смире́ніє вели́коє стяжа́вий.","Ра́дуйся, пусти́ні вели́кий моли́твенниче.","Ра́дуйся, благода́тний і́ноков путевождю́ і наста́вниче.","Ра́дуйся, о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і уго́дниче Христо́в, ско́рий помо́щниче і моли́твенниче наш, преподо́бне о́тче Стилія́не, прославля́я просла́вльшаго тя Го́спода, похва́льная пі́нія прино́сим ті, чту́щії святу́ю па́м'ять твою́. Ти же, предстоя́ пред Престо́лом Вседержи́теля, воздви́гни о нас, грі́шних, многомо́щния моли́тви твоя́, взива́ющих ті:","Ра́дуйся, преподо́бне о́тче Стилія́не, пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче Стилія́не! По́двигом до́брим подвиза́вся на землі́, на небесі́х восприя́л єси́ віне́ць пра́вди от Христа́ Бо́га на́шего. Ті́мже на твой святи́й о́браз взира́юще, о пресла́внім сконча́нії жи́тельства твоєго́ ра́дуємся і чтим святу́ю па́м'ять твою́. Почита́юще же твоє́ ве́ліє дерзнове́ніє пред Го́сподем, со смире́нієм мо́лим тя, преподо́бне о́тче: воззри́ у́бо благосе́рдим о́ком любве́ твоєя́ на нас, недосто́йних рабо́в твої́х, і потщи́ся богоприя́тним твої́м хода́тайством іспроси́ти у Царя́ ца́рствующих і Го́спода госпо́дствующих, да проба́вить вели́кия і бога́тия ми́лости Своя́ на нас, грі́шних, да пода́сть нам дух пра́вия ві́ри, дух любве́, ми́ра і ра́дости о Ду́сі Свя́те, да ізба́вить ни от вся́ких бід і напа́стей, да ниспо́слеть вся поле́зная ко спасе́нію душ на́ших. Єй, свя́тче Бо́жий, не посрами́ упова́нія на́шего, є́же на тя по Бо́зі і Богоро́дице возлага́єм, но бу́ди нам помо́щник і покрови́тель во спасе́ніє, да сподо́бимся сконча́ти житіє́ на́ше в покая́нії і воспри́ймем ві́чная блага́я во Ца́рствії Христа́ Бо́га на́шего, і просла́вим человіколю́біє Отця́ і Си́на і Свята́го Ду́ха, і твоє́ свято́є заступле́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Столп воодушевленний воздержа́нія, столп неколеби́мий Це́ркве, Стилія́не, соді́лался єси́, блаже́нне. Го́споду от ю́ности вві́рился єси́, обита́лище Ду́ха яви́лся єси́, о́тче преподо́бне, Христа́ Бо́га моли́ дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["От утро́би ма́тернія освяти́вийся, я́ко Боже́ственний Самуї́л, богоно́сне, подви́жничеськи Христа́ Бо́га просла́вил єси́. Ті́мже ісціле́ній показа́лся єси́ кла́дязь і предста́тель боже́ственний отроко́в і младе́нцев, Христо́с бо тя сві́тло сла́вить, Єго́же ізмла́да, Стилія́не, просла́вил єси́."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Стилія́не, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святим рівноапостольним Мефодію і Кирилу, учителям Словенським","e":"Akathist to the Holy Equal-to-the-Apostles Methodius and Cyril, Teachers of the Slavs","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії от Царя́ сил Го́спода Ісу́са во Апо́столи язи́ком слове́нським, Мефо́діє і Кири́лле богому́дрії, пі́сньми восхваля́єм вас, предста́телей на́ших; ви же, я́ко іму́щії дерзнове́ніє ко Го́споду, от вся́ких нас напа́стей предста́тельством ва́шим свободи́те, зову́щих:","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь сил предуста́ви вас би́ти просвіти́телі язи́ком слове́нським; того́ ра́ди і благода́ть Єго́ бі с ва́ми, огражда́ющи і укріпля́ющи вас во вся дні живота́ ва́шего, ю́же помо́щницю себі́ іму́ще, сла́ву Бо́жию во граді́х і пусти́ніх ді́ли і словеси́ вещали єсте́ всім. Ті́мже і ми, я́ко о́трасль язи́к, ві́рою Христо́вою от вас просвіще́нних, воспіва́єм вам, глаго́люще:","Ра́дуйтеся, ра́дости єва́нгельськия благовестителіє;","ра́дуйтеся, чудоді́йственния благода́ті носи́теліє.","Ра́дуйтеся, ско́рбі мно́гі за і́м'я Госпо́днє приявшії;","ра́дуйтеся, пре́лести ми́ра сего́ отве́ргшії.","Ра́дуйтеся, ізді́тська Бо́гом благослове́ннії;","ра́дуйтеся, вінці́ ісповедничеськими от Него́ укра́шеннії.","Ра́дуйтеся, я́ко сла́ву челові́чеськую презрі́вше, в пусти́ні Го́спода іскали єсте́;","ра́дуйтеся, я́ко во́лю Єго́ си́льним ми́ра сего́ со мно́гим дерзнове́нієм благовестили єсте́.","Ра́дуйтеся, сих ра́ди от Влади́ки всіх в рай сві́тел прия́тії;","ра́дуйтеся, пред Ним на́ші те́плії хода́таї.","Ра́дуйтеся, я́ко ва́шими моли́твами ві́рі на́шей утвержде́ніє і́мами;","ра́дуйтеся, я́ко предста́тельством ва́шим єресе́й одолі́ніє стяжа́хом.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 2","ps":["Ви́дів святи́й Кири́лл, єще́ сий о́трок, в нощі́ виді́ніє, я́ко ізбра́ти єму́ Софі́ю ді́ву сестру́ себі́, роди́телем сія́ пові́да. Ті́ї же, разумі́вше зді во́лю Бо́жию, во є́же би́ти ча́ду їх прему́дрости служи́телю, вельми́ о науче́нії і наказа́нії єго́ пекошася, зря́ще же ско́роє єго́ в разумі́ преспі́яніє, поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразумі́нний і єстество́ су́щих іспиту́я, Кири́лл в прему́дрости па́че све́рстник свої́х преспіва́ше і, єще́ о́трок сий, просла́вися, і в палатіх ца́рських во о́браз благи́й ю́ному си́ну царе́ву водворен бі. Но, бога́тство і сла́ву земну́ю презрі́в і є́же єди́но на потре́бу спасе́нія іща́, в пусти́ню всели́ся, да поще́ньми і моли́твами безстра́стія дости́гнеть. Сих же ра́ди і Мефо́дій, воєво́да уже́ сий, оти́де на го́ру Оли́мп, іді́же я́ко і́нок Го́споду служа́ше. Ті́мже научі́мся і ми іскуше́нія ми́ра презира́ти, найпа́че же Христу́ Бо́гу угожда́ти, уго́дники Єго́ воспіва́юще си́це:","Ра́дуйтеся, сла́вою, я́же от челові́к, не прельсти́вшіїся;","ра́дуйтеся, пустинножительству крі́пці приліпи́вшіїся.","Ра́дуйтеся, я́ко Госпо́дь просвіща́л ви єсть в со́ніїх і виді́ніїх;","ра́дуйтеся, я́ко і му́дрость челові́чеськая посо́бствова вам во спасе́ніє.","Ра́дуйтеся, я́ко сло́во Бо́жиє і святи́х оте́ць писа́нія па́че филосо́фії возлюби́ли єсте́;","ра́дуйтеся, я́ко Госпо́дня зако́на не сли́шателіє заби́тливи би́сте, но творці́.","Ра́дуйтеся, я́ко ко́зні дия́вольськия, на пустинножи́телі находя́щия, побіди́ли єсте́;","ра́дуйтеся, я́ко сих ра́ди даде́ся вам власть над іскуше́ньми і страстьми́.","Ра́дуйтеся, я́ко по́двизі ва́ша стяжа́ша вам віне́ць живота́;","ра́дуйтеся, я́ко і ни́ні подви́жником і по́стником посо́бници єсте́.","Ра́дуйтеся, всім грі́шним пред Бо́гом блазі́ї засту́пниці;","ра́дуйтеся, душ на́ших от ле́сти сатани́нськия защи́тници.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 3","ps":["Си́ла моле́ній царе́вих пону́ди свята́го Кири́лла пусти́ню оста́вити служе́нія ра́ди па́стирська в Царегра́ді, іді́же сла́ву Бо́жию уче́ньми і ді́ли віща́ше і є́ресь іконоборную посрамля́ше. Ті́мже і нас, о святи́й о́тче, в правосла́вії утверди́, отпадшия же от і́стинния ві́ри єдиноплеме́нники на́ша к єдиноверію возврати́, да всі словене єди́ними усти́ вопію́ть о просветителіх свої́х Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я прему́дрости си́лу, поте́кл єси́, святи́й Кири́лле, с мона́хом Георгиєм ко ага́ряном стяза́нія ра́ди о ві́рі, і от свята́го Григо́рія Богосло́ва духо́вно просвіща́єм, прему́дрость та́йни Святи́я Тро́йці во мно́зіх подо́біїх показа́л єси́, посрамля́я нечести́вих си́лою слове́с твої́х. Ті́ї же, за́вистію распаля́ємі, восхоті́ша зе́лієм погуби́ти тя, єго́же вкуш, не претерпі́л єси́ вре́да, но здрав прибил єси́ ко свято́му Мефо́дію во оби́тель і с ним ку́пно і́ночеськия труди́ па́ки под'ял єси́, і просвіти́ся пусти́ня по́двигов ва́ших сві́том. Ті́мже і нас предста́тельством ва́шим просвіті́те, любо́вію пою́щих:","Ра́дуйтеся, доброгласнії сла́ви Бо́жия кимвали;","ра́дуйтеся, Це́ркве Єго́ тве́рдії столпи́.","Ра́дуйтеся, та́йну Тро́йці в подо́біїх пропові́давшії;","ра́дуйтеся, воплоще́ніє Бо́га Сло́ва пред сарацини нетрепетно іспові́давшії.","Ра́дуйтеся, е́ллинов і іуде́єв і ва́рваров просвіти́теліє;","ра́дуйтеся, Трієди́наго Божества́ благовестителіє.","Ра́дуйтеся, я́ко ва́ми посрами́ся лесть іконобо́рная;","ра́дуйтеся, я́ко от вас ув'яда́єть нече́стіє ага́рянськоє.","Ра́дуйтеся, я́ко і́стину Христо́ву не ві́дущії і́муть ви учи́тели;","ра́дуйтеся, я́ко іскуша́ємії сомненієм обріта́ють ви во ві́рі наставители.","Ра́дуйтеся, я́ко прогні́вавшії Го́спода і́муть вас пред Ним предста́телі;","ра́дуйтеся, я́ко угожда́ющії Єму́ імі́ють ви покрови́телі.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 4","ps":["Бу́рю разли́чних бід і зол, на язи́ки слове́нськия находя́щую, предста́тельством ва́шим разорі́те, преподо́бнії, я́ко служе́ній мно́гих жре́бій прия́ли єсте́, і во апо́стольстім бо лице́, і в преподо́бних со́нме, і во учи́телей че́сти, і во іспові́дников во́їнстві вчини́ вас Госпо́дь, да всі словене вопію́ть Єму́ о вас: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша цар Козареск, я́ко і́стинная ві́ра в страні́ е́ллинов іспові́дується, іспроси́ себе́ от царя́ Византійська учи́телей правосла́вія. Сей же умоли́ святи́х Кири́лла і Мефо́дія оста́вити пусти́ню і пли́ти по́нтом Євксинським ко козаром. К ни́мже прише́дше, свята́я бра́тія обрати́ша се́рдця їх ко Христу́ і спаси́тельноє Креще́ніє препода́ша їм. С ті́миже і ми просла́вим равноапо́стольних бра́тій, глаго́люще:","Ра́дуйтеся, не убоявшіїся сни́ти ко ва́рваром с єва́нгельським благові́стієм;","ра́дуйтеся, озари́вшії мо́ре сла́вним свої́м та́мо ше́ствієм.","Ра́дуйтеся, я́ко свята́го Апо́стола Кли́мента нетлі́нния мо́щі от вас обрі́тени би́ша;","ра́дуйтеся, я́ко того́ по́мощію нече́стіє козарсько от вас посрами́ся.","Ра́дуйтеся, я́ко світ Христо́в страні́ полуночней преподали єсте́;","ра́дуйтеся, я́ко пра́ведности ва́шея сла́ва во вся конці́ землі́ распростре́ся.","Ра́дуйтеся, Це́ркве Христо́ви предста́тельство і утвержде́ніє;","ра́дуйтеся, от єресе́й і раско́лов на́ше крі́пкоє огражде́ніє.","Ра́дуйтеся, от ага́рян і іуде́й приявшії за Христа́ укоре́ніє;","ра́дуйтеся, от моще́й му́ченика снискавшії благослове́ніє.","Ра́дуйтеся, почита́нію уго́дников благи́м о́бразом житія́ ва́шего нас научи́вшії;","ра́дуйтеся, і са́мі, я́ко уго́дниці Бо́жії, от всіх правосла́вних ісповедуємії.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся вам свята́го Кли́мента нетлі́нноє ті́ло, восплив на волна́х по́нта Євксинськаго, на єго́же дне от семисот літ сокрито лежа́ше. Вам же яви́л є єсть творя́й чудеса́ Госпо́дь в зна́меніє трудо́в апо́стольських і скорбе́й ісповедничеських ва́ших. Є́же разумі́вше, возопи́сте Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше свята́я бра́тія соплеменния їм словени і́стинную ві́ру ісповедующа, сло́во же Бо́жиє свої́м їм язи́ком че́сти не ві́дуща, потща́шася Боже́ственния кни́ги на язи́к словенск прелага́ти, да всі лю́діє на сро́днім їм язи́ці єди́наго всіх Го́спода просла́в'ять; ті́мже і ми просла́вим Го́спода о святи́теліх на́ших, і́мже возопії́м:","Ра́дуйтеся, пода́теліє Христо́ва сві́та наро́дом іноплеме́нним;","ра́дуйтеся, просвіти́теліє слове́н, вам соплеменних.","Ра́дуйтеся, ді́лателіє виногра́да Христо́ва;","ра́дуйтеся, па́стиріє до́брії стада́ Ісу́сова.","Ра́дуйтеся, сло́ва Бо́жия ві́рнії толковници;","ра́дуйтеся, на́ші блазі́ї і кро́тції учи́теліє.","Ра́дуйтеся, мир Христо́в с собо́ю всю́ду пронесшії;","ра́дуйтеся, мир весь сві́том уче́ній ва́ших просвіти́вшії.","Ра́дуйтеся, і ни́ні приє́млющії моле́нія нас грі́шних;","ра́дуйтеся, і ни́ні посилающії утіше́ніє печа́льним.","Ра́дуйтеся, всіх, за і́стину угнете́нних, прибі́жище;","ра́дуйтеся, Ду́ха Свята́го пречестно́є жили́ще.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 6","ps":["Пропові́дници богоно́снії би́вше, свята́я бра́тія во страни́ слове́нськия ідо́ша просвіти́ти новокреще́нния лю́ди Христо́вим уче́нієм. Ті́ї же, узрі́вше вас, я́ко А́нгелов сві́тлих, спасе́ніє благовісти́ти гряду́щих, я́ко па́стирей до́брих, ду́шу свою́ за о́вці полага́ющих, возопи́ша прославля́ющему святи́я Своя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшей в Моравії заре́ і́стинния ві́ри, іспроси́ша кня́зі слове́нстії от царя́ Византі́йськаго во страни́ своя́ учи́тели і утвердители лю́дем. Сих же моле́нія усли́шавше, святі́ї Мефо́дій і Кири́лл во страни́ слове́нськия подвиго́шася, пропові́дающе Єва́нгеліє Ца́рствія Бо́жия слове́нським наро́дом. Є́же уві́дівше, возра́довашася словене і, отвсю́ду ко святи́м бра́тіям притека́юще, зако́ну Бо́жию поуча́хуся, Го́спода сла́в'яще і просвіти́телі своя́ хва́ляще, с ни́миже і ми вку́пі воспої́м Мефо́дія і Кири́лла, взива́юще:","Ра́дуйтеся, Апо́столи на́ші богоглаго́ливії;","ра́дуйтеся, учи́теліє на́ші благода́тнії.","Ра́дуйтеся, іспові́дниці на́ші, мно́гоє дерзнове́ніє іму́щії;","ра́дуйтеся, пусти́нници на́ші преподо́бнії.","Ра́дуйтеся, моли́твенниці на́ші те́плії;","ра́дуйтеся, чудотво́рці на́ші сві́тлії.","Ра́дуйтеся, сла́вити Бо́га всі́ми язи́ки завещавшії;","ра́дуйтеся, тріязичную є́ресь до́бльственно обличившії.","Ра́дуйтеся, слове́ном в год ско́рби утіше́ніє;","ра́дуйтеся, во обстоя́ніїх тя́жких наде́ждо їх і заступле́ніє.","Ра́дуйтеся, принося́щії ко Влади́ці всіх на́ші покая́нния моли́тви;","ра́дуйтеся, і са́мі о нас к Нему́ ви́ну моля́щіїся.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 7","ps":["Хотя́ще ізгна́ти ви із стран слове́нських, свяще́нници латинстії оклевета́ша ви пред єпи́скопом Ри́мським. Єгда́ же сей с мощми́ свята́го Кли́мента прише́дших вас узрі́ і правові́ріє ва́ше і до́броє житіє́ уві́де, а́біє посрами́ клеветавшия на ви користолюбці, вас же і́менем Христо́вим благослови́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́внії Апо́столи яви́шася свята́я бра́тія, не іму́ще поко́я в труді́х свої́х: святи́й бо Кири́лл от по́двигов мно́гих ізнемо́г, ско́ро по прише́ствії в Рим живо́т свой сконча́. Святи́й же Мефо́дій ре́вностію бра́та своєго́ укріпле́н і от па́пи Адрія́на благода́тію архієре́йською почте́н, к по́двигом но́вим в Моравію і Паннонію возврати́ся, іді́же труди́ мно́жайшия понесе́; і́мже див'я́щеся, воспої́м святу́ю бра́тію, зову́ще:","Ра́дуйтеся, до́брії слуги́ Христо́ви;","ра́дуйтеся, я́ко да́же до сме́рти ві́рни і́стині преби́ли єсте́.","Ра́дуйтеся, Го́сподеві, а не челові́ком угождавшії;","ра́дуйтеся, і́мене Єго́ ра́ди поноше́нія от челові́к приявшії.","Ра́дуйтеся, чрез все житіє́ на ни́ві Госпо́дней потрудившіїся;","ра́дуйтеся, і по сме́рті от па́стви своєя́ любо́вію не отлучи́вшіїся.","Ра́дуйтеся, світ ми́ру і соль землі́ би́вшії;","ра́дуйтеся, я́ко світи́льник, горя́й во тьмі, язи́ком светившії.","Ра́дуйтеся, я́ко град верху́ гори́, от ві́рних і неві́рних не утаївийся;","ра́дуйтеся, за́повіді Госпо́дні сотво́ршії і іни́х научи́вшії.","Ра́дуйтеся, сего́ ра́ди ве́лії во Ца́рствії Бо́жиєм нарече́ннії;","ра́дуйтеся, на землі́ в Це́ркві Госпо́дней просла́вленнії.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 8","ps":["Стра́нно преставле́ніє свята́го Кири́лла всім яви́ся, не о жи́зні бо вре́менній помишля́ше, но Го́спода о новопросвіще́нних їм це́рквах моля́ше, да утверди́ть я в Правосла́вії і от тріязичния є́ресі і про́чих напа́стей і бід огради́ть я, свята́го же Мефо́дія увіщава́ше, глаго́ля: Се, бра́те, супру́га воло́в бяхове, єди́ну бразду́ тяжуща, і аз на селі́ па́даю, тече́ніє сконча́в; ти же лю́биши святу́ю го́ру вельми́, не мозі у́бо гори́ ра́ди оста́вити уче́нія язи́ков слове́нських. Ті́мже, толи́цій ре́вности святи́х бра́тій див'я́щеся, воспої́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь пре́дан бив душе́ю же і ті́лом заветам бра́та своєго́, святи́й Мефо́дій не убоя́ся преще́ній кня́жеських, ні клеве́ть от ієре́єв лати́нських, ні заточе́нія темнична, но вся сія́, я́ко до́блій во́їн Христо́в, претерпіва́я, не преста́ язи́ки слове́нськия і па́ству свою́ до́брі пра́вити і просвіща́ти, до́ндеже в ста́рости опочі і к свято́му Кири́ллу во блаже́нную оби́тель ра́йськую преста́вися. К ним же ми воспої́м те́плі:","Ра́дуйтеся, вінце́м терпі́нія на землі́ вінча́ннії;","ра́дуйтеся, сві́том ві́чним на небесі́ осіяннії.","Ра́дуйтеся, подви́жници, ни́щії ду́хом, я́ко ва́ше єсть Ца́рствіє Небе́сноє;","ра́дуйтеся, плакавшії мно́го, я́ко оби́льно утешистеся.","Ра́дуйтеся, кро́тції, я́ко наслі́дисте во Христі́ землі́ слове́нськия;","ра́дуйтеся, алкавшії і жаждавшії пра́вди, я́ко наси́тистеся в селе́ніїх небе́сних.","Ра́дуйтеся, ми́лостивії, я́ко не са́мі то́кмо поми́ловані єсте́, но і іни́м ми́лости от Бо́га хода́таї би́сте;","ра́дуйтеся, чи́стії се́рдцем, я́ко днесь Бо́га лице́м к лицю́ зрита.","Ра́дуйтеся, миротво́рці челові́ком би́вшії, я́ко си́нове Бо́жії нареко́стеся;","ра́дуйтеся, ізгнаннії пра́вди ра́ди, я́ко ва́ше єсть Ца́рствіє Бо́жиє.","Ра́дуйтеся, я́ко возненавидені би́сте от челові́к і гоне́ніє і клевети́ прия́ли би́сте Христа́ ра́ди;","ра́дуйтеся і веселі́теся, я́ко мзда ва́ша мно́га на небесі́х.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 9","ps":["Вся́кия ко́зні, на страни́ слове́нськия находящії, бо́дро разоряли єсте́, преподо́бнії, ті́мже і ни́ні не оста́віте нас, смире́нних і грі́шних, но вся словени в Правосла́вії і єдиноми́слії утверді́те, да всі єди́ними усти́ і єди́ним се́рдцем вопію́ть просла́вившему вас Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния, я́ко ри́би безгла́сни, зрим о вас, преподо́бнії, недоумі́ють бо, ка́ко і в пусти́ні ду́хом витали єсте́, і посреді́ челові́к неуси́пними по́двиги подвиза́стеся. Ми же, ра́дующеся, я́ко такови́є і́мами учи́тели і моли́твенники, прославля́єм вас, глаго́люще:","Ра́дуйтеся, і́стинния ві́ри іспові́дниці;","ра́дуйтеся, Ца́рствія Бо́жия наслі́дници.","Ра́дуйтеся, є́ресі іконоборния обличи́теліє;","ра́дуйтеся, іуде́йства посрамителіє.","Ра́дуйтеся, тріязичную є́ресь попра́вшії;","ра́дуйтеся, слове́ном две́рі Ца́рствія Небе́снаго отверзшії.","Ра́дуйтеся, во́їни Христо́ві, єще́ в житії́ от Него́ сла́вою вінча́ннії;","ра́дуйтеся, і в сла́ві своє́й дух смиренному́дрія соблю́дшії.","Ра́дуйтеся, зла́я, я́ко Іса́їя і Ієремия, от єдиноплеме́нних за блага́я приявшії;","ра́дуйтеся, я́ко Данії́л і Есфи́р, за язи́к свой ходатайствовавшії.","Ра́дуйтеся, со всі́ми святи́ми немерца́ющим сві́том осіяваємії;","ра́дуйтеся, со всі́ми уго́дники Бо́жії о нас грі́шних Го́споду моля́щіїся.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ но́воє ста́до Христо́во от волко́в ми́сленних, святи́й Мефо́дій на одрі́ сме́ртном ученики́ своя́ вельми́ моля́ше тве́рдо стоя́ти во і́стинній ві́рі, ніже́ ко́зней вра́жеських устраша́тися, но і в ско́рбіх і напа́стіх за вся благодари́ти Бо́га, пою́ще: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єсте́ всім, о правосла́вії трудящимся, і заступле́ніє к вам с ві́рою притекающим, Мефо́діє і Кири́лле богому́дрії, і́бо небесе́ і землі́ Творе́ць ізбра́ вас би́ти на землі́ ловці́ челові́ком, по́сліжде же на небесі́х к ли́ку Апо́стол сопричте. Ті́мже і нам умолі́те благода́ті Єго́ да́ром пода́тися, умиле́нно вопію́щим такова́я:","Ра́дуйтеся, доброді́тельми, я́ко виссо́ном, укра́шеннії;","ра́дуйтеся, в прему́дрости с Соломо́ном сравнившіїся.","Ра́дуйтеся, воздержа́нієм і моли́твою вели́ким Анто́нію і Пахо́мію уподо́бльшіїся;","ра́дуйтеся, я́ко Вели́кий Васи́лій і Іоа́нн Златоу́стий, си́лою сло́ва одареннії.","Ра́дуйтеся, я́ко цілому́дрієм Іо́сифу подо́бни би́сте;","ра́дуйтеся, терпі́нію Іовлему подража́вшії.","Ра́дуйтеся, незло́бієм царю́ і проро́ку Дави́ду соревновавшії;","ра́дуйтеся, ре́вностію по ві́рі Ілії́ уподобившіїся.","Ра́дуйтеся, я́ко, подо́бно Па́влу і Іоа́нну Богосло́ву, Христа́ Бо́га возлюби́ли єсте́;","ра́дуйтеся, я́ко Данії́л і тріє́ о́троци, му́жественно Бо́га просла́вившії.","Ра́дуйтеся, я́ко А́нгелом і святи́м Бо́жиїм сожительствуєте;","ра́дуйтеся, я́ко і ми грі́шнії і́м'я ва́ше с ві́рою призива́єм.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рноє принося́ще ко Го́споду, предста́теліє нам грі́шним вас дарова́вшему, со умиле́нієм мо́лим ви, святі́ї учи́теліє на́ші, не возгнуша́тися нас лі́ності ра́ди на́шея, ніже́ отступи́ти от нас тя́жких ра́ди беззако́ній на́ших, но милосе́рдіє от Го́спода всім іспроси́ти, вопію́щим Єму́ о вас: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную Апо́стол слове́нських дво́їцю восхваля́юще, ві́рнії, устрані́мся свої́х ра́спрей і раздо́ров, па́че же разделеній во ві́рі, єдине́ніє же ду́ха в сою́зі ми́ра блюду́ще, воспої́м святи́х учи́телей та́ко:","Ра́дуйтеся, громогласния труби́ єва́нгельськаго благові́стія;","ра́дуйтеся, гу́сли сладкозвучния про́повіді спасе́нія.","Ра́дуйтеся, крі́пції пра́вди насади́теліє;","ра́дуйтеся, непоколеби́мії непра́вди істребителіє.","Ра́дуйтеся, ра́дости подателі всім би́вшії;","ра́дуйтеся, скорбе́й нападе́нія отвсю́ду восприя́вшії.","Ра́дуйтеся, мзди і воздая́ній трудо́м свої́м от челові́к не іскавшії;","ра́дуйтеся, о неблагода́рних лю́діх Бо́гу молившіїся.","Ра́дуйтеся, А́нгел Бо́жиїх і святи́х Єго́ по́двиги і доброді́тельми свої́ми радовавшії;","ра́дуйтеся, ра́дости ві́чния ку́пно с ни́ми во оби́теліх блаже́нних наслажда́ющіїся.","Ра́дуйтеся, зві́зди, сві́том і́стини сіяющия;","ра́дуйтеся, са́мі доброді́телей ва́ших сві́том осіяннії.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 12","ps":["Благода́ть єдине́нія і ми́ра іспросі́те нам, преподо́бнії, і мир во всем ми́рі, до конця́ мирська́го житія́ ва́шего благовестившії, я́ко да і ми, от всіх раско́лов і іскуше́ній свобо́ждшеся, в ми́рі воспої́м, я́ко дру́ги, вас возлюби́вшему єди́ному миротворцю всіх Го́споду: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ва́ша ди́вноє житіє́ на землі́ і помишля́юще сла́ву, я́же на небесі́, святі́ї учи́теліє, си́лу сви́ше правосла́вним христия́ном на враги́ неви́димия і ви́димия даровавшия, і наро́ди слове́нськия в єдине́ніє ві́ри приведшия, всі ві́рнії взива́ють:","Ра́дуйтеся, правосла́вія тве́рдоє огражде́ніє;","ра́дуйтеся, неві́рія живо́є обличе́ніє.","Ра́дуйтеся, ісхожде́ніє Ду́ха Свята́го от Отця́ то́чію, я́ко отдре́вле прия́хом, іспові́давшії;","ра́дуйтеся, слу́жбу Бо́жию соверша́ти кому́ждо свої́м сі язи́ком завещавшії.","Ра́дуйтеся, пра́ведних в пра́ведности утвержде́ніє;","ра́дуйтеся, і беззако́нних к зако́ну обраще́ніє.","Ра́дуйтеся, я́ко ва́ми і ми во ісполне́ніє Це́ркве внидо́хом;","ра́дуйтеся, я́ко ва́ми сло́во Бо́жиє на сро́днім нам язикі́ дости́же.","Ра́дуйтеся, я́ко моли́твами ва́шими, а́ки забра́лом крі́пким, от враго́в на́ших огражда́ємся;","ра́дуйтеся, я́ко предста́тельством ва́шим ві́чния жи́зні сподобля́ємся.","Ра́дуйтеся, всім слове́ном па́стиріє і отці́, ї́хже ра́ди єсьми́ всі бра́тіє;","ра́дуйтеся, я́ко вас ра́ди бра́тія су́ще по пло́ті і по ду́ху бра́тія Христу́ сотвори́хомся.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 13","ps":["О пречу́днії і преди́внії язи́к слове́нських учи́теліє, святі́ї равноапо́стольнії Мефо́діє і Кири́лле, ни́нішнєє приє́мше моле́ніє на́ше, вся словени от находя́щих їм зол і бід свободи́те, в ми́рі і єдине́нії соблюді́те і к Ца́рствію Небе́сному предста́тельством ва́шим приведі́те всіх, во умиле́нії о вас пою́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь сил предуста́ви вас би́ти просвіти́телі язи́ком слове́нським; того́ ра́ди і благода́ть Єго́ бі с ва́ми, огражда́ющи і укріпля́ющи вас во вся дні живота́ ва́шего, ю́же помо́щницю себі́ іму́ще, сла́ву Бо́жию во граді́х і пусти́ніх ді́ли і словеси́ вещали єсте́ всім. Ті́мже і ми, я́ко о́трасль язи́к, ві́рою Христо́вою от вас просвіще́нних, воспіва́єм вам, глаго́люще:","Ра́дуйтеся, ра́дости єва́нгельськия благовестителіє;","ра́дуйтеся, чудоді́йственния благода́ті носи́теліє.","Ра́дуйтеся, ско́рбі мно́гі за і́м'я Госпо́днє приявшії;","ра́дуйтеся, пре́лести ми́ра сего́ отве́ргшії.","Ра́дуйтеся, ізді́тська Бо́гом благослове́ннії;","ра́дуйтеся, вінці́ ісповедничеськими от Него́ укра́шеннії.","Ра́дуйтеся, я́ко сла́ву челові́чеськую презрі́вше, в пусти́ні Го́спода іскали єсте́;","ра́дуйтеся, я́ко во́лю Єго́ си́льним ми́ра сего́ со мно́гим дерзнове́нієм благовестили єсте́.","Ра́дуйтеся, сих ра́ди от Влади́ки всіх в рай сві́тел прия́тії;","ра́дуйтеся, пред Ним на́ші те́плії хода́таї.","Ра́дуйтеся, я́ко ва́шими моли́твами ві́рі на́шей утвержде́ніє і́мами;","ра́дуйтеся, я́ко предста́тельством ва́шим єресе́й одолі́ніє стяжа́хом.","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Кондак 1","ps":["Ізбра́ннії от Царя́ сил Го́спода Ісу́са во Апо́столи язи́ком слове́нським, Мефо́діє і Кири́лле богому́дрії, пі́сньми восхваля́єм вас, предста́телей на́ших; ви же, я́ко іму́щії дерзнове́ніє ко Го́споду, от вся́ких нас напа́стей предста́тельством ва́шим свободи́те, зову́щих:","Ра́дуйтеся, Мефо́діє і Кири́лле, язи́к слове́нських Апо́столи і богому́дрії учи́теліє."]},{"h":"Молитва","ps":["О пресла́внії язи́к слове́нських учи́теліє і просвіти́теліє, святі́ї равноапо́стольнії Мефо́діє і Кири́лле. К вам, я́ко ча́да ко отце́м, сві́том уче́ній і пи́смен ва́ших просвіще́ннії і во ві́рі Христо́вой наста́вленнії, ни́ні усе́рдно прибіга́єм і в сокруше́нії серде́ць на́ших мо́лимся. А́ще бо і заві́т ва́ших, я́ко ча́да непокори́вая, не соблюдо́хом і о угожде́нії Бо́гу, я́коже учи́сте, небрего́хом, і от єдиноми́слія і любве́, ю́же слове́ном, я́ко бра́тіям во ві́рі і по пло́ті, до́брі завіща́сте, отпадо́хом, оба́че, я́коже дре́вле в житії́ ва́шем неблагода́рних і недосто́йних не отвраща́сте тщи, но благи́ми за зла́я воздава́сте, та́ко і ни́ні грі́шних і недосто́йних чад ва́ші моли́тви не отвраті́те, но, я́ко ве́ліє іму́ще дерзнове́ніє ко Го́споду, прилі́жно Того́ молі́те, да наста́вить і обрати́ть нас на путь спасе́нія, ра́спри же і раздо́ри, посреді́ єдинові́рних бра́тій возникающия, умири́ть, отпадшия па́ки во єдиноми́сліє приведе́ть і всіх нас єдине́нієм ду́ха і любве́ во єди́ній, Святі́й, Собо́рній і Апо́стольстій Це́ркві соєдини́ть. Ві́ми бо, ві́ми, я́ко мно́го мо́жеть моли́тва пра́ведника ко благосе́рдію Влади́ки, а́ще і о грі́шних лю́діх приноси́ма бива́єть. Не оста́віте у́бо нас, уни́лих і недосто́йних чад ва́ших, ї́хже гріх ра́ди па́ства ва́ша, ва́ми собра́нная, враждо́ю разділя́єма і собла́зни от інові́рних прельща́єма, ума́лися, о́вці же єя́ слове́сния разсеваєми, от волко́в ми́сленних восхища́ються, даді́те у́бо нам моли́твами ва́шими о правосла́вії ре́вность, да є́ю возгріва́ємі, оте́чеськая преда́нія до́брі сохрани́м, уста́ви і оби́чаї церко́вния ві́рно соблюда́ти потщі́мся, вся́ких лжеуче́ній стра́нних отбіжи́м і та́ко, в житії́ богоуго́днім на землі́ преспіва́юще, жи́зні ра́йськия на небесі́ сподо́бимся, і та́мо с ва́ми вку́пі Влади́ку всіх, в Тро́йці Єди́наго Бо́га просла́вим во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко апо́столом єдинонра́внії / і слове́нських стран учи́теліє, / Кири́лле і Мефо́діє Богому́дрії, / Влади́ку всіх молі́те, / вся язи́ки слове́нськия утверди́ти в Правосла́вії і єдиноми́слії, / умири́ти мир // і спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Свяще́нную дво́їцю просвіти́телей на́ших почті́м, / Боже́ственних писа́ній преложе́нієм істо́чник Богопозна́нія нам істочи́вших, / із него́же да́же додне́сь неоску́дно почерпа́юще, / ублажа́єм вас, Кири́лле і Мефо́діє, / Престо́лу Ви́шняго предстоя́щих // і те́плі моля́щихся о душа́х на́ших."]},{"h":"Величання","ps":["Велича́єм вас, / святі́ї равноапо́стольнії Мефо́діє і Кири́лле, / вся слове́нськия страни́ уче́ньми свої́ми просвети́вшия // і ко Христу́ приве́дшия."]}],"notes":[]},{"u":"Акафіст святителю Григорію Паламі, архієпископу Солунському","e":"Akathist to St Gregory Palamas, Archbishop of Thessalonica","secs":[{"h":"Кондак 1, глас 8","ps":["Фессалони́тськаго па́стиря всеїзря́днаго і Це́ркве світи́ло многосві́тлоє воспої́м в пі́сніх боговіща́нних: Сві́та бо незаходи́маго яви́ся селе́ніє, і подає́ть просвіще́ніє і благода́ть незави́стную зову́щим:","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Ікос 1","ps":["А́нгел в ми́рі, я́ко ви́шніх зри́тель, показа́лся єси́, Григо́ріє всеблаже́нне, і богови́дним твої́м житіє́м а́нгельськая дарова́нія улучи́л єси́. Ті́мже, твоє́й сві́тлости див'я́щеся, о́тче, вопіє́м:","Ра́дуйся, і́мже Світ боже́ственний сія́єть;","ра́дуйся, і́мже тьма отгна́ся.","Ра́дуйся, прему́дрости ве́рті благово́ннійший;","ра́дуйся, наказа́нія лу́чшаго прича́стниче.","Ра́дуйся, висото́ неудобозри́мая висо́ких виді́ній;","ра́дуйся, глубино́ непроходи́мая даро́в духо́вних.","Ра́дуйся, я́ко єси́ церко́вная сві́тлость;","ра́дуйся, я́ко показа́лся єси́ правосла́вних крі́пость.","Ра́дуйся, світи́ло ві́ри всесві́тлоє;","ра́дуйся, світи́льниче благода́ті незаходи́мий.","Ра́дуйся, єго́же ра́ди буєсло́вці умолка́ють;","ра́дуйся, єго́же ра́ди богосло́вці взигра́ють.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 2","ps":["Зрі́ніє душі́ твоєя́ от ю́ности, о́тче, ко Христу́ Царю́ простира́я, ца́рськия презрі́л єси́ двори́ і земну́ю сла́ву оста́вил єси́, по́стничеськими же труди́ Го́сподеві послі́дуя, воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зуму вні́шнему всему́ обучи́лся єси́, всеблаже́нне, я́ко разу́мен і зіло́ остроу́мен, отню́дуже Прему́дрости Бо́жия добро́ти рачи́тель яви́лся єси́, Григо́ріє, умудря́я боже́ственними словеси́ твої́ми благогові́йні ті вопію́щия:","Ра́дуйся, нра́вов преподо́бних сосу́де;","ра́дуйся, Сві́та невеще́ственнаго сокро́вище.","Ра́дуйся, ко́рене благоро́днаго дре́во всепло́дноє;","ра́дуйся, благоче́стія кинна́моне благово́нний.","Ра́дуйся, цві́те неув'яда́ємий земледі́ланія та́їнственнаго;","ра́дуйся, фи́никс многопло́дний благопло́дія душе́внаго.","Ра́дуйся, я́ко презрі́л єси́ лесть мирську́ю;","ра́дуйся, я́ко прия́л єси́ благода́ть богода́нную.","Ра́дуйся, Христо́в служи́телю теплі́йший;","ра́дуйся, тлі́нних вся́чеських преви́шшій.","Ра́дуйся, душе́вния си́ли оживи́вий;","ра́дуйся, страсте́й стремле́нія умертви́вий.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 3","ps":["Си́лою на Афо́ні обле́клся єси́ свято́ю, приє́м і́ночеський о́браз, і в не́мощі пло́ті к по́стничеським угото́вался єси́ трудо́м, Григо́ріє блаже́нне, Укріпля́ющему тя зови́й: Аллилу́я."]},{"h":"Ікос 3","ps":["Просія́л єси́ безмо́лвієм і усе́рдним по́двигом вся́ким ді́ятельнаго жи́тельства і у́мною моли́твою Спа́су в та́їнстві соєдини́лся єси́, Сві́та боже́ственнаго ісполня́єм і просвіща́я тебі́ вопію́щия:","Ра́дуйся, світи́льниче безмо́лвія;","ра́дуйся, о́бразе воздержа́нія.","Ра́дуйся, у́мния моли́тви ді́лателище;","ра́дуйся, ді́ятельнаго жи́тельства сокро́вище.","Ра́дуйся, сосу́де многоці́нний дохнове́нія Уті́шителева;","ра́дуйся, уста́ богоно́сная гла́са духо́внаго.","Ра́дуйся, я́ко превозше́л єси́ преді́ли тлі́нія;","ра́дуйся, я́ко взира́єши на сла́ву Бо́жию.","Ра́дуйся, зряй Світ боже́ственний;","ра́дуйся, Бо́га ви́дяй і от Него́ ви́димий.","Ра́дуйся, бу́яя упраздня́яй мудрова́нія;","ра́дуйся, лю́тая отгоня́яй нападе́нія.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 4","ps":["Пожи́во в безмо́лвії, я́коже а́нгел, о́тче, го́рнєє світозаре́ніє прия́л єси́ і, іспо́лнь воі́стину боже́ственнаго Сві́та, отше́л єси́ от Афо́на я́коже со́лнце, Григо́ріє богому́дре, воспламеня́я пою́щия: Аллилу́я."]},{"h":"Ікос 4","ps":["Обличи́л єси́ боже́ственним сло́вом і прему́дрости си́лою і догма́ти святи́ми, богому́дре, злосла́віє Варлаа́мово, удиви́во вся твоє́ю благода́тію, учи́тель бо боже́ственний вопію́щим показа́лся єси́:","Ра́дуйся, цівни́це благоче́стія;","ра́дуйся, паде́ніє злоче́стія.","Ра́дуйся, Це́ркве вели́кий учи́телю;","ра́дуйся, богоза́рности невеще́ственния іспо́лненний.","Ра́дуйся, віті́є многому́дрий догма́тов пра́вих;","ра́дуйся, мечу́ обоюдоо́стрий на вся вражду́ющия.","Ра́дуйся, у́мних плеве́л іскорени́телю;","ра́дуйся, доброді́телей небе́сних насади́телю.","Ра́дуйся, мно́гий в сло́ві благода́ті;","ра́дуйся, кро́ткий во всіх і незло́бивий.","Ра́дуйся, ві́рних сердця́ утвержда́яй;","ра́дуйся, страсте́й вини́ попаля́яй.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 5","ps":["Богоглаго́ливим язи́ком на собо́рі боже́ственнім, я́ко іспо́лнь небе́сния прему́дрости, ізложи́л єси́, о́тче, Правосла́вія воі́стину святи́я догма́ти, я́ко отце́м єдиноду́шний, Григо́ріє, с ни́миже зове́ши: Аллилу́я."]},{"h":"Ікос 5","ps":["Святи́тель богому́дрий, я́ко доброді́телей сокро́вище і таї́нник восхожде́ній боже́ственних, і Фессалони́тський па́стир богови́ден і прему́др бил єси́ боже́ственним жре́бієм, преподо́бне, сли́ша от нас сицева́я:","Ра́дуйся, уста́ богосло́вов;","ра́дуйся, держа́во правосла́вних.","Ра́дуйся, ієре́єв пра́вило точне́йшеє;","ра́дуйся, па́стирей о́бразе богонапечатле́нний.","Ра́дуйся, трубо́ боговіща́нная уче́ній свяще́нних;","ра́дуйся, істо́чниче богостру́йний, во́ду но́ву істоча́яй.","Ра́дуйся, Солу́ню благосла́вний пастиренача́льниче;","ра́дуйся, Правосла́вія богоглаго́ливий предста́телю.","Ра́дуйся, Сві́та боже́ственнаго служи́телю;","ра́дуйся, жи́зні непоро́чния учи́телю.","Ра́дуйся, душе́вную скве́рну очища́яй;","ра́дуйся, ві́рних ре́вность возбужда́яй.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 6","ps":["Пропові́дник Сві́та боже́ственнаго бив, богоглаго́ливе, я́ко того́ прича́стник в житії́, на той под'є́мшія глас слове́с сві́тлостію затми́л єси́, і вся воздви́гл єси́, Григо́ріє, Бо́гові зва́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в на собо́рі, я́ко сві́тлий богосло́в і уста́ неізглаго́ланния Прему́дрости, неприча́ствуємо би́ти Бо́жиє существо́ боговеща́яй пропові́дал єси́, прича́ствуємо же ді́йство, тебі́ вопію́щим, о́тче:","Ра́дуйся, ве́лій священнояви́телю;","ра́дуйся, боже́ственний богояви́телю.","Ра́дуйся, ви́шнія сві́тлости возвісти́телю;","ра́дуйся, обоже́нія сві́тлий тайнописа́телю.","Ра́дуйся, у́мнаго трезві́нія вождю́ богови́дний;","ра́дуйся, моли́тви вну́треннія наста́вниче непреле́стний.","Ра́дуйся, я́ко іспо́лнился єси́ благода́тей небе́сних;","ра́дуйся, я́ко приобщи́лся єси́ осія́ній боже́ственних.","Ра́дуйся, Бо́жию ви́дівий сві́тлость;","ра́дуйся, страсте́й ізгоня́яй те́мность.","Ра́дуйся, догма́тов правосла́вних основа́ніє;","ра́дуйся, струй богото́чних істо́чниче.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 7","ps":["Ве́лій во святи́теліх воі́стину показа́лся єси́, Григо́ріє му́дре, богояви́телю, я́ко апо́стольським житіє́м і ди́вними доброді́тельми украше́н, преподо́бне, і вся воздвиза́єши пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Не́ктар невеще́ственний боже́ственний і ма́нну душепита́тельную і мед і́же із ка́мене істоча́ющся, я́ко рече́ свяще́нний Дави́д, твої́х слове́с завіща́нія подаю́ть, Григо́ріє всечу́дне, веселя́ще вопію́щия:","Ра́дуйся, язи́че сладча́йший;","ра́дуйся, зра́че боже́ственнійший.","Ра́дуйся, подо́бниче Спа́сов і подража́телю;","ра́дуйся, ревни́телю отце́м і сообита́телю.","Ра́дуйся, ві́яніє небе́сноє, ду́ші прохлажда́ющеє;","ра́дуйся, росо́ духора́дованная, нас ороша́ющая.","Ра́дуйся, благово́ніє свято́є чи́стаго жи́тельства;","ра́дуйся, пи́ще соверше́нная душе́внаго пи́ршества.","Ра́дуйся, ча́ше не́ктара безсме́ртнаго;","ра́дуйся, лю́тих мудрова́ній обличи́телю.","Ра́дуйся, богоно́сцев сія́ніє му́дрих;","ра́дуйся, люде́й води́телю правосла́вних.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 8","ps":["Стра́нная даде́ся благода́ть во ізлія́нії бога́те устна́ма твої́ма, богояви́телю, отню́дуже, я́ко ве́лія ріка́, із Еде́ма проісходя́щая, Григо́ріє, Це́рков всю напоя́єши, Го́сподеві вопію́щую: Аллилу́я."]},{"h":"Ікос 8","ps":["Гора́, о́тче, Афо́нськая сві́тлия твоя́ по́двиги с Солу́нем пропові́дуєть, і вся Це́рков ві́рних я́ко богоза́рнаго тя честву́єть із'яви́теля Сві́та і́же па́че сми́сла, і́мже просвіща́єши вопію́щия:","Ра́дуйся, уста́ богоно́сная;","ра́дуйся, сосу́де мироно́сний.","Ра́дуйся, трисо́лнечнаго осія́нія орга́не;","ра́дуйся, безмо́лвія соверше́ннаго ни́во.","Ра́дуйся, до́ме богосві́тлий боже́ственнаго ді́йства;","ра́дуйся, бога́тство некра́домоє і́же в Ду́сі живота́.","Ра́дуйся, я́ко прия́л єси́ боже́ственная дая́нія;","ра́дуйся, я́ко отврати́л єси́ Варлаа́мова пустосло́вія.","Ра́дуйся, і́мже Афо́н велича́ється;","ра́дуйся, і́мже пре́лесть отгоня́ється.","Ра́дуйся, сві́тлая Солу́ню сла́во;","ра́дуйся, тве́рдая Правосла́вія держа́во.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 9","ps":["Рі́ки от чре́ва твоєго́ та́їнственним одожде́нієм с небесе́, я́ко рече́ Спас, теку́ть, о́тче прему́дре, і жа́ждущая сердца́ напоя́ють от живо́тния струї́, Григо́ріє, Бо́гові зва́ти: Аллилу́я."]},{"h":"Ікос 9","ps":["Легча́йше, о́тче, под'я́л єси́ іскуше́нія разли́чная за до́броє іспові́даніє, і я́коже зла́то во огні́ іскуше́н всі́ми, превозсія́л єси́, возводя́ к лу́чшим благогові́йні ті вопію́щия:","Ра́дуйся, ка́меню благому́жества;","ра́дуйся, ка́меню терпі́нія.","Ра́дуйся, іскуше́ній наше́ствія не убоя́вийся;","ра́дуйся, страсте́й пещ угаси́вий.","Ра́дуйся, стіно́ неколеби́мая Це́ркве Христо́ви;","ра́дуйся, світи́льниче многосві́тлий люде́й богому́дрих.","Ра́дуйся, я́ко ско́рби в ра́дості поне́сл єси́;","ра́дуйся, я́ко Го́сподеві со сла́вою предста́л єси́.","Ра́дуйся, Бо́жия та́їнства пропові́давий;","ра́дуйся, ві́рним спаси́тельная предложи́вий.","Ра́дуйся, душ домострої́телю боже́ственний;","ра́дуйся, Христо́в дру́же боже́ственнійший.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 10","ps":["Уст твої́х словеси́ правосла́вная ві́ра утверди́ся в Ду́сі боже́ственнім: дре́внім бо боже́ственним отце́м єдинонра́вен і єдиноду́шен бив, гла́си тіх, преподо́бне, возгла́вил єси́, поя́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сві́та нетва́рнаго наслажда́яся луча́ми, возсія́вшаго на Фаво́рі, сего́ словопису́єши свяще́нне сла́ву, добро́ту, сві́тлость і воздвиза́єши, свя́те, ко приобще́нію вопію́щия:","Ра́дуйся, сві́та нетва́рнаго таї́нниче;","ра́дуйся, от страсте́й душетлі́нних ізба́вителю.","Ра́дуйся, бу́дущаго благосла́вія предначина́ніє;","ра́дуйся, су́щих в ско́рбі душ утіше́ніє.","Ра́дуйся, я́ко бу́їю показа́л єси́ му́дрость Варлаа́мову;","ра́дуйся, я́ко возвісти́л єси́ Ду́ха благода́ть.","Ра́дуйся, архієре́єв боже́ственноє удобре́ніє;","ра́дуйся, світоно́сноє сокро́вище богосло́вія.","Ра́дуйся, сві́та невеще́ственнаго зерца́ло;","ра́дуйся, чужди́х догма́тов се́рпе.","Ра́дуйся, ра́досте правосла́вних і да́ре;","ра́дуйся, вра́жий рог низверга́яй.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 11","ps":["Висо́ким помишле́нієм і прему́дростію боже́ственною пропові́дав Бо́жия вели́чія, Ду́ха боже́ственних плодо́в открива́єши благода́ті, Григо́ріє, чи́стим ду́хом, ї́хже причаща́ються вопію́щії: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рно твоє́ житіє́ доброді́телей луча́ми, Григо́ріє, яви́ся, боговеща́нне, іспо́лнь же сві́та воі́стину уче́ніє твоє́, блаже́нне: Бо́гові бо приво́диши вся́чеськия уче́нії твої́ми, вопію́щия:","Ра́дуйся, істо́чниче уче́нія;","ра́дуйся, утвержде́ніє Правосла́вія.","Ра́дуйся, жи́тельства свята́го о́бразе;","ра́дуйся, Це́ркве боже́ственния ві́нче.","Ра́дуйся, житія́ чисті́йшаго возвісти́телю чу́дний;","ра́дуйся, сло́ва благода́тнаго пропові́дниче свяще́нний.","Ра́дуйся, я́ко душ вся́ку скве́рну очища́єши;","ра́дуйся, я́ко на спасе́нія стезю́ наставля́єши.","Ра́дуйся, світи́льниче невеще́ственних осія́ній;","ра́дуйся, світи́ло ви́шніх тайнонауче́ній.","Ра́дуйся, єго́же ра́ди Це́рков лику́єть;","ра́дуйся, єго́же ра́ди всяк ві́рний боже́ственно ра́дується.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 12","ps":["Ра́дость іспроси́ боже́ственную і душ спасе́ніє, Григо́ріє, му́дрий святи́телю, приходя́щим к тебі́ благогові́йні і сві́тлия твоя́ по́двиги честву́ющим; сві́та бо я́ко служи́тель, просвіща́єши вопію́щия: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ труди́ і боже́ственния по́двиги, я́же соверши́л єси́ Це́ркве ра́ди, благочести́вих ли́ци ви́ну пою́ть тя, Григо́ріє, і благода́рними усти́ вопію́ть ті непреста́нно:","Ра́дуйся, держа́во Це́ркве;","ра́дуйся, віті́є благоче́стія.","Ра́дуйся, пустосло́ва Акинди́на постиди́вий;","ра́дуйся, си́лу богода́нную яви́вий.","Ра́дуйся, апо́столом купножи́телю, я́ко во всіх подража́тель;","ра́дуйся, о́бщниче і прича́стниче зари́ богонача́льния.","Ра́дуйся, Фессалоні́тськая сві́тлая денни́це;","ра́дуйся, Правосла́вія подви́жниче богоглаго́ливий.","Ра́дуйся, душ на́ших наслажде́ніє;","ра́дуйся, вся́каго правосла́внаго утвержде́ніє.","Ра́дуйся, хра́ма честна́го твоєго́ сві́тлосте;","ра́дуйся, люде́й ві́рних твої́х весе́ліє.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 13","ps":["О боже́ственний о́тче, таї́нниче неізглаго́ланних, Григо́ріє, отце́в кра́ю, твої́х люде́й прийми́ гла́си і твоє́ предста́тельство даждь всім: ві́рно бо к тебі́ притека́єм і Тро́йце вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел в ми́рі, я́ко ви́шніх зри́тель, показа́лся єси́, Григо́ріє всеблаже́нне, і богови́дним твої́м житіє́м а́нгельськая дарова́нія улучи́л єси́. Ті́мже, твоє́й сві́тлости див'я́щеся, о́тче, вопіє́м:","Ра́дуйся, і́мже Світ боже́ственний сія́єть;","ра́дуйся, і́мже тьма отгна́ся.","Ра́дуйся, прему́дрости ве́рті благово́ннійший;","ра́дуйся, наказа́нія лу́чшаго прича́стниче.","Ра́дуйся, висото́ неудобозри́мая висо́ких виді́ній;","ра́дуйся, глубино́ непроходи́мая даро́в духо́вних.","Ра́дуйся, я́ко єси́ церко́вная сві́тлость;","ра́дуйся, я́ко показа́лся єси́ правосла́вних крі́пость.","Ра́дуйся, світи́ло ві́ри всесві́тлоє;","ра́дуйся, світи́льниче благода́ті незаходи́мий.","Ра́дуйся, єго́же ра́ди буєсло́вці умолка́ють;","ра́дуйся, єго́же ра́ди богосло́вці взигра́ють.","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Кондак 1","ps":["Фессалони́тськаго па́стиря всеїзря́днаго і Це́ркве світи́ло многосві́тлоє воспої́м в пі́сніх боговіща́нних: Сві́та бо незаходи́маго яви́ся селе́ніє, і подає́ть просвіще́ніє і благода́ть незави́стную зову́щим:","Ра́дуйся, о́тче Григо́ріє, благода́ті пропові́дниче."]},{"h":"Молитва","ps":["О треблаже́нная і честна́я воі́стину і превожделе́нная главо́, безмо́лвія держа́во, мона́шествующих сла́во, о́бщеє богосло́вов і отце́в і учи́телей укра́шеніє, апо́столов сподви́жниче, іспові́дников і му́чеников безкро́вний ревни́телю і венча́телю словеси́ і дія́ньми і благоче́стія побо́рниче і воєво́до взбра́нний, боже́ственних догма́тов висо́кий із'ясни́телю і учи́телю, пре́лести многоразли́чних єресе́й потреби́телю, всея́ Це́ркве Христо́ви предста́телю, і стра́же, і ізба́вителю! Ти і преста́влься ко Христу́ назира́єши у́бо і ни́ні ста́до твоє́ і всю Це́рков сви́ше, болі́зні разли́чния ісціля́я і словеси́ твої́ми вся управля́я, і є́ресі ізгоня́я, і многообра́зних страсте́й избавля́я. Прийми́ же і на́ше сіє́ моле́ніє і ізба́ви нас от страсте́й і іскуше́ній, і треволне́ній, і бід, і осла́бу і мир і благоде́нствіє нам пода́ждь, о Христі́ Ісу́се Го́споді на́шем, Єму́же сла́ва і держа́ва подоба́єть со безнача́льним Єго́ Отце́м і Животворя́щим Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Правосла́вія світи́льниче, / Це́ркве утвержде́ніє і учи́телю, / мона́хов добро́то, богосло́вов побо́рниче непребори́мий, / Григо́ріє чудотво́рче, Фессалоні́тськая похвало́, / пропові́дниче благода́ті, // моли́ся ви́ну спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 8","ps":["Правосла́вію наста́вниче, святи́телєм украше́ніє, / богосло́вцем побо́рниче непобіди́мий, Григо́ріє чудотво́рче, / Солу́ню вели́кая похвало́, пропові́дниче благода́ті, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Прему́дрости свяще́нний і Боже́ственний орга́н, / Богосло́вія сві́тлую согла́сно трубу́, / воспіва́єм тя Григо́ріє Богоглаго́льниче: / но я́ко ум Уму́ Пе́рвому предстоя́й, / к Нему́ ум наш о́тче наста́ви, да зове́м: // ра́дуйся пропові́дниче благода́ті."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Григо́ріє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святій рівноапостольній Ніні, просвітительці Грузії","e":"Akathist to the Holy Equal-to-the-Apostles Nina, Enlightener of Georgia","secs":[{"h":"Кондак 1","ps":["Ізбра́нной служи́тельнице сло́ва Бо́жия і по́двигом святи́х апо́стол подражательнице, зало́г благослове́нія от Бо́жия Ма́тере, честни́й крест приявшей і во страні́ І́верстій водрузившей, благода́рственная хвале́нія воспису́єм ті, цівни́це духо́вная, свята́я равноапо́стольная Ні́но. Ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, не преста́й моля́щися ізба́вити нас от вся́ких бід і скорбе́й, да со умиле́нієм благода́рственно зове́м ті:","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Ікос 1","ps":["А́нгела ди́вна страни́ І́верськия яви́ тя всея́ тва́рі Созда́тель, обрати́ти наро́ди землі́ сея́, сідя́щия во тьмі і сі́ні сме́ртній, от пре́лести і́дольскія і призва́ти їх во язи́к свят, в лю́ди обновле́нія. Ті́мже ми, благодаря́ще Бо́га, прославля́єм тя я́ко просвіти́тельницю і моли́твенницю на́шу і прилі́жно зове́м ті:","Ра́дуйся, пречу́дная ізбраннице Боже́ственнаго Про́мисла;","ра́дуйся, ди́вно процві́тшая розго́ благочести́ваго ко́рене.","Ра́дуйся, сосу́де благода́ті преізря́дний;","ра́дуйся, вмісти́лище благода́тния си́ли.","Ра́дуйся, Пресвяти́я Ді́ви Богоро́диці ві́рная посланнице;","ра́дуйся, прехва́льная апо́столом подражательнице.","Ра́дуйся, во благові́стії первозва́нному Андре́ю поревновавшая;","ра́дуйся, є́юже лжа і́дольськая попра́на бисть.","Ра́дуйся, є́юже свята́я ві́ра насади́ся;","ра́дуйся, є́юже нам земни́м путь к небесе́м показу́ється.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 2","ps":["Ви́дяще ісполне́ніє Боже́ственнаго о лю́діх смотре́нія Отця́ Небе́снаго, Єдиноро́днаго Єго́ Си́на і Свята́го Ду́ха, воздви́гшаго проро́ки і апо́столи ко спаси́тельному служе́нію і на́шего ра́ди обраще́нія к сві́ту Єва́нгельськия і́стини ізбра́вшаго святу́ю равноапо́стольную Ні́ну, вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний возжелі́вши уразумі́ти свята́я Ни́на, не єди́ножди іспи́товаше от наста́вници своєя́ Ніянфори, я́же ізві́стна би́ша о Го́споді Спаси́телі на́шем і Єго́ свято́м Хитоне, науче́нная же от нея́ і́стинними позна́нії, восхоті́ поклони́тися вседрагому Хитону і мі́сту по́двигов святи́х Апо́стол. Ми же, благогові́нія к жи́зні святи́я Ни́ни іспо́лненнії, прославля́єм ю си́це:","Ра́дуйся, і́стини Ца́рствія Бо́жия уразумі́ти іму́щая;","ра́дуйся, от ю́ности Христа́ возлюби́вшая.","Ра́дуйся, от мла́дости ма́терію своє́ю Сусанною благоче́стію науче́нная;","ра́дуйся, отця́ своєго́ Завуло́на утіше́ніє.","Ра́дуйся, святи́телєм Іувеналієм в стра́сі Бо́жії упасенная;","ра́дуйся, Бо́жиїм словесе́м обученная.","Ра́дуйся, во святі́м гра́де Ієрусали́ме возращенная;","ра́дуйся, тече́нієм свої́м к сла́ві Бо́жієй во мла́дости пра́ведних удиви́вшая.","Ра́дуйся, земни́м благо́м небе́сная предпочетшая.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго воздви́гши тя, свята́я Ні́но, любо́вію благоче́стія, жела́нієм поклони́тися хитону Госпо́дню і ре́вностію апо́стольською, поста́ви тя я́ко світи́льник лучезарен, да приє́млющії от тебе́ світ Богоразу́мія взива́ють к Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи свята́я Ни́на непоколеби́мую ре́вность ко благоугожде́нію Го́сподеві, возгара́шеся жела́нієм прийти́ во страну́ І́верськую і поклони́тися та́мо сокрове́нним святи́ням. Ми же, ви́дяще в ней таково́є свято́є ревнова́ніє, возопії́м к ней:","Ра́дуйся, ізмла́да суєту́ ми́ра презревшая;","ра́дуйся, і́стинную му́дрость возлюби́вшая.","Ра́дуйся, ві́рноє сокро́вище Богому́дрія в Боже́ственном уче́нії обрі́тшая;","ра́дуйся, возлюби́вших суєту́ ми́ра доброді́тельним житіє́м превозше́дшая.","Ра́дуйся, на непоколеби́мім ка́мені за́повідей Христо́вих утверди́вшаяся;","ра́дуйся, преданностію во́лі Бо́жієй А́нгели і челові́ки удиви́вшая.","Ра́дуйся, посто́м і моли́твою плоть свою́ ду́хові покорившая;","ра́дуйся, любо́вію своє́ю ко хра́му Бо́жию тому́жде мно́гі научи́вшая.","Ра́дуйся, добро́тою нра́ва к служе́нію апо́стольства уготовившаяся;","ра́дуйся, чрез доброді́тельноє житіє́ своє́ сосу́дом Ду́ха Свята́го соделавшаяся.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 4","ps":["Бу́рею жите́йських страсте́й смущаємі, недоумі́єм, ка́ко досто́йно воспіва́ти твоє́ ди́вноє му́жество, свята́я богоізбра́нная Ні́но, не устраши́ла бо ся єси́ іспо́лнити хоті́ніє своє́, є́же ше́ствовати о і́мені Христо́ві во язи́чеський град Рим. Пречи́стая же Ма́тер Го́спода на́шего благоізво́ли да́ти ті честнима рука́ма Свої́ма святи́й крест і призва́ти тя ко благові́стію спасе́нія во страні́ І́верстій всім хотя́щим взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав святи́тель гра́да Госпо́дня Іувена́лій, я́ко Пресвята́я Богоро́диця призва́ тя пропові́дати сло́во Бо́жиє во жре́бії Єя́, во страні́ І́верстій, і дарова́ ті во виді́нії крест, єго́же ти обвила́ єси́ власи́ свої́ми, нача́ сла́вити Бо́га, спаса́ющаго челові́ки, і зва́ти тебі́ си́це:","Ра́дуйся, благода́тію Бо́жиєю приосіне́нная;","ра́дуйся, смире́нієм ду́ха дерзнове́ніє ко Го́споду Ісу́су і Пречи́стой Єго́ Ма́тері приобретшая.","Ра́дуйся, обра́дованная явле́нієм Богома́тере;","ра́дуйся, пресладкая словеса́ от Бо́жия Ма́тере сли́шавшая.","Ра́дуйся, с Не́ю я́ко со другинею беседовавшая;","ра́дуйся, благогові́йно ієрусали́мською бра́тією почтенная.","Ра́дуйся, угото́ваніє ко просвіще́нію на́шему незаходи́мим Сві́том;","ра́дуйся, свіще́, Бо́гом возжже́нная, во є́же разгони́ти мрак нече́стія.","Ра́дуйся, честни́й крест зало́г твоєго́ преуспі́янія во благові́стії приі́мшая.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю яви́ся, свята́я Ні́но, возсія́вши нам ізволе́нієм Пресвяти́я Влади́чиці на́шея Богоро́диці і просвіти́вши нас благові́стієм сло́ва Бо́жия. Сію́ небе́сную путеводницю, сія́ющую сла́вою по́двигов благоче́стія і утіша́ющую ви́ну своє́ю по́мощію всіх нас, притека́ющих к ней с мольба́ми, ублажа́юще, найпа́че восхва́лим Бо́га, яви́вшаго святу́ю Ні́ну ходатайцею о нас, і возопії́м Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше Христо́ви неві́сти, я́же со свято́ю Ни́ною і Рипсимі́єю посто́м і моли́твою спаса́хуся, нечести́вая помишле́нія беззако́нновавшаго Діоклитія́на, хотя́щаго Рипсимі́ю поя́ти в жену́ себе́ і ідолослуженію научи́ти, вся ку́пно біжа́ша та́йно із ідольнаго гра́да Ри́ма во страну́ Арме́нськую; та́може пре́дани бя́ху сме́рті повелі́нієм язичествовавшаго царя́ Тивридата. Святу́ю же Ні́ну Госпо́дь от сіте́й Діоклитія́на і Тивридата спа́се і приведе́ ю благові́стія ра́ди сло́ва Єва́нгельськаго во Іверію. Ті́мже і ми, ра́дующеся сему́ промишле́нію Бо́жию о спасе́нії люді́й, восхваля́єм Бо́жию посланницю, святу́ю Ні́ну, зову́ще:","Ра́дуйся, пребива́нієм свої́м в Ри́мі путь благові́стія себі́ уясни́вшая;","ра́дуйся, несокрушимостію ду́ха і ди́вним му́жеством в служе́нії сло́ва Бо́жия прославившаяся.","Ра́дуйся, тру́дний путь во Іверію безро́потно во сла́ву Бо́жию проше́дшая;","ра́дуйся, благода́тію Бо́жиєю от руки́ Діоклитія́на і Тивридата ізбавленная.","Ра́дуйся, су́щия у гор Тріялетських гла́сом смире́нія огласи́вшая;","ра́дуйся, о́бразом кро́тости мир в душа́х утверди́вшая.","Ра́дуйся, воне́ю благоуха́нія слове́с Христо́вих мно́гіє облагоуха́вшая;","ра́дуйся, утвержде́ніє на́ше на путі́ спасе́нія; ра́дуйся, я́ко тобо́ю сподобля́ємся благ ві́чних.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 6","ps":["Пропові́дниця ве́лія показа́ся свята́я Ни́на, труда́ми бо і болі́зньми єя́ во Іве́рії Це́рков Христо́ва насади́ся, мрак неві́дінія отгна́ся, світ і́стини яви́ся, нам же, ізба́вленним свято́ю Ни́ною от тьми ідолослуже́нія, досто́йно єсть взива́ти ко Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ страні́ І́верстій просвіще́ніє і́стини, єгда́ свята́я Ни́на огласи́ благові́стієм град Урбниси, отню́дуже мно́зі хожда́ху во Грузинський сто́льний град Мцхеть кла́нятися лжи́вим бо́гом Ормузду і Задену; сих і́долов свята́я Ни́на моли́твами свої́ми сокруши́ і низпроверже. Ті́мже і ми я́ко победительницю де́монов восхва́лим ю си́це:","Ра́дуйся, всемогу́щую си́лу і́стиннаго Бо́га во страні́ І́верстій пе́рвіє показа́вшая;","ра́дуйся, си́лою Всеви́шняго і́дола Ормузда порази́вшая.","Ра́дуйся, го́рдость єго́ мольба́ми свої́ми посрами́вшая;","ра́дуйся, останками єго́ безси́ліє зла́го ду́ха открившая.","Ра́дуйся, де́мона За́дена і єго́ а́ггелов попра́вшая;","ра́дуйся, власти́телей тьми отгна́вшая.","Ра́дуйся, безсильноє ца́рство їх разруши́вшая;","ра́дуйся, бісо́вський пла́мень нече́стія угаси́вшая.","Ра́дуйся, бу́рним диха́нієм і огне́м небе́сним служе́ніє і́долом низпровергшая;","ра́дуйся, ре́вностію своє́ю і́м'я і́стиннаго Бо́га во Іве́рії просла́вившая.","Ра́дуйся, синово́м тьми світ Єва́нгельський показа́вшая.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 7","ps":["Хотя́ цар Миріян со слуги́ свої́ми уразумі́ти си́лу і́стиннаго Бо́га, сокруши́вшаго безси́льния і́доли їх, с недоумі́нієм глаго́лаше: что у́бо сіє́ бисть, я́ко бо́зі на́ші падо́ша? Дом же вертогра́даря царе́ва со Авія́фаром, ієре́єм іуде́йським, дще́рію єго́ Сидонією і іни́ми ді́вами, благогові́йно приявшими благові́стіє святи́я Ни́ни, позна́вше Го́спода Христа́, возопи́ша к Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая жизнь даде́ся синово́м Іве́рії прия́тієм от Ни́ни сло́ва і́стини, всі бо от нея́ крести́шася ба́нею водно́ю во очище́ніє своє́ от гріхо́в і освяще́ніє і досто́йні соді́лашася прийма́ти от Бо́га ісціле́нія мольба́ми сея́ предста́тельниці; цар Миріян, благода́тію Бо́жиєю прозрі́в от сліпоти́, і́стиннаго Бо́га уразумі́ і Христа́ іспові́да; цари́ця Нана возста́ от одра́ болі́зні, о́трок же їх от ду́ха зла́го свободи́ся, і всі в купі́лі пакибитія́ возродишася. Сего́ ра́ди всі наро́ди, ви́дяще такова́я, подолгу прославля́ють па́м'ять святи́я Ни́ни, воспіва́юще єй си́це:","Ра́дуйся, неві́ріє царя́ Миріяна во ві́ру обрати́вшая;","ра́дуйся, ві́рноє того́ іспові́даніє приє́мшая.","Ра́дуйся, тому́жде от сліпоти́ ісціле́ніє пода́вшая;","ра́дуйся, і́долом поклоне́ніє угаси́вшая.","Ра́дуйся, свобожде́ніє от язи́чеських заблужде́ній;","ра́дуйся, очище́ніє нра́вов.","Ра́дуйся, ізбавле́ніє от іскуше́ній;","ра́дуйся, дарова́ніє благодія́ній тре́бующим.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до показа́ся нам от Бо́га, я́ко Той, по благосе́рдію Своєму́, страну́ Іверію соді́ла жре́бієм Богома́тере і, в зна́меніє Своєго́ благоволе́нія обитающим в ней, от пе́рвих же дній благовіствова́нія о спасе́нії люді́й посла́ честни́й Хито́н Го́спода Христа́ і над Хитоном водрузи́ Живоно́сний Столп, от него́же і поднесь ві́рующії получа́ють ісціле́нія; єще́ же і яви́ в ней ди́вную і пресла́вную благові́стницю святу́ю Ні́ну, і крест со драги́ми єя́ власи́ ко утвержде́нію святи́я Своєя́ ві́ри дарова́. Сицева́я утіше́нія іму́ще, ми, земноро́днії, вознесе́м уми́ і се́рдця своя́ ко го́рнему Ца́рствію і просла́вим благоді́ющаго нам Бо́га, взива́юще к Нему́ немо́лчно: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся об'ята била́ єси́ ти, свята́я Ні́но, ми́слію о го́рнем і сего́ ра́ди призвала́ єси́ до́льних, неві́дущих Спаси́теля всіх Го́спода Ісу́са Христа́, ко обще́нію со наслі́дники Небе́снаго Ца́рствія, да і ті́ї уві́дять вели́чіє сла́ви єди́наго і́стиннаго Па́стиря небесе́ і землі́ і просла́в'ять Єго́ ку́пно с го́рніми жи́тельми єди́німи усти́ і єди́нім се́рдцем. Ті́мже і ми, взира́юще на ре́вность твою́ о спасе́нії на́шем, со умиле́нієм зове́м ті такова́я:","Ра́дуйся, отверзе́ніє две́рій креще́нія;","ра́дуйся, на́ше к небесе́м приведе́ніє.","Ра́дуйся, святи́м креще́нієм Гру́зії ве́лією ра́достію святи́я А́нгели іспо́лнившая;","ра́дуйся, царя́ Миріяна к созида́нію рукотворе́ннаго хра́ма Бо́гу І́стинному подвигшая.","Ра́дуйся, честни́й крест от рождій лозних в нем водрузившая;","ра́дуйся, зало́г сей любве́ своєя́ ко Христу́ всім ча́дом Святи́я Це́ркве оставившая.","Ра́дуйся, с со́нмом подвижниць свої́х ко свято́му креще́нію всіх призва́вшая;","ра́дуйся, сино́в Іве́рії от купі́лі восприя́вшая.","Ра́дуйся, мно́гі в разумі́ просвіти́вшая.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ Небе́сних Сил ра́довашеся, єгда́ креща́хуся си́ни Іве́рії; єди́н бо от небожи́телей во о́бразі ди́внаго челові́ка яви́ся і утверди́ чудотво́рний столп над ри́зою Госпо́днею, науча́я всіх со свято́ю Ни́ною воспіва́ти Бо́гу:Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії язи́ки свої́ми не возмо́гуть ізрещи́ тебі́ досто́йния хвали́, равноапо́стольная Ні́но: сла́ви бо ра́ди Бо́жия і спасе́нія бли́жніх протекла єси́ от Мцхета Картали́нськия і Кахетинськия землі́, іді́же вся племена́ дол і висо́т, от тебе́ сли́шавша словеса́ Бо́жия, прия́ша спасе́ніє. Ми же, іспо́лненнії ра́дости і благодаре́нія за толи́кую любо́в к нам, от всего́ се́рдця взива́єм ті си́це:","Ра́дуйся, облече́ніє на́ше багряни́цею креще́нія;","ра́дуйся, пото́че сла́дости, напоі́вий нас водо́ю благоче́стія.","Ра́дуйся, преди́вная побо́рнице ві́ри Христо́ви;","ра́дуйся, насажде́ніє на землі́ рая́ небе́снаго.","Ра́дуйся, свобожде́ніє на́ше от ра́бства гріхо́внаго;","ра́дуйся, сокруше́ніє сіте́й вра́жиїх.","Ра́дуйся, посіче́ніє злоче́стія;","ра́дуйся, сла́вная побі́до над неві́рієм.","Ра́дуйся, потребле́ніє злих оби́чаєв і суєві́рій;","ра́дуйся, сладкозвучная свирі́ль ві́ри.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи от ві́чния поги́белі ду́шу свою́ і бли́жніх, равноапо́стольная Ні́но, ти ре́вностію поревнова́ла єси́ о сла́ві Бо́жієй і под'яла єси́ многотрудний по́двиг апо́стольський, ті́мже у́бо і вінце́м апо́стольським украси́лася єси́ от Го́спода на небесі́х, іді́же со всі́ми святи́ми предстоя́щи с мольбо́ю о нас воспіва́єши Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну неруши́мую воздви́же тя Госпо́дь, свята́я Ні́но, і показа́ огражде́нієм на́шим от вся́ких бід і істо́чником ісціле́ній нетлі́нноє твоє́ ті́ло во страні́ Кизикийстей, во ві́си Бодбе, іді́же просвіти́ла єси́ ти цари́цю Софі́ю і наро́д єя́, да всі, предста́тельством твої́м приє́млюще от Бо́га ми́лости, воззове́м ті си́це:","Ра́дуйся, стіно́ і покро́ве, не кри́ющийся от на́шего притека́нія;","ра́дуйся, гото́вая по́моще іщущим спасе́нія і і́стиннаго просвіще́нія.","Ра́дуйся, неоскудіва́ємий істо́чниче благослове́ній і ми́лостей Бо́жиїх к почита́ющим тя;","ра́дуйся, защи́тнице на́ша от поги́белі і напа́стей.","Ра́дуйся, благочести́вим лю́дем ві́рноє поможе́ніє;","ра́дуйся, і́стинноє умире́ніє м'ятущіяся пло́ті.","Ра́дуйся, ра́дованіє душ на́ших.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє принесла́ єси́ Пресвяті́й Тро́йце, свята́я Ні́но, умо́м і ді́лом до конця́ своєя́ жи́зні Трієди́наго Бо́га возлюби́вши. Прийми́ же от прославля́ющих тя умиле́нноє пі́ніє і не пре́зри гла́са на́шего, к тебі́ бо в напа́стіх і ско́рбіх прибіга́єм по Преблагослове́нній Богома́тері і, на твоє́ предста́тельство упова́юще, зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная свіща́, свята́я Ні́но, світ во тьмі я́вльшая, єгда́ преселяшеся от землі́ на не́бо, собра́ ві́рния ча́да своя́ от купі́лі, я́ко отра́сли новосажде́нія, і от них ні́кия неду́жния ісціли́, і предаде́ Бо́гу непоро́чний дух свой. Ви́дяще же блаже́нную єя́ кончи́ну, цар Миріян і бли́жнії єго́ го́рко пла́каху і, со слеза́ми отходния пі́сні пою́ще, взива́ху к ней такова́я:","Ра́дуйся, небе́сний А́нгеле во о́бразі земна́го челові́ка яви́вийся;","ра́дуйся, неві́сто Христо́ва, уневестившая Небе́сному Жениху́ Це́рков Іверійськую.","Ра́дуйся, блага́я просвіти́тельнице на́ша, в по́двизіх дневни́х і нощни́х тече́ніє соверши́вшая;","ра́дуйся, неуста́нная корми́тельнице, пи́щею Боже́ственних слове́с нас пита́вшая.","Ра́дуйся, непоро́чная голуби́це, возлетающая от землі́ в небе́сния оби́телі;","ра́дуйся, я́ко ті́ло твоє́ в нетлі́ніє облече́ся.","Ра́дуйся, я́ко святи́я мо́щі твоя́ благоуха́нія іспо́лнишася;","ра́дуйся, я́ко тіх благоуха́нієм ми, ча́да твоя́, ни́ні наслажда́ємся.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га, ві́дуще, по до́лгу пра́зднуєм всечестну́ю па́м'ять твою́, свята́я равноапо́стольная Ні́но, і со умиле́нієм се́рдця притека́юще ко о́бразу твоєму́, честни́м кресто́м украше́нному, вседу́шно про́сим: сохрани́ нас в жи́зні сей во ві́рі правосла́вній і во вся́ком благоче́стії і чистоті́, да і в сме́ртном успе́нії на́шем обря́щемся досто́йні воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ к Бо́гу отше́ствіє, всехва́льная Ні́но, почита́єм твой по́двиг апо́стольства, велича́єм ре́вность по Бо́зі, хва́лим долготерпі́ніє, сла́вим смире́ніє і ублажа́єм кончи́ну твою́, чудеси́ бо мно́гими по отше́ствії твоє́м ди́вно просла́вилася єси́; о ни́хже див'я́щеся, вопіє́м ті си́це:","Ра́дуйся, в сожи́тельство А́нгельських чино́в і святи́х любе́зні прия́тая;","ра́дуйся, собо́ру апо́стольському сопричте́нная.","Ра́дуйся, с ли́ки ізбра́нних Бо́жиїх в черто́г небе́сний все́льшаяся;","ра́дуйся, злата́я кади́льнице, фиміа́м моли́тви о нас Бо́гу принося́щая.","Ра́дуйся, лицезрі́нієм небе́сних ві́чноє блаже́нство вкушающая;","ра́дуйся, с равноапостольними Константи́ном і Єле́ною сла́вимая.","Ра́дуйся, наро́дом Грузинським і всі́ми правосла́вними величаємая;","ра́дуйся, чуде́с Христо́вих сокро́вище.","Ра́дуйся, я́ко от честна́го креста́, власи́ твої́ми пови́таго, ісціле́ніє душ і тіле́с получа́єм;","ра́дуйся, я́ко от святи́х моще́й твої́х благопотребную по́мощ обріта́єм.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 13","ps":["О пресла́вная і преди́вная просвіти́тельнице страни́ І́верськия, при́сная моли́твеннице на́ша пред Спаси́телем Бо́гом і Єго́ Пречи́стою Ма́терію, свята́я равноапо́стольная Ні́но! Ни́нішнєє приє́мши приноше́ніє на́ше, умоли́ Го́спода Богоприя́тним твої́м хода́тайством ізба́вити нас от вся́кия напа́сти, бід і скорбе́й, і сподо́бити ві́чних благ на небесі́, да с тобо́ю ви́ну взива́єм Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела ди́вна страни́ І́верськия яви́ тя всея́ тва́рі Созда́тель, обрати́ти наро́ди землі́ сея́, сідя́щия во тьмі і сі́ні сме́ртній, от пре́лести і́дольскія і призва́ти їх во язи́к свят, в лю́ди обновле́нія. Ті́мже ми, благодаря́ще Бо́га, прославля́єм тя я́ко просвіти́тельницю і моли́твенницю на́шу і прилі́жно зове́м ті:","Ра́дуйся, пречу́дная ізбраннице Боже́ственнаго Про́мисла;","ра́дуйся, ди́вно процві́тшая розго́ благочести́ваго ко́рене.","Ра́дуйся, сосу́де благода́ті преізря́дний;","ра́дуйся, вмісти́лище благода́тния си́ли.","Ра́дуйся, Пресвяти́я Ді́ви Богоро́диці ві́рная посланнице;","ра́дуйся, прехва́льная апо́столом подражательнице.","Ра́дуйся, во благові́стії первозва́нному Андре́ю поревновавшая;","ра́дуйся, є́юже лжа і́дольськая попра́на бисть.","Ра́дуйся, є́юже свята́я ві́ра насади́ся;","ра́дуйся, є́юже нам земни́м путь к небесе́м показу́ється.","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Кондак 1","ps":["Ізбра́нной служи́тельнице сло́ва Бо́жия і по́двигом святи́х апо́стол подражательнице, зало́г благослове́нія от Бо́жия Ма́тере, честни́й крест приявшей і во страні́ І́верстій водрузившей, благода́рственная хвале́нія воспису́єм ті, цівни́це духо́вная, свята́я равноапо́стольная Ні́но. Ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, не преста́й моля́щися ізба́вити нас от вся́ких бід і скорбе́й, да со умиле́нієм благода́рственно зове́м ті:","Ра́дуйся, свята́я равноапо́стольная Ні́но, просвіти́тельнице Гру́зії."]},{"h":"Молитва","ps":["О всехва́льная і преди́вная равноапо́стольная Ні́но, воі́стину вели́коє украше́ніє Це́ркве Правосла́вния і ізря́дная похвало́ наро́ду Івері́йському, просвіти́вшая всю страну́ Грузи́нськую Боже́ственним уче́нієм і по́двиги апо́стольства побіди́вшая врага́ на́шего спасе́нія, трудо́м і моли́твами насади́вшая зді вертогра́д Христо́в і возра́щшая єго́ в плод мног. Пра́зднующе святу́ю па́м'ять твою́, притека́єм к честно́му ли́ку твоєму́ і благогові́йно лобиза́єм всехва́льний дар тебі́ от Бо́жия Ма́тере, чудотво́рний крест, єго́же ти обвила́ єси́ драги́ми власи́ твої́ми, і уми́льно про́сим, я́ко при́сную предста́тельницю на́шу: огради́ нас от вся́ких зол і скорбе́й, вразуми́ враго́в Святи́я Це́ркве Христо́ви і проти́вников благоче́стія, охраня́й твоє́ ста́до, упасе́нноє тобо́ю, і моли́ Всеблага́го Бо́га, Спаси́теля на́шего, Єму́же ти ни́ні предстої́ши, да да́руєть наро́ду на́шему мир, долгоде́нствіє і во вся́ком до́брім начина́нії поспіше́ніє, і да приведе́ть Госпо́дь нас в Небе́сноє Своє́ Ца́рствіє, іді́же всі святі́ї славосло́в'ять всесвято́є Єго́ І́м'я ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Сло́ва Бо́жия служи́тельнице, / во апо́стольстій про́повіді первозва́нному Андре́ю / і про́чим апо́столом подража́вшая, / просвіти́тельнице Іве́рії і Ду́ха Свята́го цівни́це, / свята́я равноапо́стольная Ні́но, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Прийді́те днесь всі, / воспої́м ізбра́нную от Христа́ / равноапо́стольную пропові́дницю Бо́жия сло́ва, / му́друю благові́стницю, / лю́ди Картали́нії приве́дшу на путь живота́ і і́стини, / Богома́тере учени́цю, / усе́рдную засту́пницю і неусипа́ющую храни́тельницю на́шу, // Ні́ну прехва́льную."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я равноапо́стольная Ні́но, / всю страну́ І́верськую сві́том Єва́нгелія просвіти́вшую // і ко Христу́ приве́дшую."]}],"notes":[]},{"u":"Акафіст блаженній Матроні Анемнясевській","e":"Akathist to the Blessed Matrona of Anemnyasevo","secs":[{"h":"Кондак 1","ps":["Ізбра́нную уго́дницю Христо́ву, в землі́ рязанстей просія́вшую, і преізрядную моли́твенницю о душа́х на́ших пі́сньми восхва́лим, блаже́нную Матрону: ти бо в терпі́нії мно́зі житіє́ твоє́ претекла́ єси́, і страда́нієм украси́вшися, уго́дна Бо́гу яви́лася єси́. Ті́мже у́бо стяжа́вши дерзнове́ніє ко Го́споду, Того́ моли́ ізба́вити ни от вся́каго зла, с любо́вію чту́щих па́м'ять твою́ і пою́щих ті:","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Ікос 1","ps":["А́нгельськи пожи́вши, блаже́нная Матро́но, тілесе́ страда́нієм ду́шу твою́ убелила єси́ і небе́сния ра́дости прича́стниця би́ти сподо́билася єси́. І ни́ні, пребива́ющи во Ца́рствії Небе́снім вку́пі с ли́ки а́нгел і всіх святи́х, непреста́нно мо́лишися за ни, со умиле́нієм пою́щих ті такова́я:","Ра́дуйся, землі́ ряза́нськия похвало́;","Ра́дуйся, страни́ россі́йськия моли́твеннице но́вая.","Ра́дуйся, Бо́гу житіє́м твої́м угоди́вшая;","Ра́дуйся, терпі́нієм мно́зім ду́шу убіли́вшая.","Ра́дуйся, страда́нієм укра́шенная;","Ра́дуйся, вінце́м сла́ви от Бо́га увінча́нная.","Ра́дуйся, с дерзнове́нієм ко Го́споду моля́щаяся;","Ра́дуйся, на землі́ прославля́ємая.","Ра́дуйся, я́ко ни́ні пред Царе́м царе́й предстої́ши;","Ра́дуйся, я́ко чту́щих тя пред Бо́гом помина́єши.","Ра́дуйся, со всі́ми святи́ми на Небесі́ пребива́ющая;","Ра́дуйся, о прославля́ющих тя Бо́га моля́щая.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще, я́ко болі́знію ізді́тська ізбра́ тя Госпо́дь, Того́ бо си́ла в не́мощі соверша́ється, ра́дуємся таково́му о тебі́ Бо́жию смотре́нію, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ющи Бо́жиє ізволе́ніє, от ю́ности Го́споду вручила єси́ себе́, і взе́мши свой крест болі́зней тіле́сних, я́ко от ру́ку Самаго́ Христа́, чрез все житіє́ твоє́ невозвра́тно Тому́ послі́довала єси́. Ми же Го́спода, ізбра́вшаго тя, прославля́юще, ра́достно вопіє́м ті:","Ра́дуйся, Бо́гом ізбра́нная;","Ра́дуйся, Христу́ уневіще́нная.","Ра́дуйся, се́рдце твоє́ Го́сподеві отдавшая;","Ра́дуйся, крест твой безро́потно поне́сшая.","Ра́дуйся, ізді́тська на Го́спода уповавшая;","Ра́дуйся, устна́ми чи́стими Бо́гові молившаяся.","Ра́дуйся, отрокови́це, от Бо́га услишанная;","Ра́дуйся, в терпі́нії твоє́м сви́ше укрепленная.","Ра́дуйся, Ду́ха Свята́го сосу́де очище́нний;","Ра́дуйся, я́ко о тебі́ си́ла Бо́жия явля́ється.","Ра́дуйся, в не́мощі лежа́щая немощни́м помо́щнице;","Ра́дуйся, Бо́жия благода́ті цільбоно́сний істо́чниче.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 3","ps":["Бу́рю укори́зн і поруга́ній от роди́телю твоє́ю непреста́нно с младе́нчества претерпіва́ющи, на Бо́га єди́наго упова́ла єси́, ві́ровавши словесе́м Єго́: я́ко а́ще же і мать забу́деть дитя своє́, но Аз не забу́ду тебі́, с наде́ждою вопія́ла єси́ Тому́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи от седьми́ літ о́чі слі́пе, сле́зи мно́гі пролила єси́, от ма́тере біє́нія терп'я́щи, і се, яви́ся ті Сама́ Пречи́стая, єгда́ же ма́тері сіє́ рекла́ єси́, та па́ки всу́є злі бія́ше тя, оба́че три́щі Богоро́диця явля́шеся, оста́вивши тебі́ рукописа́ніє утешительноє. Тебі́ же отто́лі в разслабле́нії лежа́щей і не озло́бленній, со слеза́ми прино́сим такова́я:","Ра́дуйся, біди́ от сро́дник терпевшая;","Ра́дуйся, в молча́нії ско́рби поне́сшая.","Ра́дуйся, ізді́тська возлюби́вшая Бо́га я́ко Отця́;","Ра́дуйся, уповавшая в напа́стіх на Того́ єди́наго.","Ра́дуйся, многослезния моли́тви к Бо́гу проліявшая;","Ра́дуйся, мно́гі ско́рбі от ма́тере твоєя́ претерпі́вшая.","Ра́дуйся, отрокови́це, от Ма́тере Бо́жия возлю́бленная;","Ра́дуйся, под покро́вом ми́лости Єя́ утешенная.","Ра́дуйся, показа́вшая о́браз кро́тости і незло́бія;","Ра́дуйся, поревновавшая смире́нію Христо́ву.","Ра́дуйся, я́ко в тебі́ ві́ра і люби́ явля́ються;","Ра́дуйся, я́ко житіє́ твоє́ по Бо́зі прославля́ється.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 4","ps":["Си́ла Бо́жия укріпля́ше тя, єгда́ в болі́зні страда́льчествующи, я́ко зла́то в горни́лі о́гненнім, ду́шу твою́ очи́стила єси́, і в го́рній Ієрусали́м устреми́лася єси́, ум і се́рдце отреши́вши от всего́ земна́го і привре́меннаго, і на вся́ком мі́сті, іді́же превитала єси́, поя́ше піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дів ні́кий челові́к тя к одру́ болі́зні пригвожде́нную і разумі́я в простоті́ се́рдця своєго́, я́ко Бо́гу уго́дна єси́, при́йде к тебі́ в не́мощі своє́й, даби́ от рук твої́х получи́ти ісціле́ніє. Ми же, ви́дяще соверше́ніє проси́маго, Бо́га прославля́юще похва́льная прино́сим ті:","Ра́дуйся, во́лю свою́ во́лі Бо́жієй покорившая;","Ра́дуйся, я́ко І́ов вся от Бо́га благода́рні приі́мшая.","Ра́дуйся, я́зви і ра́ни на ті́лі твоє́м носи́вшая;","Ра́дуйся, в же́ртву Бо́гу всю себе́ прине́сшая.","Ра́дуйся, си́лою Бо́жиєю в болі́зні укрепленная;","Ра́дуйся, душе́ю, я́ко в горни́лі очище́нная.","Ра́дуйся, отрешившая ум і се́рдце от всего́ земна́го;","Ра́дуйся, помишлявшая то́кмо о небе́снім.","Ра́дуйся, в го́рній Ієрусали́м устреми́вшаяся;","Ра́дуйся, сподо́бльшаяся сла́дости ра́йськия.","Ра́дуйся, от Го́спода дар ісціле́нія приі́мшая;","Ра́дуйся, прикоснове́нієм ру́ку твоє́ю ісцелявшая.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 5","ps":["Звізда́ многосві́тлая яви́лася єси́, преди́вная ма́ти Матро́но, я́ко світи́льник неугасаяй, путеводя́щи челові́ков по мо́рю жите́йському, людські́я стра́сті в ду́сі кро́тости обличала єси́ і подава́ла єси́ всім ісціле́нія не то́кмо тіле́сная, но і душе́вная, увіщава́ющи це́рков Бо́жию посіща́ти і за вся Бо́га сла́вити, с любо́вію пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Сли́шавше лю́діє бли́жнії і да́льнії о чудесі́х тобо́ю твори́мих, притека́ху к тебі́, я́ко ко купі́лі силоа́мстій, в болі́зніх і ско́рбіх, біда́х і ну́ждах, і нікто́же от тебе́ без утіше́нія оти́де. Ти же, ма́ти Матро́но, помога́ющи всім, назидала єси́ найпа́че Бо́га благодари́ти. І ми, прославля́юще твоє́ смире́ніє, поє́м ті такова́я:","Ра́дуйся, Боже́ственнаго Ду́ха чи́стоє селе́ніє;","Ра́дуйся, к Бо́гу стяжа́вшая ве́ліє дерзнове́ніє.","Ра́дуйся, по мо́рю жите́йському путеводящая;","Ра́дуйся, болі́зні тіле́сния і душе́вния ісціля́ющая.","Ра́дуйся, су́щих во страстеіх с кро́тостію обличавшая;","Ра́дуйся, путь смире́нія во спасе́ніє нам указавшая.","Ра́дуйся, врачми оста́вленних ди́вноє ісціле́ніє;","Ра́дуйся, в піянстві ги́бнущих ско́роє ісправле́ніє.","Ра́дуйся, я́ко оби́димих от злих заступа́єши;","Ра́дуйся, я́ко погиба́ющих в бедствіїх спаса́єши.","Ра́дуйся, сро́дник вражду́ющих благо́є примире́ніє;","Ра́дуйся, с ві́рою прибіга́ющим к тебі́ при́сноє утіше́ніє.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 6","ps":["Ди́вно і стра́нно єсть сли́шати, ма́ти Матро́но, ка́ко не іму́щи науче́нія книжнаго, лю́дем приходя́щим поуче́нія от Свяще́ннаго Писа́нія глаго́лала єси́. Наставля́ющи пребива́ти їх в за́повідіх Госпо́дніх, житія́ святи́х во о́браз їм полагала єси́, подвиза́ющи всіх зва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возлюби́вши оби́тель Диве́євськую, зіло́ почитала єси́ блаже́нную Марі́ю, та́мо пребива́ющую, і с не́ю су́щи во обще́нії духо́внім, моли́тву вку́пі твори́ла єси́. І та́ко мно́гія неду́жния і стра́ждущия от дух нечи́стих ва́шими моли́твами ісціля́юще, на путь покая́нія наставляли єсте́. Ми же Бо́га, ди́внаго во святи́х свої́х, восхваля́юще, прино́сим ті такова́я:","Ра́дуйся, ізмла́да благода́ті Бо́жия іспо́лненная;","Ра́дуйся, да́ри Ду́ха Свята́го обогаще́нная.","Ра́дуйся, прему́дрость і ра́зум от Бо́га прия́вшая;","Ра́дуйся, твої́ми уче́ньми во спасе́ніє назидавшая.","Ра́дуйся, от Бо́га сви́ше науче́нная;","Ра́дуйся, па́че кни́жних просвіще́нная.","Ра́дуйся, подававшая сові́т благи́й во ісправле́ніє;","Ра́дуйся, направлявшая от ві́чния поги́белі ко спасе́нію.","Ра́дуйся, пребивавшая с блаже́нною Марі́єю в духо́внім обще́нії:","Ра́дуйся, посилавшая бісни́х мно́гих к ней за ісціле́нієм.","Ра́дуйся, на землі́ сподоблшаяся сли́шати пі́ніє небе́сноє;","Ра́дуйся, я́ко ни́ні на небесі́х Го́споду воспіва́єши со а́нгели.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 7","ps":["І́ночеський чин преви́ше всего́ земна́го поставлявшая, се́рдцем свої́м скорбела єси́ я́ко не возмо́жно єсть тебі́ во святі́й оби́телі пребива́ти. Ми же Го́споду, да́вшему ті по́прище іно́є прейти́, си́річ в мирсті́м чи́ні лю́дем послужи́ти, благода́рственно воспої́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Іму́щи огнь любве́ ко Го́споду в се́рдці своє́м, по́двигу преподо́бних отце́в поревнова́ла єси́ блаже́нная, непреста́нно умерщвляющи плоть свою́ хла́дом, бді́нієм і поще́нієм. Ми же, немощні́ї, ублажа́юще тя, зове́м тебі́ си́це:","Ра́дуйся, от ю́ности возлюби́вшая нищету́ духо́вную;","Ра́дуйся, дух твой окрилившая та́йною моли́твою.","Ра́дуйся, благо́є і́го Христо́во на ся вземшая;","Ра́дуйся, бре́м'я Єго́ с ра́достію поне́сшая.","Ра́дуйся, любо́вію Бо́жиєю возжже́нная свіще́;","Ра́дуйся, преподо́бних отце́в подражательнице.","Ра́дуйся, мраз со благоду́шієм претерпевавшая;","Ра́дуйся, посто́м твої́м дух немощни́х укреплявшая.","Ра́дуйся, луча́ми Свята́го Ду́ха озаре́нная;","Ра́дуйся, преісполненная ми́лости к бли́жнім і сострада́нія.","Ра́дуйся, бі́дствующим на по́мощ ускоря́ющая;","Ра́дуйся, в ра́дость претворя́ющая печа́ль скорб'я́щих.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 8","ps":["Но́воє і лю́тоє гоне́ніє на Це́рков Бо́жию власть предержащії воздвиго́ша, дишаще преще́нієм і уби́йством. Ти же, Матро́но, в пра́вой ві́рі всіх укріпля́ющи, увещавала єси́ вся претерпі́ти і ві́ру храни́ти, со упова́нієм взива́юще к Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Хотя́ща списа́ти житіє́ твоє́, блаже́нная Матро́но, прийдо́ста к тебі́ два ві́рних му́жа, ти же нічесо́же о себі́ глаго́лала єси́, оба́че узрі́вши духо́внима очи́ма, я́ко от Го́спода му́ченичеський віне́ць обі́ма угото́ван єсть, моли́лася єси́, прося́щи і́ма у Го́спода терпі́нія і по́мощі, во є́же крест понести́. Сего́ ра́ди, тайнозренію твоєму́ див'я́щеся, прино́сим ті такова́я:","Ра́дуйся, Бо́га па́че всего́ земна́го возлюби́вшая;","Ра́дуйся, себі́ ні во что́же вміни́вшая.","Ра́дуйся, па́че жи́зні возжелавшая Ца́рствія Небе́снаго;","Ра́дуйся, на му́ченичество укреплявшая ві́рних.","Ра́дуйся, моли́твеннице о су́щих в гоне́ніїх;","Ра́дуйся, науча́ющая за Христа́ терпі́ти страда́нія.","Ра́дуйся, прозрі́вшая угото́ванния ві́рним вінці́;","Ра́дуйся, я́ко о свя́тости твоє́й свиді́тельствоваша му́ченици.","Ра́дуйся, наставлявшая благода́рні крест Бо́гом да́нний нести́;","Ра́дуйся, увещававшая всегда́ ко Го́споду прибіга́ти.","Ра́дуйся, ка́ко в страда́ніїх ві́ру храни́ти показа́вшая;","Ра́дуйся, я́ко немощни́я в ско́рбіх укріпля́єши.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 9","ps":["Внегда́ собла́зни мно́зі Це́рков Ру́ськую обуреваху, ти, Матро́но, ревнительниця су́щи ві́ри правосла́вния, ча́да Бо́жія в см'яте́нії пребива́ющая увещавала єси́ душепа́губних раско́лов уклоня́тися, да чи́стим се́рдцем всегда́ взива́ють Бо́гу побі́дную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Все житіє́ твоє́, достоблаже́нная ма́ти Матро́но, преіспо́лненно пропові́данія ві́ри, наде́жди і любве́, я́же к Бо́гу і бли́жнім. Ти бо стра́ждущи по во́лі Бо́жієй, я́ко ві́рну Зижди́телю, ду́шу твою́ предала́ єси́ во благотворе́ніє. Сего́ ра́ди прийми́ от нас приноси́моє ті ни́ні піснопі́ніє:","Ра́дуйся, ві́рноє ча́до Це́ркве Правосла́вния;","Ра́дуйся, в броню́ ві́ри і любве́ оболкшаяся.","Ра́дуйся, непрело́жні за Го́сподем последовавшая;","Ра́дуйся, чистоту́ ві́ри сохранившая.","Ра́дуйся, см'яте́нних наставлявшая в Правосла́вії;","Ра́дуйся, обличавшая отпавших от Це́ркве.","Ра́дуйся, храня́щая от па́губних раско́лов ча́да Бо́жия;","Ра́дуйся, скорб'я́щая об уклони́вшихся ві́ри пра́вия.","Ра́дуйся, безприкладний істо́чниче ві́ри, наде́жди і любве́;","Ра́дуйся, і́стини немо́лчноє пропові́даніє.","Ра́дуйся, немощни́я во ві́рі заступа́ющая;","Ра́дуйся, малоду́шния с любо́вію утіша́ющая:","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 10","ps":["Не мо́жеть град укри́тися верху́ гори́ стоя́, та́ко і ти, богому́драя Матро́но, я́ко свіща́ на сві́щниці сві́том любве́ своєя́ вся осіявала єси́, да ви́дящий до́брая діла́ твоя́ прославля́ють Бо́га Отця́, і́же на Небесі́х, воспіва́юще Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Лю́діє неразу́мнії, гріхо́м уя́звленнії і не хотя́щії к Бо́гу обрати́тися, да ісціли́ть їх, возскрежеташа на тя, блаже́нная Матро́но, і злосові́тіє сотвори́вше, ізгна́ша тя із ві́си своєя́. Челові́к же тяжкосе́рдий, і́же ізнесе́ тя, в наказа́ніє злострада́я, ка́яся, і́здше, зане́ Бог поругаєм не бива́єть. Ми же, ви́дяще вся би́вшая, в стра́сі Бо́жиєм взива́єм ті:","Ра́дуйся, милосе́рдію Христо́ву подража́вшая;","Ра́дуйся, безме́здно цільби́ лю́дем подававшая.","Ра́дуйся, гра́де, верху́ гори́ стоя́й;","Ра́дуйся, сві́те любве́ Бо́жия, всіх осіява́яй.","Ра́дуйся, за і́м'я Христо́во хулимая;","Ра́дуйся, гонимая за ві́ру Бо́жию.","Ра́дуйся, лю́дем в ну́ждах благотворившая;","Ра́дуйся, зла́я возблагая приі́мшая.","Ра́дуйся, пра́вди ра́ди ізгна́нная;","Ра́дуйся, о ізгоняющих тя молившаяся.","Ра́дуйся і весели́ся, на по́двиг Бо́гом благослове́нная;","Ра́дуйся, я́ко мзда твоя́ мно́га на Небесі́х.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 11","ps":["Не устраши́лася єси́, уго́днице Бо́жия, уз темни́чних, і́бо ра́достію почитала єси́ за Христа́ страда́нія прия́ти, ті́мже у́бо в тя́жких неду́зіх пребива́ющи, не́мощію своє́ю си́льних ми́ра сего́ посрами́ла єси́. Сего́ ра́ди велегла́сно воспої́м Бо́гу побіди́вшему мир: Аллилу́я."]},{"h":"Ікос 11","ps":["А́ще і не до сме́рти пострада́ла єси́, блаже́нная Матро́но, но ісповедничеством ві́ри украси́вшися, віне́ць сла́ви от Бо́га прия́ла єси́. Ни́ні же с лико́м новому́чеников і іспові́дников россі́йських соувенчанно пребива́єши і за ча́да Бо́жия те́плі предста́тельствуєши. Ми же, крі́постію ду́ха твоєго́ утвержда́ємії, воспіва́єм ті такова́я:","Ра́дуйся, уз темни́чних не устрашившаяся;","Ра́дуйся, страсте́м Христо́вим приобщившаяся.","Ра́дуйся, ра́достію почитавшая гоне́нія за ві́ру;","Ра́дуйся, посрами́вшая си́льних ми́ра не́мощію своє́ю.","Ра́дуйся, приі́мшая заточе́ніє Ца́рствія ра́ди Бо́жия;","Ра́дуйся, я́ко та́мо сло́во Госпо́днє не престава́ше пропові́дати.","Ра́дуйся, в ско́рбіх лютіх не унивавшая;","Ра́дуйся, іскуше́нія му́жеськи терпевшая.","Ра́дуйся, іспові́данієм ві́ри укра́шенная;","Ра́дуйся, с му́ченики соувенчанная.","Ра́дуйся, не убоявшаяся от убива́ющих ті́ло;","Ра́дуйся, ни́ні за ско́рби зіло́ утешенная.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 12","ps":["Уготовляющися в мир іно́й отити́, рекла́ єси́ знаємей своє́й, я́ко Марда́рія ни́ні наречена́ єси́, ли́шше же нічесо́же глаго́лющи, но вся устреми́лася єси́ го́ре, от всего́ жите́йськаго отрешившися, і то́кмо к Бо́гу ум свой возводя́щи, я́ко к наде́жді непреложней, с упова́нієм на ми́лость єго́ вопія́ла єси́ Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по Бо́зі подви́жничеськоє твоє́ житіє́, достохва́льная ма́ти Матро́но, не ві́ми, гді погребе́на єси́, но і́стинно ві́ми, я́ко блаже́ннаго упокоє́нія в Бо́зі сподо́бльшаяся, в Ца́рстві Єго́ пребивавши і всім призива́ющим тя по́мощ ско́рую подає́ши. Ми же Бо́га, просла́вльшаго тя, благодаря́ще, пі́ніє серде́чноє прино́сим ті:","Ра́дуйся, возне́сшаяся умо́м свої́м ко Го́споду;","Ра́дуйся, в не́мощі стяжа́вшая висоту́ духо́вную.","Ра́дуйся, за весь мир с усе́рдієм моля́щаяся;","Ра́дуйся, ла́стовице благоглаго́ливая.","Ра́дуйся, я́ко не скрила єси́ тала́нт Бо́гом да́нний;","Ра́дуйся, обрі́тшая би́сер многоці́нний.","Ра́дуйся, ві́ри зе́рно гору́шично в себі́ возрасти́вшая;","Ра́дуйся, пшени́ці, мног плод прине́сшая.","Ра́дуйся, му́драя ді́во, єя́же світи́льник не угаса́єть;","Ра́дуйся, я́ко і́м'я твоє́ написа́ся в кни́зі жи́зні.","Ра́дуйся, я́ко на всяк день оболче́на бі в одія́ніє бра́чноє;","Ра́дуйся, на пир к Небе́сному Жениху́ ізбра́нная.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 13","ps":["О свята́я блаже́нная ма́ти Матро́но, зря́ще твоє́ ско́рбноє житіє́, со умиле́нієм серде́чним мо́лим тя: прийми́ ни́ні от нас, немощни́х, ма́лоє сіє́ моле́ніє, с любо́вію тебі́ приноси́моє, огради́ ни моли́твами твої́ми от вся́кия ско́рби, біди́ і ну́жди, да предста́тельством твої́м ізба́вимся ві́чния муки́, да сподо́бит і нас Госпо́дь ку́пно с тобо́ю і всі́ми святи́ми во ві́ки во Ви́шніх пі́ти Єму́ піснь трегу́бую: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськи пожи́вши, блаже́нная Матро́но, тілесе́ страда́нієм ду́шу твою́ убелила єси́ і небе́сния ра́дости прича́стниця би́ти сподо́билася єси́. І ни́ні, пребива́ющи во Ца́рствії Небе́снім вку́пі с ли́ки а́нгел і всіх святи́х, непреста́нно мо́лишися за ни, со умиле́нієм пою́щих ті такова́я:","Ра́дуйся, землі́ ряза́нськия похвало́;","Ра́дуйся, страни́ россі́йськия моли́твеннице но́вая.","Ра́дуйся, Бо́гу житіє́м твої́м угоди́вшая;","Ра́дуйся, терпі́нієм мно́зім ду́шу убіли́вшая.","Ра́дуйся, страда́нієм укра́шенная;","Ра́дуйся, вінце́м сла́ви от Бо́га увінча́нная.","Ра́дуйся, с дерзнове́нієм ко Го́споду моля́щаяся;","Ра́дуйся, на землі́ прославля́ємая.","Ра́дуйся, я́ко ни́ні пред Царе́м царе́й предстої́ши;","Ра́дуйся, я́ко чту́щих тя пред Бо́гом помина́єши.","Ра́дуйся, со всі́ми святи́ми на Небесі́ пребива́ющая;","Ра́дуйся, о прославля́ющих тя Бо́га моля́щая.","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нную уго́дницю Христо́ву, в землі́ рязанстей просія́вшую, і преізрядную моли́твенницю о душа́х на́ших пі́сньми восхва́лим, блаже́нную Матрону: ти бо в терпі́нії мно́зі житіє́ твоє́ претекла́ єси́, і страда́нієм украси́вшися, уго́дна Бо́гу яви́лася єси́. Ті́мже у́бо стяжа́вши дерзнове́ніє ко Го́споду, Того́ моли́ ізба́вити ни от вся́каго зла, с любо́вію чту́щих па́м'ять твою́ і пою́щих ті:","Ра́дуйся, Матро́но, в ско́рбіх і напа́стіх нам помога́ющая."]},{"h":"Молитва","ps":["О пресла́вная і достоблаже́нная ма́ти Матро́но, житіє́ твоє́ ско́рби іспо́лнено бі, но взира́юще на смире́ніє твоє́ мо́лим тя, уго́днице Бо́жия, умоли́ всеще́драго Бо́га, да низпосле́ть нам, недосто́йним, ми́лость Свою́, па́че же утверди́ть і укріпи́ть ни в несенії креста́ на́шего, да отве́ржемся себе́ і по́йдем по путі́ спасе́нія за Христо́м, смири́вше ви́я своя́ под крі́пкую ру́ку Бо́жию, принимающе вся, я́же от руки́ Єго́: ві́ми, я́ко Госпо́дь єди́н мо́жеть і па́дших возста́вити, і заблу́ждших возврати́ти, і соблазнившихся іспра́вити, і грі́шников пра́ведники соді́лати. Огради́ нас, ма́ти Матро́но, моли́твами твої́ми от сі́ті лука́ваго, да не прельще́ннії їм возвраті́мся всп'ять. Єще́ мо́лим тя, я́ко іму́щую ве́ліє дерзнове́ніє ко Го́споду, проле́й те́плую моли́тву за ни, неду́жния і уни́лия, і іспроси́ у Го́спода коєму́ждо благопотре́бная, да пода́сть Госпо́дь і нам, я́коже тебі́, терпі́ніє і благоду́шіє в біда́х і ско́рбних обстоя́ніїх, да поживе́м по во́лі Єго́ во вся дні живота́ на́шего, зане́ воі́стину ві́ми, я́ко вість Оте́ць наш Небе́сний, ї́хже тре́буєм, пре́жде проше́нія на́шего. О, блаже́нная ма́ти Матро́но, многоімени́тому со́нму новому́чеников россі́йських причтенная, с ни́ми моли́ Го́спода на́шего і Спа́са Ісу́са Христа́, да сохрани́ть Це́рков Правосла́вную от собла́знов, єресе́й і раско́лов, да огради́ть Госпо́дь страну́ на́шу от всіх наві́тов ви́димих і неви́димих враг і ізи́меть ю із пучи́ни безбо́жия: ві́ми, я́ко живе́м ни́ні то́кмо ра́ди кро́ве му́чеников ізлія́нния, да́руєть же і нам Госпо́дь нічесо́же боя́тися, ві́рним же би́ти Єму́ да́же до сме́рти, і я́ко мучениколюбцем со му́ченики возра́доватися во Ца́рствії Небе́снім. Єй, ма́ти Матро́но, іспроси́ нам у Человіколю́бця Го́спода вре́м'я покая́нія, да не істо́ргнеть ни а́ки пле́вели пре́жде жа́тви, да не во злі поги́бнем, но да очи́стить ни от вся́кия скве́рни пло́ті і ду́ха, во є́же яви́тися нам в день су́дний нескве́рним і непоро́чним пред лице́м Єго́, да чи́стим се́рдцем, я́ко і́стинная ча́да Бо́жия, ра́достні воззове́м к Нему́: не отри́ни ни Го́споди, і прийми́ во Ца́рствіє Твоє́, іді́же Ти ца́рствуєши со Отце́м і Святи́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Молитва про дарування дітей","ps":["О блаже́нная ма́ти Матро́но, к твоєму́ предста́тельству прибіга́єм і тебі́ сле́зно мо́лим, я́ко іму́щую ве́ліє дерзнове́ніє ко Го́споду, проле́й те́плую моли́тву о рабі́х твої́х, в ско́рбі душе́вній пребива́ющих і по́мощі от тебе́ прося́щих. І́стинно бо сло́во Госпо́днє: просі́те і да́сться вам, і па́ки: я́ко а́ще два от вас совіща́єта на землі́ о вся́кой ве́щі, єя́же а́ще про́сита, бу́деть і́ма от Отця́ Моєго́, і́же на Небесі́х. Усли́ши у́бо воздиха́нія на́ша і донеси́ я ко Престо́лу Влади́чню, іді́же ти предстої́ши, ві́ми, я́ко мно́го мо́жеть пред Бо́гом моли́тва пра́ведника. Да не до конця́ забу́деть нас Госпо́дь, но при́зрить с висоти́ Небе́сния на скорб рабо́в Свої́х і плод чре́ва на поле́зноє да́руєть. Воі́стину, Бог іді́же хо́щеть побіжда́ється єстества́ чин, твори́ть бо єли́ка хо́щеть: я́ко сотвори́ Госпо́дь Авраа́му і Са́ррі, Заха́рії і Єлисаве́ті, Іоаки́му і А́нні, с ни́миже моли́, та́ко да сотвори́ть Госпо́дь Бог і нам по ми́лості Своє́й і неізрече́нному человіколю́бію. Бу́ди І́м'я Госпо́днє благослове́нно от ни́ні і до ві́ка. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Я́ко зарни́ця небе́снаго огня́ возсія́ в рязанстей страні́ блаже́нная ста́риця свята́я Матро́на, єя́же па́м'ять днесь творя́ще, воспої́м Христа́ Бо́га, моля́ще Єго́ дарова́ти нам тоя́ предста́тельством в болі́зніх, біда́х і ско́рбіх терпі́ніє, і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["В не́мощіх си́лу, в сліпоті́ о́чі нетлі́нния обріла́ єси́, пребива́ющи на одрі́ болі́зні, всю́ду я́ко пти́ця ду́хом носилася єси́, младе́нствующи ті́лом, била́ єси́ ма́ти скорб'я́щим і обурева́ємим. Ті́мже чту́щих твою́ па́м'ять не оста́ви в моли́твах, і помоги́ нам ізба́витися от гріхо́в покая́нієм, і улучи́ти с тобо́ю Ца́рство Небе́сноє."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я пра́ведная ста́рице Матро́на, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим мученикам Віленським: Антонію, Іоанну, Євстафію","e":"Akathist to the Holy Martyrs of Vilnius: Anthony, John and Eustathius","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії Бо́гом для свиді́тельства правосла́вния ві́ри, му́жеськи попра́сте, святі́ї му́ченици, язи́чеськоє нече́стіє, і за ва́ша страда́нія нетлі́нними вінці́ от Христа́ Бо́га увенчастеся; ті́мже ми, ублажа́юще ва́шу па́м'ять, всеумиле́нно взива́єм к вам:","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії яви́стеся, святі́ї му́ченици, єгда́ озари́вшеся сві́том і́стиннаго богопозна́нія, ра́достно потеко́сте на страда́льчеський по́двиг. Приймі́те у́бо от нас хвале́бноє пі́ніє сіє́:","Ра́дуйтеся, богоблаже́ннії іспові́дниці правосла́вния ві́ри, іздре́вле насажде́нния в землі́ Россі́йсько-Литовськой;","Ра́дуйтеся, неумолкающії глашатаї і́стиннаго благоче́стія.","Ра́дуйтеся, ве́лії подви́жници, ні во что́же вміни́вшії сла́ву ми́ра сего́, да Христа́ приобря́щете;","Ра́дуйтеся, возлюби́вшії Христа́ Бо́га всім ва́шим се́рдцем і все́ю душе́ю.","Ра́дуйтеся, кро́вію ва́шею запечатлевшії любо́во ва́шу ко Го́споду Ісу́су;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 2","ps":["Ви́дяще, я́ко нетлі́нния мо́щі ва́ша да́рують всім, притекающим с ві́рою, ісціле́ніє от болі́зней душе́вних і тіле́сних, благодари́м милосе́рдаго Бо́га, просла́вившаго вас, святі́ї му́ченици, такою благода́тію, і вопіє́м Христу́ Спаси́телю: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мния очеса́ ва́ша впери́вше в позна́ніє і́стинния ві́ри, ви, святі́ї бра́тія Анто́ніє і Іоа́нне, мужему́дренно отверго́стеся язи́чеськаго прельще́нія, і за іспові́даніє єди́наго і́стиннаго Бо́га ра́достно прия́сте у́зи, темни́чноє заключе́ніє, ра́ни і лю́тую смерть. Таково́му по́двигу ва́шему поревнова́в, і ю́ний Євста́фій, небоя́зненно іспові́дал себі́ християни́на би́ти, і сподо́бился таких же лю́тих за Христа́ муче́ній і сме́рті. За таково́є ва́ше, є́же за Христа́, свято́є дерзнове́ніє взива́єм к вам си́це:","Ра́дуйтеся, блаже́нная тро́йце честни́х страстоте́рпцев, просла́вивших і́стиннаго Бо́га, во Святі́й Тро́йці покланя́ємаго, Отця́, Си́на і Свята́го Ду́ха;","Ра́дуйтеся, до́блії во́їни Христо́ви, сохрани́вшії ві́рность ко Влади́ці до сме́рти.","Ра́дуйтеся, не убоявшіїся претерпі́ти за Христа́ никиїх мук;","Ра́дуйтеся, я́ко ні тіснота́, ні у́зи, ні страда́нія, ні са́мая смерть не могли́ разлучи́ти вас от любве́ Христо́вой.","Ра́дуйтеся, ізгнаннії, поруганнії і убієннії пра́вди ра́ди, я́ко мзда ва́ша мно́га на небесі́;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́ємі, небрего́сте, святі́ї му́ченици, тя́жкаго страда́нія ва́ших тіле́с, пре́данних му́кам, і на муче́нія, а́ки на бра́чний пир, ра́достно теко́сте; ми же благода́рственно взива́єм укріпи́вшему вас Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще крі́пкую наде́жду на Небе́снаго Царя́ і Бо́га і по́мняще апо́стольськоє сло́во, я́ко подоба́єть повинова́тися Бо́гу па́че, не́жели челові́ком, ви, святі́ї му́ченици, не повинустеся велі́нію ва́шего мучи́теля, є́же возврати́тися к пре́жнему язичеському нече́стію:","Ра́дуйтеся, у́бо ісповедавший Христа́ пред челові́ки і от Него́ ісповеданнії пред Отце́м Небе́сним;","Ра́дуйтеся, ві́рнії слузи́ Христо́ви, за ві́рность свою́ наслі́довавшії Ца́рствіє Небе́сноє.","Ра́дуйтеся, сожи́теліє а́нгелом і при́снії всім святи́м;","Ра́дуйтеся, водвореннії в невече́рнім дні Ца́рствія Бо́жия.","Ра́дуйтеся, призирающії с небесі́ на земну́ю бра́тію ва́шу і моля́щіїся о всіх, призива́ющих вас на по́мощ;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 4","ps":["Бу́ря я́рости ва́ших мучи́телей не поколебала крепкой ва́шей ві́ри, наде́жди і любве́ к Спаси́телю Бо́гу, і ви, святі́ї му́ченици, ре́вностно упреждасте друг дру́га в тя́жких страда́ніях, воспіва́я Бо́гу в сердця́х ва́ших: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шана бисть по всей правосла́вной землі́ ра́достная вість, я́ко ви, святі́ї му́ченици, по́двигом до́брим подвиза́стеся, тече́ніє ва́ше до́брі сконча́сте і ві́ру до конця́ соблюдо́сте. Сего́ ра́ди ми со все́ю Правосла́вною Це́рковію ублажа́єм вас:","Ра́дуйтеся, ісполнившії сло́во Христо́во, є́же претерпі́вий до конця́, той спасе́н бу́деть;","Ра́дуйтеся, ва́шим терпі́нієм удиви́вшії мучи́телей ва́ших.","Ра́дуйтеся, приме́ром ва́шей жи́зні і сме́рті обрати́вшії мно́гих ко Го́споду;","Ра́дуйтеся, я́ко і ни́ні чудеса́ми, істека́ющими от святи́х ва́ших моще́й, ви укріпля́єте правосла́вную ві́ру в лю́діх.","Ра́дуйтеся, я́ко за терпі́ніє ва́ше соблюде́ся вам віне́ць пра́вди на небесі́;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 5","ps":["Боготечними звізда́ми правосла́вния ві́ри би́сте ви, святі́ї му́ченици, для ва́ших земни́х соо́тчичей, указу́я для них в Правосла́вной Це́ркві єди́ний наде́жний путь ко спасе́нію, да всі єди́ним се́рдцем і єди́ними усти́ взива́ють спаса́ющему Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діно бисть чу́дноє зна́меніє Бо́жієй бла́гости, єгда́ честно́є мі́сто ва́ших страда́ній озари́л сви́ше о́блачний столп, указу́ющий вам путь к небесі́, я́ко же дре́вле ізра́їльтяном із Єги́пта в зе́млю обітова́нную. Сего́ ра́ди воспіва́єм к вам:","Ра́дуйтеся, ча́да но́ваго Ізра́їля, дости́гшії го́рняго Небе́снаго Ієрусали́ма;","Ра́дуйтеся, до́брі проше́дшії многотру́дноє стра́нствіє ва́ше в пусти́ні сея́ жи́зні і вселившіїся в страні́ обетованной ві́чной.","Ра́дуйтеся, я́ко не Мойсе́й, но Сам Христо́с Бог бисть для вас вожде́м к Небе́сному Оте́чествію;","Ра́дуйтеся, побіди́вшії всіх ва́ших супоста́тов і проти́вников на путі́ к Ца́рствію Небе́сному.","Ра́дуйтеся, блаже́ннії небожители, вкуша́ющії ві́чная бла́га, ї́хже о́ко не ви́ді, і у́хо не сли́ша, і я́же на ум челові́ку не взидо́ша.","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 6","ps":["Пропові́дують святи́я мо́щі ва́ша па́че вся́каго красноречія несомні́нную наде́жду всео́бщаго воскресе́нія, єгда́ Бог, не даю́щий і ни́ні преподо́бним Свої́м ви́діти істлі́ніє, воззове́ть к пакибитію весь род челові́чеський, і всі сподо́бльшіїся ста́ти одесну́ю Престо́ла Госпо́дня воспою́ть Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ но́вий світ для всея́ Россі́йськия землі́, єгда́ милосе́рдий Бог яви́л вели́чіє Свої́х чуде́с над ва́шими нетлі́нними моща́ми, я́же стра́ха ра́ди іноверчеськаго втори́цею сокри́ти би́ша в ні́драх землі́ под спу́дом хра́ма, і отто́лі істочаху оби́льния ісціле́нія всім, с те́плою моли́твою прибегавшим к ва́шей честной іко́ні. Приймі́те же от нас, святі́ї му́ченици, сіє́ усе́рдноє славосло́віє:","Ра́дуйтеся, світоза́рния світи́ла Христо́вой Це́ркві, не могу́щия сокритися под спу́дом;","Ра́дуйтеся, ско́рії врачи́ душ і тіле́с на́ших.","Ра́дуйтеся, защи́тники на́ші от зловрі́дних іноверчеських мудрова́ній;","Ра́дуйтеся, сві́тлії вожди́ на́ші к і́стинному богопознанію і богопочтенію.","Ра́дуйтеся, усердниє моли́твенниці на́ші пред Господом;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 7","ps":["Хотя́ще просла́вити Го́спода Бо́га, ди́внаго во святи́х Свої́х, не обріта́єм дово́льних слов є́же благохвали́ти Єго́ по достоя́нію; но вас, святі́ї му́ченици, призива́єм на по́мощ, молі́теся за ни прилі́жно, да неосужде́нно дерза́єм воспіва́ти Го́споду: Аллилу́я."]},{"h":"Ікос 7","ps":["Новоявленними му́чениками нарекла́ вас Правосла́вная Це́рков, я́ко ма́тер, веселя́щаяся о ча́діх свої́х; і я́коже дре́внії му́ченици по всей вселе́нній свої́ми страданіями утверди́ша Боже́ственную ві́ру, подо́біє їм і ви, новоявленнії му́ченици, та́ко утверди́сте святу́ю ві́ру в мі́сті земна́го оте́чествія ва́шего, я́ко никия ко́зні інові́рія не мо́гуть поколеба́ти єя́, і ми, благодаря́ще, взива́єм к вам:","Ра́дуйтеся, тве́рдії столпи́ правосла́вія, і́ми же красу́ється і укріпля́ється Свята́я Це́рков;","Ра́дуйтеся, іску́снії ко́рмчії, благонаде́жно ві́дущії нас среди́ вре́менних волне́ній к приста́нищу ві́чния жи́зні.","Ра́дуйтеся, споспі́шници на́шего оправда́нія;","Ра́дуйтеся, я́ко моли́твами ва́шими ми ізбавля́ємся от вся́каго лука́ваго прельще́нія, і́щущаго улови́ти душі́ на́ша.","Ра́дуйтеся, благоді́телі на́ші, указу́ющії нам, путь ко спасе́нію.","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 8","ps":["Стра́нноє і для ума́ челові́чеськаго непости́жноє, оба́че явнозримоє на́ми чу́до всемогу́щества Бо́жия явля́ється в нетлі́нії святи́х ва́ших моще́й, я́же бо́льше полутисящи літ пребива́ють невреди́ми от разрушительних стихі́й і от вре́мене всепоядающаго, воздвиза́я нас со умиле́нієм пі́ти Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся ра́дости ві́ка сего́, всю честь ва́шего зва́нія і всю крі́пость ва́ших сил принесо́сте, святі́ї му́ченици, в же́ртву Спаси́телю Бо́гу, і сподо́бистеся от Него́ мздовоздая́нія на небесі́, іді́же ні черв, ні тля тлить, ні та́тіє не подкапивають і не мо́гуть похи́тити дарова́ннаго вам наслі́дія:","Ра́дуйтеся, у́бо, му́дрії іскателі Ца́рствія Бо́жия, подо́бнії єва́нгельському му́жу, і́же обрі́т на селі́ сокро́вище сокрове́нно, вся продає́ть, єли́ка і́мать, і купу́єть то село́ драгоці́нноє;","Ра́дуйтеся, обрі́тшії єди́н многоці́нен би́сер, і́же єсть Ца́рствіє Бо́жиє, і за него́ отдавшії вся бла́га ми́ра сего́.","Ра́дуйтеся, па́че му́дрих ві́ка сего́ уразумі́вшії ці́ну битія́ земна́го;","Ра́дуйтеся, святі́ї пропові́дници, возвещающії нам із ва́шего гро́ба, я́ко недосто́йни суть стра́сті ни́нішняго вре́мені ко хотя́щей яви́тися сла́ві гряду́щаго Ца́рствія.","Ра́дуйтеся, гра́ждане небе́снії і сонаследници всім святи́м;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 9","ps":["Вся́кия ско́рби, болі́зні і прило́ги на́ша ви утоляєте, святі́ї му́ченици, і те́мния зра́ки лука́вих бісо́в дале́че от нас отгоня́єте, да та́ко ва́шею по́мощію, благода́тію же Бо́жиєю спаса́ємі, благода́рним і ра́достним гла́сом воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє немотствуєть, тща́щеєся восхвали́ти вас, святі́ї му́ченици, за ва́ша страда́нія, я́же претерпі́сте Христа́ ра́ди, і за ва́шу му́ченичеськую смерть. Оба́че любо́вію ва́шею побіжда́єми, єли́ко мо́жем, ублажа́єм вас:","Ра́дуйтеся, возвеселившії весь а́нгельський лик ва́шим за Христа́ терпі́нієм і страда́нієм;","Ра́дуйтеся, дружелюбно принятиї на небесі́ от всего́ со́нма пра́ведников і уго́дников Бо́жиїх.","Ра́дуйтеся, я́ко предста́вше Престо́лу Госпо́дню, сподо́билися єсте́ поклони́тися Єму́ і получи́ти от Него́ ві́чную награ́ду;","Ра́дуйтеся, обита́ющії во сві́тлостіх святи́х, іді́же ність болі́знь, ні печа́ль, ні воздиха́ніє.","Ра́дуйтеся, уті́шители всіх гони́мих і терп'я́щих за Христо́ву ві́ру;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 10","ps":["Спасе́нія і ві́чнаго поко́я дости́гше после многоскорбния земни́я жи́зні, ви і нас, святі́ї му́ченици, поучаєте, я́ко єди́н єсть і́стинний путь ко спасе́нію в сем ми́рі злом і лука́вом, є́же вся благоду́шно терпі́ти Христа́ ра́ди, воспіва́юще Єму́ усе́рдно: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ни пеще́рнаго хра́ма, іді́же нетлі́нно почива́ють ва́ша цільбоно́сная тілеса́, просвіща́ються, а́ки небе́сний черто́г, і всі жа́ждущії спасе́нія прибіга́ють к вам, святі́ї му́ченици, с мольба́ми, с благодаре́нієм і с славосло́вієм:","Ра́дуйтеся, помо́щници на́ші в ско́рбіх, болі́зніх і печа́ліх;","Ра́дуйтеся, хода́таї на́ші пред Престо́лом Небе́снаго Судії́ живи́х і ме́ртвих.","Ра́дуйтеся, я́ко нікто́ же прибіга́яй к вам по́мощі ра́ди отхо́дить от вас тощ;","Ра́дуйтеся, щедрії пода́теліє нам Бо́жієй ми́лости.","Ра́дуйтеся, обра́дованнії на небесі́ і нас на землі́ укрепляющії в радостной наде́жде ві́чнаго спасе́нія;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 11","ps":["Пі́нію а́нгельськаго ли́ка на небесі́ совоку́пльше ва́ші преподо́бния гла́си, ви, святі́ї му́ченици, ку́пно с небе́сними чи́ни непреста́нно сла́віте Го́спода Бо́га; і ми, недосто́йнії, упова́юще на милосе́рдіє Бо́жиє, дерза́єм на землі́ бре́нними уста́ми і благода́рним се́рдцем воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рнаго дне всео́бщаго воскресе́нія і стра́шнаго суда́ Бо́жия ча́юще, ужаса́ємся лю́тих на́ших дія́ній і безмі́рних гріхо́в, і́ми же єжеча́сно прогнівля́єм Созда́теля і Спаси́теля на́шего; но імі́я вас, святі́ї му́ченици, предстательствующих за ни пред Господом, благода́рственно взива́єм к вам:","Ра́дуйтеся, я́ко ми по Бо́зі і по Пречи́стой Присноді́ві Богоро́дице все на́ше упова́ніє на нас возлага́єм;","Ра́дуйтеся, я́ко ви не посраміте́ нас от ча́янія на́шего.","Ра́дуйтеся, я́ко моли́твами ва́шими ми упова́єм получи́ти отпуще́ніє гріхо́в і жизнь ві́чную;","Ра́дуйтеся, благослове́ннії Отця́ Небе́снаго, наслі́довавшії угото́ванноє вам Ца́рствіє от сложе́нія ми́ра.","Ра́дуйтеся, я́ко і ми ва́шим заступле́нієм ча́єм ізбіжа́ти участи стоя́щих ошу́юю Престо́ла Судії́;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 12","ps":["Благода́ть чуде́сних ісціле́ній і ско́раго предста́тельства за нас пред Господом іму́ще, не преставайте, святі́ї му́ченици, ви́ну помога́ти нам, сла́в'ящим о вас Христа́ Бо́га і вопію́щим Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ва́ше сві́тлоє прославле́ніє на небесі́ і на землі́, благодари́м Всеми́лостиваго Спа́са і Бо́га на́шего, я́ко содержа́й в Своє́й ру́ці времена́ і лі́та, благоволи́л просла́вити і яви́ти нам вас, святі́ї му́ченици, в благопотре́бноє для на́шего спасе́нія вре́м'я, да не погря́знем в тимі́нії па́губних страсте́й і неразу́мних стремле́ній; сего́ ра́ди возсила́єм к вам на́ше усе́рдноє благохвале́ніє:","Ра́дуйтеся, неуси́пнії стра́жи на́шего спасе́нія, берегущії нас от вся́каго наві́та неприя́зненнаго;","Ра́дуйтеся. Храни́теліє на́ші, удаля́ющії от нас вся́коє вре́дноє іскуше́ніє.","Ра́дуйтеся, іску́снії наста́вници на́ші в непоколеби́мом і тве́рдом іспові́данії правосла́вния ві́ри;","Ра́дуйтеся, громогласнії орга́ни благода́ті Бо́жієй, наполняющей Правосла́вную Це́рков.","Ра́дуйтеся, великії соо́тчичі на́ші, всім нам жела́ющії і помога́ющії спасти́ся;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 13","ps":["О пресла́внії і святі́ї му́ченици: Анто́ніє, Іоа́нне і Євста́фіє! Приймі́те сіє́ ма́лоє, но усе́рдноє моле́ніє на́ше, і хода́тайством на́шим у Христа́ Бо́га ізбавте нас от всіх болі́зней душе́вних і тіле́сних, і от вся́каго прило́га вра́жия, і от вся́кия біди́ і напа́сти, да ви́ну, благодаря́ще о вас Го́спода Бо́га, ра́достно воспіва́єм Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії яви́стеся, святі́ї му́ченици, єгда́ озари́вшеся сві́том і́стиннаго богопозна́нія, ра́достно потеко́сте на страда́льчеський по́двиг. Приймі́те у́бо от нас хвале́бноє пі́ніє сіє́:","Ра́дуйтеся, богоблаже́ннії іспові́дниці правосла́вния ві́ри, іздре́вле насажде́нния в землі́ Россі́йсько-Литовськой;","Ра́дуйтеся, неумолкающії глашатаї і́стиннаго благоче́стія.","Ра́дуйтеся, ве́лії подви́жници, ні во что́же вміни́вшії сла́ву ми́ра сего́, да Христа́ приобря́щете;","Ра́дуйтеся, возлюби́вшії Христа́ Бо́га всім ва́шим се́рдцем і все́ю душе́ю.","Ра́дуйтеся, кро́вію ва́шею запечатлевшії любо́во ва́шу ко Го́споду Ісу́су;","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Кондак 1","ps":["Ізбра́ннії Бо́гом для свиді́тельства правосла́вния ві́ри, му́жеськи попра́сте, святі́ї му́ченици, язи́чеськоє нече́стіє, і за ва́ша страда́нія нетлі́нними вінці́ от Христа́ Бо́га увенчастеся; ті́мже ми, ублажа́юще ва́шу па́м'ять, всеумиле́нно взива́єм к вам:","Ра́дуйтеся, святі́ї му́ченици, Анто́ніє, Іоа́нне і Євста́фіє."]},{"h":"Молитва","ps":["Святі́ї му́ченици Анто́ніє, Іоа́нне і Євста́фіє! При́зріте с небе́снаго черто́га на тре́бующих ва́шея по́мощі, і не отве́ргніте проше́ній на́ших, но я́ко при́снії благоді́телі і хода́таї на́ші, молі́те Христа́ Бо́га, да человіколюби́в і многоми́лостив сий, сохрани́ть нас от вся́каго лю́таго обстоя́нія: от тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, да не осу́дить нас, грі́шних, по беззако́ніям на́шим, і да не во зло обрати́м блага́я, да́руємая нам от Всеще́драго Бо́га, но во сла́ву свята́го і́мені Єго́ і в прославле́ніє крі́пкаго ва́шего заступле́нія; да моли́твами ва́шими дасть нам Госпо́дь мир помисло́в, воздержа́ніє от па́губних страсте́й і от вся́кия скве́рни, і да укріпи́ть во всем ми́рі Свою́ єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков, ю́же стяжа́л єсть честно́ю Своє́ю Кро́вію, да утверди́ть во Святі́й Своє́й Правосла́вній Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, да ми всі в ми́рі і благоче́стії поживе́м в настоя́щем ві́ці і дости́гнем блаже́нния ві́чния жи́зні на небесі́, благода́тію Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва со Отце́м і Святи́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І́же земни́х че́сти і сла́ви отве́ргшеся, / до́блії і честні́ї страда́льці, / ві́ри ра́ди крі́пко і му́жественно му́ки претерпі́сте, / на смерть себі́ вда́вше за Живо́т всіх – Влади́ку. / Ті́мже і Христо́с пресла́вно столпо́м о́блачним / с Небесе́ вас озари́ / і по́честьми і вінці́ от Престо́ла сла́ви вінча́. / Со А́нгели Тому́ предстоя́ще, // молі́те спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["От ко́рене непло́дна, преблаже́ннії, / возрасти́вше Правосла́вния ві́ри ві́тві, / первому́чеником тезоімени́тії яви́стеся: / зла́го бо і нечести́ваго кня́зя я́рости не убоя́стеся, / повеліва́юща Христа́ отрещи́ся. / Сего́ ра́ди му́ченичеськия вінці́ приє́мше / і со А́нгели Престо́лу Влади́чню предстоя́ще, / о нас молі́теся, преблаже́ннії, // правосла́вно чту́щих святу́ю па́м'ять ва́шу."]},{"h":"Кондак, глас 3","ps":["Оте́чеськую пре́лесть оста́вльше, святі́ї, / приведо́стеся Христо́ві, / всім душі́ усе́рдієм ста́сте мужему́дренно до сме́рти. / Ті́мже і взя́сте побі́ди по́честь воі́стину, // о всіх Влади́ку на́шего непреста́нно моля́ще."]},{"h":"Величання","ps":["Велича́єм вас, / страстоте́рпці святі́ї Анто́ніє, Іоа́нне і Євста́фіє, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст праведному Симеону Богоприїмцю","e":"Akathist to the Righteous Symeon the God-Receiver","secs":[{"h":"Кондак 1","ps":["Ізбра́нний в благові́стника явле́нія Христо́ва в челові́ціх, святи́й пра́ведний ста́рче Симео́не, похва́льная пі́нія прино́сим ті, Богоприї́мче, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, Єго́же во об'я́тіях Твої́х носи́л єси́, моли́ спасти́ся нам, любо́вію зову́щим:","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нний."]},{"h":"Ікос 1","ps":["А́нгел Госпо́день по́слан бисть ізві́ствовати ста́рцю Симео́ну, я́ко воі́стину от Ді́ви роди́тися і́мать обетова́нний Спас ми́ру Христо́с. Єгда́ бо той, чту́щу єму́ кни́гу проро́ка Іса́її, дости́же мі́ста, іді́же бі напи́сано: «Се Ді́ва во чре́ві при́йметь і роди́ть Си́на Емману́їла», і недоумева́яй о рече́нних, помишля́ше в себі́, ка́ко мо́гуть сія́ би́ти, тогда́ яви́ся єму́ А́нгел і возвісти́, я́ко не і́мать ви́діти сме́рті, до́ндеже ви́дить ро́ждшагося от Ді́ви Христа́ Госпо́дня. Таково́му ди́вному о нем промишле́нію Бо́жию чудя́щеся, воззове́м к нему́ такова́я:","Ра́дуйся, с сіди́нами ста́рчеськими і му́дрость і́стинную стяжа́вий;","ра́дуйся, Ду́хом Бо́жиїм, я́ко муж пра́веден і благочести́в свиді́тельствованний.","Ра́дуйся, во всіх оправда́ніїх Госпо́дніх непоро́чно і непреткнове́нно ходи́вий;","ра́дуйся, всім житіє́м твої́м Го́сподеві угоди́вий.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 2","ps":["Ви́дя ста́рець, я́ко умножа́ющимся лі́том живота́, умножа́ються єму́ труд і болі́знь, зіло́ скорб'я́ше душе́ю, я́ко продолжи́ся вре́м'я прише́льствія єго́, на землі́ ті́мже жела́ніє іми́й разріши́тися і ко отце́м прейти́, сле́зне прося́ще отпуще́нія себі́, зови́й Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразумі́нний возвіще́нних от А́нгела разумі́ти, ста́рець іща́, недоуміва́ше, в себі́ глаго́ля: что сіє́ єсть стра́нноє і неудо́б сказа́ємоє та́їнство, я́ко Ді́ва во чре́ві зачне́ть і роди́ть Си́на? Єда́ Ді́ва чи́ста, я́ко му́жа не зна́єть, роди́ти мо́жеть, і Кто бу́деть Сей, І́же і́мать роди́тися без му́жа, Син Ді́ви? Па́че же і па́че іспиту́я писа́нії, уразумі́ от них ве́лію сію́ благоче́стія та́йну, я́ко подоба́єть Бо́гу яви́тися во пло́ті, да спасе́ть челові́ка Бо́гом же і челові́ком. Ті́мже ми, ди́вному прему́дрости Бо́жия сові́ту чудя́щеся воспої́м блаже́ннаго сотаї́нника прему́дрости, зову́ще к нему́ такова́я:","Ра́дуйся, я́ко свято́ю жи́знію се́рдце твоє́ очи́стил єси́;","ра́дуйся, я́ко чистото́ю се́рдця пла́менную любо́в к Бо́гу стяжа́л єси́.","Ра́дуйся, я́ко любо́вію к Бо́гу ум твой чист сотвори́л єси́;","ра́дуйся, я́ко чистото́ю ума́ ра́зум Боже́ственних писа́ній уясни́л єси́ себе́.","Ра́дуйся, я́ко разумі́нієм писа́ній к ві́рі во Христа́ приведе́н бил єси́;","ра́дуйся, я́ко ві́рою і упова́нієм к ча́янію уті́хи Ізра́їлевой наста́влен бил єси́.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 3","ps":["Си́ла Ду́ха Бо́жия воздви́же во он день ста́рця прийти́ в це́рков, і єгда́ введо́ста роди́теля Отроча́ Ісу́са, сотвори́ти і́ма по оби́чаю зако́нному о Нем, і той, узрі́в Отроча́, а́біє уразумі́ Ду́хом, я́ко Сей єсть обетова́нний Спас ми́ру Христо́с, і ра́дуяся возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ум зряй к Бо́гу і бив в Ду́сі, прия́т тогда́ ста́рець Симео́н Младе́нця Ісу́са на руку́ своє́ю і благослови́ Бо́га, і рече́ к Марі́ї, Ма́тері Єго́: «Се лежи́ть Сей на паде́ніє і на воста́ніє мно́гим во Ізра́їлі і в зна́меніє преріка́ємо, я́ко да откри́ються от мно́гих серде́ць помишле́нія їх». Таково́му у́бо прозрі́нію свята́го див'я́щеся, ублажи́м Богоприї́мця пі́нії си́ми:","Ра́дуйся, Богові́дче прозорли́вий, Христа́ Госпо́дня, во о́бразі младе́нця четиредесятодне́вна я́вльшася, Ду́хом Бо́жиїм а́біє позна́вий;","ра́дуйся, Богопропові́дниче святи́й, Бо́га Того́ во пло́ті прише́дша, во спасе́ніє ми́ру велегла́сно пропові́давий.","Ра́дуйся, Боголю́бче благочести́вий, прише́ствієм ча́янния тобо́ю уті́хи Ізра́їлевой несказа́нно обра́дованний;","ра́дуйся, Богови́дче преблаже́нний, Бо́га во пло́ті я́вльшася, не у́мними то́чію, но і тіле́снима очи́ма узрі́вий.","Ра́дуйся, Богоприї́мче пра́ведний, всю твар Содержа́щаго дла́нію, ста́рчеськими твої́ми дла́ньми восприя́вий;","ра́дуйся, Богоно́сче і́стинний, Бо́га, Єго́же не́бо і земля́ носи́ти не мо́гуть, во об'я́тіїх твої́х тіле́сні носи́вий.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 4","ps":["Бу́ря внутр помишле́ній трево́жних вни́де в ду́шу Святи́я Богоотрокови́ці, єгда́ благослови́в Ю Симео́н, приложи́ глаго́лати к Ней: «І Тебі́ же само́й про́йдеть ду́шу ору́жіє». Є́же сли́шавше Свята́я Ді́во, пе́рвіє у́бо смути́ся о словесі́ сем, та́же, я́ко раба́ Госпо́дня су́щи, предаде́ Себі́ во во́лю Госпо́дню, зову́щи Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще Іо́сиф і Пречи́стая Ма́тер і Ді́ва ди́вная прорече́нія прозорли́ваго ста́рця об Отроча́те, чудя́хуся о глаго́ланних о Нем. Ма́ти же Єго́ соблюда́ша вся глаго́ли сія́, слага́ющи в се́рдці своє́м. Ті́мже і ми, проро́чеським ди́внаго ста́рця глаго́лом чудя́щеся, воззове́м те́плі єму́ такова́я:","Ра́дуйся, проро́че Бо́жий, проро́чеськаго да́ра бога́тно іспо́лненний; ра́дуйся, дре́вніх проро́ков удобре́ніє і но́вих прови́дцев похвало́.","Ра́дуйся, я́ко страж ві́рен, посреді́ двою́ Заві́тов, Ве́тхаго же і Но́ваго, на боже́ственной стра́жи поста́вленний;","ра́дуйся, отсю́ду мимоше́дшая і гряду́щая ми́ра і ро́да челові́чеськаго єди́ним зрі́нієм о́ка согляда́вий.","Ра́дуйся, я́ко страж ві́рен, неуси́пне бдяй і стрегі́й, прише́дшу Домовлади́ці Христу́, а́біє во срі́теніє ісше́дий;","ра́дуйся, стра́сті Христо́ви єще́ Младе́нцю су́щу Єму́ предуві́дівий, і болі́знь і тугу́ серде́чную Ма́тері Єго́ предсказа́вий.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, предте́чу Боже́ственнаго сві́та зрим тя, Богоприї́мче преблаже́нний. Сей бо, Єго́же світ язи́ком би́ти возвісти́л єси́, возсія́ у́бо просвіще́ніє і́стини во всіх язи́ціх, от ни́хже і ми, сві́том Єго́ просвіще́ннії, благода́рні пі́ти навико́хом Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["«Ви́дісті о́чі мої́ спасе́ніє Твоє́, Влади́ко, є́же угото́вал єси́ пред лице́м всіх люде́й, світ во открове́ніє язи́ком і сла́ву люде́й Твої́х, Ізра́їля», возопи́л єси́, блаже́нне Симео́не, приє́м на руку́ твоє́ю младе́нця Ісу́са, Єму́же ми ни́ні, со стра́хом і любо́вію покланя́ющеся, воспіва́єм ті, я́ко Богоприї́мцю і проро́ку, пі́нія такова́я:","Ра́дуйся, всему́ ми́ру, іуде́єм же і е́ллином, спасе́ніє во Христі́ угото́ванноє, пропові́давий;","ра́дуйся, лю́дем во тьмі і сі́ні сме́ртній сидя́щим, сві́ту возсія́ти їм предвозвісти́вий.","Ра́дуйся, високоме́ріє іуде́єв, мни́вших, я́ко тіх то́чію єсть Ца́рствіє Бо́жиє, уничижи́вий;","ра́дуйся, і язи́ком спасе́ніє во Христі́ Ісу́се благовести́вий.","Ра́дуйся, неві́ріє ожесточе́нних іуде́єв предуві́дівий;","ра́дуйся, спасе́ніє ві́рою во Христа́ ізбра́нних от іуде́єв же і язи́к предуказа́вий.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 6","ps":["Пропові́дник Богоно́сний прише́ствія Христо́ва, всім ча́ющим ізбавле́нія во Ізра́їлі бил єси́, Богоно́се Симео́не. Отто́лі бо нача́ша лю́діє Бо́жії ві́ровати, я́ко прибли́зися к ним Ца́рствіє Бо́жиє, ві́ровавше же поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Ієрусали́му і всей землі́ іуде́йстій просвіще́ніє і́стини сві́том благові́стія твоєго́, пра́ведний ста́рче; се бо і пра́ведная А́нна проро́чиця ви́дящи на руку́ твоє́ю Младе́нця Боголі́пна, і та разумі́в Ду́хом, я́ко Сей єсть прише́дий ізба́вити Ізра́їля, приступи́ в той час і іспові́дашеся Го́сподеві і глаго́лаше о Нем всім ча́ющим ізбавле́нія во Ієрусали́мі. Присту́пим у́бо і ми очище́нним се́рдцем і у́мнима очи́ма, Богомладе́нця на руку́ ста́рчу держи́ма зря́ще, воспої́м сему́ такова́я:","Ра́дуйся, я́ко пе́рвий срі́тил єси́ обітова́ннаго Царя́ Ізра́їлева, іспе́рва прише́дша во град Свой і в дом Отця́ Своєго́;","ра́дуйся, я́ко сла́ву но́ваго Хра́ма па́че сла́ви дре́вняго пе́рвий узрі́л єси́.","Ра́дуйся, я́ко всім ча́явшим ізбавле́нія, ча́янную і́ми уті́ху Ізра́їлеву я́ві указа́л єси́;","ра́дуйся, я́ко возсія́ти звізді́ от Іа́кова і воста́ти челові́ку от Ізра́їля, я́коже прорече́ Валаа́м, лю́дем твої́м благовісти́л єси́.","Ра́дуйся, я́ко благові́стієм твої́м сердца́ упова́вших возвесели́л єси́, малоду́шния же і унива́ющия укріпи́л і уті́шил єси́;","ра́дуйся, я́ко свиді́тельством твої́м о Христі́ і нас во ві́рі і упова́нії утвержда́єши.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 7","ps":["Хотя́щу Симео́ну от ни́нішняго ві́ка преста́витися преле́стнаго, вда́лся єси́ я́ко младе́нець тому́, Влади́ко Го́споди, но позна́лся єси́ єму́ і Бог соверше́нний: ті́мже удиви́ся ста́рець неізрече́нному Твоєму́ снисхожде́нію і ра́дуяся возопи́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вни ді́ла Твоя́, Го́споди, вопія́ше ве́тхий де́нми ста́рець, ко І́же от него́ держи́мому Спа́су ми́ра. А́ще і мню́ся держа́ти Тя я́ко младе́нця, оба́че не аз держу́ Тебі́, но Ти де́ржиши м'я, я́ко Бог і Созда́тель вся́чеських, і я́ко Влади́ка живота́ і сме́рті, де́ржиши м'я і в животі́ сем, ве́тха су́ща ста́рця. Отпусти́ у́бо м'я ни́ні, по глаго́лу Твоєму́ с ми́ром, я́ко ви́дісті о́чі мої́ спасе́ніє Твоє́. Ті́мже ми́рноє от земни́х отше́ствіє свята́го ста́рця сла́в'яще, воззове́м к нему́ такова́я:","Ра́дуйся, я́ко клас зрі́лий пшени́чний на зе́млю, та́ко ти́хо ста́рчеськую главу́ твою́ на ло́же сме́рті склони́вий;","ра́дуйся, я́ко пу́тник да́льним стра́нствієм утомле́нний, ми́рно сном сме́рти почи́вий.","Ра́дуйся, многоле́тнєє тече́ніє твоє́ до́брі во ві́рі і благоче́стії сконча́вий;","ра́дуйся, от вре́меннаго сего́ житія́ в ми́рі глубо́ці к ві́чному поко́ю преста́вивийся.","Ра́дуйся, с наде́ждою ско́раго ізбавле́нія от держа́ви сме́ртния ко отце́м твої́м пресели́вийся;","ра́дуйся, во упова́нії жи́зні ві́чния дух твой ра́достно Го́сподеві преда́вий.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 8","ps":["Стра́нно Бо́га преві́чна, я́ко младе́нця четиредесятодне́вна, на руку́ ста́рчу держи́ма зря́ще, удиві́мся неізрече́нному Того́ нас ра́ди істоща́нію і ум на небеса́ возне́сши, благода́рні воззове́м к Нему́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ жела́ніє і жела́ній кра́ю сладча́йший Ісу́се, взива́ше пра́ведний Симео́н ко І́же во об'я́тіях єго́ носи́му Ізба́вителю ми́ра. Оба́че, узрі́в Тя ни́ні Бо́га преві́чна, что восхощу́ про́чеє ви́діти на землі́: «Отпусти́ у́бо м'я ни́ні, раба́ Твоєго́, Влади́ко, да шед возвіщу́ прише́ствіє Твоє́ во а́ді держи́мим у́зником, с ві́рою Тебі́ ожида́ющим, я́ко да і аз ку́пно с ни́ми ізведе́н бу́ду во оби́телі Ца́рствія Твоєго́, іді́же ви́жду сла́ву Твою́». Ті́мже, блаже́нноє преставле́ніє свята́го ста́рця помина́юще, просла́вим єго́ се́рдцем і усти́ возноси́мими пі́нії си́ми:","Ра́дуйся, благи́й ве́стниче Христо́в і во а́ді от ві́ка содержи́мим у́зником прише́ствіє Єго́ благовести́вий;","ра́дуйся, наде́ждою ско́раго ізбавле́нія ду́ші прароди́телей і пра́отцев возвесели́вий.","Ра́дуйся, ку́пно с ни́ми Христо́м воскре́сшим, побіди́телем сме́рти і а́да, із оби́телей мра́ка ізведе́нний;","ра́дуйся, с со́нмом ізбра́нних Бо́жиїх, в рай сла́дости во оби́теліх небе́сних водворе́нний.","Ра́дуйся, к со́нму святи́х царе́й, проро́ков і первосвяще́нников ветхозаве́тних сопричте́нний;","ра́дуйся, к блаже́нству святи́х небе́сних сил безпло́тних приобще́нний.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 9","ps":["Вся́коє колі́но небе́сних і земни́х і преіспо́дніх покло́ниться о і́мені Ісу́сові, і всяк язи́к іспові́сть, я́ко Госпо́дь Ісу́с Христо́с в сла́ву Бо́га Отця́. Весели́ся у́бо і ра́дуйся, ста́рче пра́ведний, я́ко Сей єсть, Єго́же я́ко Младе́нця ума́лена на руку́ твоє́ю прия́л єси́, і Єму́же ни́ні, я́ко Бо́гу с ли́ки безпло́тних сил на небесі́ зове́ши: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії недоумі́ють ізрещи́ ве́лію сла́ву твою́, святи́й Богоприї́мче Симео́не, є́юже просла́ви тя Христо́с Бог во Ца́рствії сла́ви Єго́. Предстоя́ бо близ Престо́ла Святи́я Тро́йці ку́пно с Пречи́стою Богоро́дицею і Предте́чею Іоа́нном, со дерзнове́нієм мо́лишися о всіх с ві́рою к тебі́ притека́ющих і прося́щих твоєго́ заступле́нія і по́мощі; сего́ ра́ди, сла́в'яще ди́вноє прославле́ніє твоє́ на небесі́ і на землі́, вопіє́м тебі́ такова́я:","Ра́дуйся, я́ко ку́пно со святи́м Предте́чею в неізрече́нной сла́ві близ предстої́ши Престо́лу Святи́я Тро́йці;","ра́дуйся, Єго́же на землі́ Младе́нця ви́діл єси́, Сего́ на небесі́ ни́ні со всі́ми святи́ми зря, ра́дуєшися.","Ра́дуйся, я́ко со Христо́м, Єго́же во об'я́тіїх твої́х носи́л єси́, ни́ні на небесі́ во ві́чній сла́ві Єго́ ца́рствуєши;","ра́дуйся, я́ко с ли́ки А́нгелов на небесі́, трисвято́ю пі́снію Єго́ воспіва́єши.","Ра́дуйся, я́ко ве́ліє дерзнове́ніє і́маши ко Го́споду, Єго́же Младе́нця на руку́ твоє́ю приє́м, Бо́га іспові́дал єси́;","ра́дуйся, я́ко весь мир христия́нський вели́каго предста́теля і хода́тая тя стяжа́.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й от заточе́нія і уз пра́веднаго Петра́ Афо́нськаго, я́ві предста́ єму́ Богопри́їмець в темни́ці, со святи́телем Христо́вим Никола́єм, ди́вен виді́нієм, че́стен о́бразом, во ветхозаве́тнаго свяще́нства єфо́д облече́н, в руці́ же жезл злати́й імі́яй. Ті́мже удиви́ся преподо́бний чу́дному виді́нію сему́, ізведе́н же бив із темни́ці, ра́дуяся возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Цар преві́чний, ди́внаго отсю́ду хода́тая і крі́пкаго засту́пника показа́ нам тебе́, вели́кий уго́дниче Бо́жий Симео́не. Сам бо святи́тель Христо́в Никола́й, хотя́й спасти́ преподо́бнаго, наста́ви єго́ прилі́жно вопи́ти к тебі́ о заступле́нії і по́мощі, многомо́щен бо єси́, глаго́лаше, у Бо́га і ве́ліє дерзнове́ніє і́маши к Нему́. Я́коже у́бо преподо́бнаго Петра́ Афо́нськаго предста́в, спасл єси́, свобо́ду і ізбавле́ніє от уз єму́ дарова́в, та́ко і нас в біда́х і обстоя́ніїх су́щих не укосни́ спаса́ти предста́тельством твої́м, да зове́м ті:","Ра́дуйся, те́плий моли́твенниче о всіх, с ві́рою тебі́ призива́ющих;","ра́дуйся, ско́рий помо́щниче всіх к твоєму́ заступле́нію прибіга́ющих.","Ра́дуйся, я́ко вели́кий во ієра́рсіх святи́тель Христо́в Никола́й, многомо́щнейша ко Христу́ Бо́гу предста́теля тя указа́;","ра́дуйся, я́ко я́влься со святи́телем Никола́єм преподо́бному Петру́ Афо́нському, чуде́сне того́ от уз і темни́ці свободи́л єси́.","Ра́дуйся, я́ко сим єго́ на стезю́ і́ночеськаго житія́ наста́вил єси́;","ра́дуйся, я́ко сим і нас в ну́ждах на́ших прибіга́ти к твоєму́ заступле́нію научи́л єси́.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сить ті весь мир христия́нський, святи́й уго́дниче Бо́жий Симео́не, вели́кий же Но́вград сла́вить тя, я́ко ми́лостиваго ізба́вителя своєго́ от болі́зні і губи́тельства сме́ртнаго. Єгда́ бо пра́ведний гнів Бо́жий пости́же отці́ на́ша і болі́знь сме́ртная нападе́ на ня, благоволи́л Бог яви́ти лю́дем Свої́м цільбоно́сную іко́ну твою́, я́же і до днесь во оби́телі і́ночестей сві́тло сія́єть, благода́ть подаю́щи ісціле́ній всім с ві́рою к тебі́ прибега́ющим, Бо́гу же зову́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная свіща́ би́вшим во тьмі іскуше́ній і бід отце́м на́шим яви́ся чудотво́рная іко́на свята́го Богоприї́мця Симео́на, па́че ча́янія наде́ждою спасе́нія веселя́щи сердця́ їх. Хотя́ бо спасти́ град от губи́тельства сме́ртнаго, преди́вно яви́ся святи́й архієпи́скопу Новгоро́дському Іо́ні, і повелі́ храм оби́денний созда́ти во і́м'я єго́, і ту святу́ю іко́ну єго́ поста́вити, да істоча́єть ісціле́нія лю́дем, в покая́нії с ві́рою к ней прибега́ющим. Сего́ ра́ди пра́ведно сли́шить от нас святи́й чудотво́рець благода́рственная пі́нія такова́я:","Ра́дуйся, гра́да на́шего стіно́ і утвержде́ніє;","ра́дуйся, от смертоно́сния я́зви і губи́тельних болі́зней благонаде́жноє огражде́ніє.","Ра́дуйся, от напа́стей і бід ско́роє ізбавле́ніє;","ра́дуйся, от враг ви́димих і неви́димих мо́щноє защи́щеніє.","Ра́дуйся, во всіх благи́х крі́пкоє вспоможе́ніє;","ра́дуйся, о грісі́х на́ших те́плоє умилостивле́ніє.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 12","ps":["Благода́ть неоску́дних ісціле́ній і істо́чник неізсяка́ємих духо́вних даро́в і во гряду́щая лю́дем оста́вити восхоті́в, человіколю́бець Госпо́дь дарова́ нам пречи́стую іко́ну твою́, святи́й Богоприї́мче Симео́не, от нея́же а́ки от Богоно́сних твої́х рук, держа́щих пода́теля всіх благ Бо́га, ми ни́ні разли́чная дарова́нія приє́млем, благода́рні зову́ще Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще сла́вим многомо́щноє предста́тельство твоє́ і крі́пкоє заступле́ніє о нас грі́шних, святи́й Богоприї́мче Симео́не. Воі́стину бо стіна́ неруши́ма і покро́в держа́вен єси́ гра́ду і оби́телі, в не́йже от літ дре́вніх, я́ко звізда́ світоза́рная, возсія́ нам чудотво́рная іко́на твоя́, к не́йже ми ни́ні припа́дающе і те́плі моля́щеся, тебі́ со слеза́ми взива́єм си́це:","Ра́дуйся, я́ко оби́тель, тобо́ю храни́ма, я́ко многоці́нноє сокро́вище іму́ще честну́ю іко́ну твою́, благода́рні о ней утіша́ється і ра́дується;","ра́дуйся, я́ко хотя́щії благоче́стно жи́ти в ней от іскуше́ній ми́ра, пло́ті і дия́вола покро́вом твої́м огражда́єши.","Ра́дуйся, я́ко до́брі тружда́ющимся помо́щник крі́пок явля́єшися;","ра́дуйся, я́ко скорб'я́щим утіше́ніє, боля́щим ісціле́ніє, малоду́шествующим успокоє́ніє моли́твами твої́ми подає́ши.","Ра́дуйся, я́ко всяк в нужді́ ко святі́й іко́ні твоє́й прибіга́яй, ско́роє утіше́ніє і благовре́менную по́мощ приє́млеть;","ра́дуйся, Богодарова́нноє нам прибі́жище, наде́ждо, покро́в і заступле́ніє на́ше.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 13","ps":["О вели́кий уго́дниче Бо́жий і Богоприї́мче Симео́не! Прийми́ ни́ні ма́лоє сіє́, оба́че от чи́стаго се́рдця приноси́моє тебі́ моле́ніє на́ше, і, я́ко многомо́щний предста́тель ко Христу́ Бо́гу, іспроси́ нам оставле́ніє гріхо́в і ми́рную кончи́ну живота́ на́шего, і ві́чния моли́твами твої́ми ізба́ви нас му́ки, о тебі́ вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел Госпо́день по́слан бисть ізві́ствовати ста́рцю Симео́ну, я́ко воі́стину от Ді́ви роди́тися і́мать обетова́нний Спас ми́ру Христо́с. Єгда́ бо той, чту́щу єму́ кни́гу проро́ка Іса́її, дости́же мі́ста, іді́же бі напи́сано: «Се Ді́ва во чре́ві при́йметь і роди́ть Си́на Емману́їла», і недоумева́яй о рече́нних, помишля́ше в себі́, ка́ко мо́гуть сія́ би́ти, тогда́ яви́ся єму́ А́нгел і возвісти́, я́ко не і́мать ви́діти сме́рті, до́ндеже ви́дить ро́ждшагося от Ді́ви Христа́ Госпо́дня. Таково́му ди́вному о нем промишле́нію Бо́жию чудя́щеся, воззове́м к нему́ такова́я:","Ра́дуйся, с сіди́нами ста́рчеськими і му́дрость і́стинную стяжа́вий;","ра́дуйся, Ду́хом Бо́жиїм, я́ко муж пра́веден і благочести́в свиді́тельствованний.","Ра́дуйся, во всіх оправда́ніїх Госпо́дніх непоро́чно і непреткнове́нно ходи́вий;","ра́дуйся, всім житіє́м твої́м Го́сподеві угоди́вий.","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нне."]},{"h":"Кондак 1","ps":["Ізбра́нний в благові́стника явле́нія Христо́ва в челові́ціх, святи́й пра́ведний ста́рче Симео́не, похва́льная пі́нія прино́сим ті, Богоприї́мче, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, Єго́же во об'я́тіях Твої́х носи́л єси́, моли́ спасти́ся нам, любо́вію зову́щим:","Ра́дуйся, Симео́не, ста́рче пра́ведний, Богоприї́мче преблаже́нний."]},{"h":"Молитва перша","ps":["О вели́кий уго́дниче Бо́жий і Богоприї́мче Симео́не! При́зри на м'я грі́шнаго, ко святі́й іко́ні твоє́й припа́дающа і прося́ща твоєго́ заступле́нія і по́мощі: скорб бо обдержи́ть м'я от обстоя́щих м'я ни́ні бід і зол, і утіше́нія не і́мам многоболі́зненній душі́ моє́й. Іска́х по́мощі от челові́к, і не обрі́теся. Возопія́х ко Го́споду, і не усли́ша м'я, аз прогні́вах пречи́стую бла́гость Єго́ беззако́ньми мої́ми, і мно́жеством мно́гих гріхо́в мої́х преогорчи́х человіколю́бную утро́бу Єго́. І кто мі ни́ні по́мощ яви́ть; кто мі скорб утоли́ть; кто дасть отра́ду і успокоє́ніє многом'яте́жній душе́ моє́й? К тебі́, вели́кий уго́дниче Бо́жий, прибіга́ю грі́шний і недосто́йний аз, ві́дий, я́ко ве́ліє дерзнове́ніє і́маши ко Христу́ Бо́гу і многомо́щен предста́тель єси́ о всіх, с ві́рою к тебі́ прибіга́ющих, і твоєго́ заступле́нія і по́мощі тре́бующих. Моли́ у́бо Человіколю́бця Го́спода, я́ко да прости́в мі безчи́сленная моя́ прегріше́нія, не отврати́ть ми́лость Свою́ от мене́, но я́ко благ і сострада́телен, яви́ть і мні безконе́чноє Своє́ милосе́рдіє, і в лю́тім напа́стей і бід мої́х озлобле́нії пода́сть мі всеси́льную по́мощ Свою́, і преогорче́нной душе́ моє́й осла́бу, мир, укріпле́ніє, утіше́ніє і успокоє́ніє да́руєть. Єй, вели́кий уго́дниче Бо́жий, вознеси́ Богоно́сния ру́ці твоя́ ко І́же во об'я́тіїх твої́х носи́тися ізво́лившему Христу́ Бо́гу на́шему і моли́ бла́гость Єго́, да не отри́неть моле́нія се́рдця моєго́ недосто́їнства ра́ди моєго́, но яви́ть мні благовре́менні ми́лость Свою́, во сла́ву безконе́чних щедро́т Свої́х і многомо́щнаго предста́тельства твоєго́, о не́мже подоба́єть Єму́ вся́кая сла́ва і благодаре́ніє ку́пно со Отце́м і Пресвяти́м Єго́ Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, вели́кий уго́дниче Бо́жий Богоприї́мче Симео́не! Предстоя́ Престо́лу Вели́каго Царя́ і Бо́га на́шего Ісу́са Христа́, ве́ліє дерзнове́ніє і́маши к Нему́, во об'я́тіїх твої́х на́шего ра́ди спасе́нія носи́тися ізво́лившему. К тебі́ у́бо, я́ко многомо́щному предста́телю і крі́пкому о нас моли́твеннику, прибіга́єм ми, грі́шнії і недосто́йнії. Моли́ Бла́гость Єго́, я́ко да отврати́ть от нас гнів Свой, пра́ведно по діло́м на́шим на ни дви́жимий, і, презрі́в безчи́сленная прегріше́нія на́ша, обрати́ть нас на путь покая́нія і на стезі́ за́повідей Свої́х утверди́ть нас. Огради́ моли́твами твої́ми в ми́рі живо́т наш, і во всем благо́м благо́є поспіше́ніє іспроси́, вся я́же к животу́ і благоче́стію потре́бная нам да́руя. Я́коже дре́вле Вели́кий Но́вград явле́нієм чудотво́рния іко́ни твоєя́ от губи́тельства сме́ртнаго ізба́вил єси́, та́ко і ни́ні нас і вся гра́ди і ве́сі страни́ на́шея от вся́ких напа́стей і бід і напра́сния сме́рті предста́тельством твої́м ізба́ви, і от всіх враг ви́димих і неви́димих покро́вом твої́м защити́. Я́ко да ти́хоє і безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́ і, та́ко в ми́рі вре́менноє сіє́ житіє́ преше́дше, во ві́чний дости́гнем поко́й, іді́же сподо́бимся Небе́снаго Ца́рствія Христа́ Бо́га на́шего. Єму́ же вся́кая сла́ва подоба́єть со Отце́м і Пресвяти́м Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Симео́н ста́рець днесь весели́ться, / восприя́т на руку́ свою́ Младе́нця Преві́чнаго Бо́га, / от уз пло́ті разріши́тися прося́ / і вопія́: / ви́діста о́чі мої́ // спасе́ніє Твоє́ ми́рові."]},{"h":"Кондак, глас 4","ps":["Ста́рець днесь отріши́тися от юз, моля́шеся, / се́го житія́ тлі́ннаго, / Христа́ восприя́т на ру́ки, // Зижди́теля і Го́спода."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний Симео́не, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому праведному Павлу Таганрозькому","e":"Akathist to the Holy Righteous Paul of Taganrog","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і уго́дниче Христо́в, путі́ небла́зненнаго ко спасе́нію о́браз подава́яй і ду́ха теплото́ю ми́ра хлад согрева́яй, благода́рно воспіва́єм ті, о́тче Па́вле; ти же, імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́кия ско́рби свободи́ ві́рою зову́щих ті:","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Ікос 1","ps":["А́нгелом уподо́битися возжелі́вий, на землі́ живи́й, богому́дре Па́вле, от ю́ности твоєя́ кра́сная ми́ра сего́ отве́ргл єси́; Христа́ ра́ди земна́я расточи́вий, небе́сная преумно́жил єси́. Ті́мже ни́ні сли́шиши от всіх похвалу́ сицеву́ю:","Ра́дуйся, ві́тве благопло́днаго дре́ва земна́го;","ра́дуйся, сонаслі́дниче Ца́рствія Небе́снаго.","Ра́дуйся, путі́ ті́снаго ко спасе́нію ізбра́ніє;","ра́дуйся, неуси́пноє благода́ті стяжа́ніє.","Ра́дуйся, єва́нгельськаго житія́ о́браз яви́вий;","ра́дуйся, пре́лесть ми́ра тім обличи́вий.","Ра́дуйся, фимія́ме чистоти́ благоуха́нний;","ра́дуйся, сві́том Бо́жия любве́ осія́нний.","Ра́дуйся, утіше́ніє люде́й благочести́вих;","ра́дуйся, похвало́ ієре́єв боголюби́вих.","Ра́дуйся, моли́тви непреста́нноє ді́ланіє;","ра́дуйся, моле́ній ско́роє усли́шаніє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 2","ps":["Ви́дівий ре́вность твою́ о спасе́нії душі́, боголюбе́зне Па́вле, роди́тель твой, про́мислу Бо́жию внем, отпусти́ тя на стезі́ стра́нничества, благослове́ніє ті препода́в; ти же, о го́рнем помишля́я, ви́ну ко Го́споду взива́л єси́: Аллилу́я!"]},{"h":"Ікос 2","ps":["Разумі́ніє богоразу́мноє достоя́ніє твоє́ бисть, блаже́нне Па́вле, я́ко дом о́тчий оста́вил єси́, Ца́рствія Небе́снаго взиску́я, і поко́й тіле́сний презрі́в, в простоту́ і нестяжа́ніє обле́клся єси́; лю́діє же ві́рнії, тща́ніє твоє́ зря́ще, во умиле́нії пою́ть ті:","Ра́дуйся, по́чести ми́ра ні во что́же вміни́вий;","ра́дуйся, стра́нничеськоє житіє́ возлюби́вий.","Ра́дуйся, о смиренному́дрії раді́ніє;","ра́дуйся, в моли́твенном по́двизі поспіше́ніє.","Ра́дуйся, рабо́м свої́м свобо́ду дарова́вий;","ра́дуйся, себі́ раба́ ві́рна Бо́гу сотвори́вий.","Ра́дуйся, поста́ ра́достноє несе́ніє;","ра́дуйся, поко́я тлі́ннаго отверже́ніє.","Ра́дуйся, су́єтнаго бога́тства отврати́вийся;","ра́дуйся, да́ри духо́вними обогати́вийся.","Ра́дуйся, і́стиннаго богопозна́нія обрі́теніє;","ра́дуйся, Про́мисла Госпо́дня явле́ніє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 3","ps":["Си́лою благода́ті сви́ше укріпля́єм, по́двиг пра́веднаго житія́ всему́ ми́ру яви́л єси́, тру́дниче Бо́жий, в трезве́нії же і моли́тві дні і но́щі пребива́я, стро́гостію воздержа́нія плоть умертви́л єси́, я́коже і А́нгелом диви́тися крі́пості твоє́й, воспіва́ющим Творцю́: Аллилу́я!"]},{"h":"Ікос 3","ps":["Імі́я ві́ру непости́дную і любо́в нелицемі́рную ко Го́споду, смиренному́дре Па́вле, ве́ліїх дарова́ній от Него́ удосто́їлся єси́, во є́же наставля́ти заблу́ждшия на стезі́ спасе́нія, глаго́лющим ті:","Ра́дуйся, ізбра́нниче Небе́с преудо́бренний;","ра́дуйся, сосу́де, Свята́го Ду́ха іспо́лненний.","Ра́дуйся, та́йни душ челові́чеських прозрева́яй;","ра́дуйся, судьби́ Бо́жії лю́дем открива́яй.","Ра́дуйся, опло́ті благоче́стія, Про́мислом Бо́жиїм ми́ру явле́нний;","ра́дуйся, світи́льниче, Го́споду возжже́нний.","Ра́дуйся, ві́ру в немощни́х укріпля́яй;","ра́дуйся, вра́жия наві́ти разруша́яй.","Ра́дуйся, неради́вих покая́нноє пробужде́ніє;","ра́дуйся, нечу́вствієм окамене́нних умиле́ніє.","Ра́дуйся, вино́ цельбоно́сноє, ра́ни омива́ющеє;","ра́дуйся, ми́ро чудотво́рноє, сердца́ ісціля́ющеє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 4","ps":["Бу́рею скорбе́й потопля́ємі і в гріхо́вную печа́ль погружа́ємі, с наде́ждею взира́єм на тя, святи́й ко́рмчий, я́ко моли́твою ні́когда мо́ря волне́ніє укроти́вшаго; ті́мже і ни́ні ко бре́гу спасе́нія тобо́ю направля́ємі, с благода́рностію вопіє́м Бо́гові: Аллилу́я!"]},{"h":"Ікос 4","ps":["Сли́шаще о благомо́щії твоє́м, всі тружда́ющіїся і обремене́ннії притека́ють к тебі́, уго́дниче Христо́в, зане́ воі́стину подає́ть Госпо́дь моли́твами твої́ми поко́й і ра́дованіє всім, та́ко велича́ющим тя:","Ра́дуйся, в ско́рбі ра́дости подая́ніє;","ра́дуйся, во отча́янії луче́ спасе́нія.","Ра́дуйся, благопристу́пний уті́шителю;","ра́дуйся, неістощи́мий ми́лости пода́телю.","Ра́дуйся, чад наде́жноє сохране́ніє;","ра́дуйся, неду́гов їх во здра́віє преложе́ніє.","Ра́дуйся, роди́тельськия сле́зи осуша́яй;","ра́дуйся, упова́нію на Го́спода науча́яй.","Ра́дуйся, укроще́ніє стихі́ї страсте́й;","ра́дуйся, разсі́яніє мгли напа́стей.","Ра́дуйся, лампа́до неугаси́мая доброде́ланія;","ра́дуйся, свіще́ присногоря́щая милосе́рдія.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 5","ps":["Богопросвіще́нний ра́зум стяжа́в, любому́дре Па́вле, о спасе́нії бли́жніх раді́л єси́ і, труди́ человіколю́бія неосла́бне творя́, тіх науча́л єси́ возноси́ти хвалу́ Бо́гу: Аллилу́я!"]},{"h":"Ікос 5","ps":["Ви́дяще по́двиги твоя́, душеве́дче Па́вле, ні́кий тщесла́вний челові́к с надме́нієм дерза́ше подража́ти тебі́; оба́че ти, вну́тренняя прозрева́я, ве́тхому ме́ху того́ уподо́бил єси́. Помози́ і нам, свя́те, тщесла́віє побіжда́ти і сіте́й вра́жиїх ізбіга́ти, вопію́щим такова́я:","Ра́дуйся, ві́ри богоізбра́нний учи́телю;","ра́дуйся, усе́рдія самочи́ннаго обличи́телю.","Ра́дуйся, прельще́нних нело́жноє вразумле́ніє;","ра́дуйся, го́рдості умовре́дния посрамле́ніє.","Ра́дуйся, ста́рче, сокрове́нная устроя́яй;","Ра́дуйся, о́тче, в послуша́нії чад твої́х наставля́яй.","Ра́дуйся, я́ко всему́дренні ду́ші врачу́єши;","ра́дуйся, я́ко смире́нія о́браз показу́єши.","Ра́дуйся, плодо́в духо́вних умноже́ніє;","ра́дуйся, пра́веднаго житія́ зна́меніє.","Ра́дуйся, кро́тости Христо́вой уподобле́ніє;","ра́дуйся, землі́ блаже́нних насле́дованіє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 6","ps":["Пропові́дуя житіє́м твої́м світ Єва́нгелія во тьмі гріхо́вній пребива́ющим, ві́рний ра́бе Бо́жий, на распу́тіїх призива́л єси́ на пир бра́чний ни́щія і бі́дния, сліпи́я і хроми́я, да возвели́чать і́м'я Госпо́днє, немо́лчно пою́ще: Аллилу́я!"]},{"h":"Ікос 6","ps":["Возсія́нієм риз твої́х, досточу́дне Па́вле, я́ко світови́ден столп яви́ тя Госпо́дь лю́дем Свої́м, див'я́щимся сни́тію сви́ше на тебі́ благода́ті і слав'я́щим тя:","Ра́дуйся, любо́вію О́тчею осія́нний;","ра́дуйся, дари́ Свята́го Ду́ха сниска́вий.","Ра́дуйся, і́м'я Христо́во непреста́нно помина́вий;","ра́дуйся, Стра́сті Єго́ благогові́йно почита́вий.","Ра́дуйся, слу́жби Бо́жия ревни́телю;","ра́дуйся, благолі́пія хра́мов попечи́телю.","Ра́дуйся, ві́рности Пресвяті́й Тро́йце горе́ніє;","ра́дуйся, при́сноє па́м'ятованіє о спасе́нії.","Ра́дуйся, сердца́ я́ко лампа́ди возжига́вий;","ра́дуйся, в ду́сі любве́ наслі́діє воспита́вий.","Ра́дуйся, скрижа́ле, Творце́м начерта́нная;","ра́дуйся, броне́ пра́вди, во бра́ні іспита́нная.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 7","ps":["Не хотя́ утаї́ти безві́стная і та́йная прему́дрости Бо́жия, ди́вний ста́рче, священної́ноку єди́ному предре́кл єси́ служе́ніє ве́ліє во гра́ді Ієрусали́мсті; внегда́ же ви́діти тому́ сверше́ніє проро́чества, хвалу́ Ви́шнему вознесе́: Аллилу́я!"]},{"h":"Ікос 7","ps":["Новозаве́тнаго открове́нія прия́телище і за́повідей Госпо́дніх усе́рдний ісполни́телю, Христа́ всім се́рдцем возлюби́л єси́, подо́бні і і́скренняго своєго́ до конця́; сего́ ра́ди ни́ні сли́шиши благода́рноє пі́ніє:","Ра́дуйся, блаже́нство єва́нгельськоє ізбра́вий;","ра́дуйся, наслажде́ніє тлі́нноє попра́вий.","Ра́дуйся, одія́ніє смире́нія боготка́нноє;","ра́дуйся, ковче́же ми́лости Боже́ственния.","Ра́дуйся, тала́нти земни́я умно́живий;","ра́дуйся, сокро́вища небе́сная собра́вий.","Ра́дуйся, озаре́ніє сви́ше приє́мий;","ра́дуйся, от ізби́тка се́рдця бли́жнему подава́вий.","Ра́дуйся, водо́ю живо́ю ду́ші напоя́яй;","ра́дуйся, ко Істо́чнику жи́зні обраща́яй.","Ра́дуйся, со́ле землі́, є́юже да осолі́мся;","ра́дуйся, сві́те ми́ру, і́мже да просвіті́мся.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 8","ps":["Стра́нничеством дух укріпля́я, богоблаже́нне, пришле́ць на землі́ яви́лся єси́, к небе́сному же оте́честву устремля́яся, о́браз ревнова́нія о го́рнем показа́л єси́ взиску́ющим Го́спода і вопію́щим: Аллилу́я!"]},{"h":"Ікос 8","ps":["Всім вся бил єси́, о́тче Па́вле, собира́я о́вці под кров твой і путь спасе́нія сим указу́я, ста́рця тя нариця́ющим і глаго́лющим ті:","Ра́дуйся, Спа́су Христу́ послужи́вий;","ра́дуйся, па́ству Єго́ соблюди́й.","Ра́дуйся, ка́ющихся і заблу́ждших окормле́ніє;","ра́дуйся, о Бо́зі стра́нствующих попече́ніє.","Ра́дуйся, сві́том ду́ха омраче́нния озаря́яй;","ра́дуйся, по́мощію многочу́дною тіх осіня́яй.","Ра́дуйся, ізсо́хших душ любо́вію ороше́ніє;","ра́дуйся, в сих благода́рности Созда́телю взра́щеніє.","Ра́дуйся, оти́шіє наде́жноє стра́ждущих;","ра́дуйся, насище́ніє а́лчущих і жа́ждущих.","Ра́дуйся, дво́ре, от стужа́ющих укрива́яй;","ра́дуйся, ста́рче, во оби́телі Отця́ Небе́снаго приводя́й.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 9","ps":["Вся́ким глаго́лом, ісходя́щим із уст Бо́жиїх, пра́ведне Па́вле, живи́й, неуста́нний пропові́дник прича́стія Святи́х Та́їн яви́лся єси́, о єди́нім Хлі́бе Небе́снім всіх, приходя́щих к тебі́, пещи́ся наставля́я і поуча́я Бо́гу воспіва́ти: Аллилу́я!"]},{"h":"Ікос 9","ps":["Вети́йство суєсло́вноє презрі́в, честни́й Па́вле, му́дрость єва́нгельськия простоти́ ізбра́л єси́, науча́я чи́стим се́рдцем сла́вити Го́спода. Ті́мже взива́єм ті:","Ра́дуйся, у́мния моли́тви ді́лателю;","ра́дуйся, покая́нія возвісти́телю.","Ра́дуйся, нищету́ духо́вную стяжа́вий;","ра́дуйся, помишле́нія твоя́ го́ре воздвиза́вий.","Ра́дуйся, в Бо́жиїх свиді́ніїх наставле́ніє;","ра́дуйся, із сіте́й безве́рія ізбавле́ніє.","Ра́дуйся, я́ко любе́зні с кро́ткими бесі́довал єси́;","ра́дуйся, я́ко ро́пщущих прему́дро увіщава́л єси́.","Ра́дуйся, гордели́ваго разжже́нія угаше́ніє;","ра́дуйся, хла́дних серде́ць возгре́яніє.","Ра́дуйся, мре́же, Христу́ челові́ков уловля́ющая;","ра́дуйся, земле́, сі́м'я до́броє прозяба́ющая.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 10","ps":["Спасе́нія хотя́ коєму́ждо, милосе́рдні Па́вле, бли́жніх к покая́нію призива́л єси́; де́нно і но́щно о сих моли́тви со слеза́ми вознося́, непреста́нно вопія́л єси́ к Бо́гу: Аллилу́я!"]},{"h":"Ікос 10","ps":["Сті́ни ка́менния темни́ці не возбрани́ша любві́ твоє́й к заключе́нним дости́гнути, і́бо ра́ди Христа́ ми́лость сію́ твори́л єси́, заточе́нних печа́льниче, а́лчущих пита́я, жа́ждущих напоя́я, наги́х одіва́я. Ті́мже прийми́ от нас славосло́віє сицево́є:","Ра́дуйся, десни́це щедро́т неоскудіва́ющая;","ра́дуйся, руко́, із пучи́ни бід ізвлека́ющая.","Ра́дуйся, призрі́ніє ни́щих і оби́димих;","ра́дуйся, приста́нище ти́хоє томи́мих.","Ра́дуйся, сле́зних проше́ній благоприя́тіє;","ра́дуйся, сокрове́нним воздиха́нієм вня́тіє.","Ра́дуйся, я́ко рида́ющих на пе́рси приє́млеши;","ра́дуйся, я́ко немощни́х на рамена́ под'є́млеши.","Ра́дуйся, вся́кия тісноти́ разріши́телю;","ра́дуйся, во обстоя́ніїх су́щих ізба́вителю.","Ра́дуйся, несокруши́мий наш засту́пниче;","ра́дуйся, добропобі́дний миротво́рче.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 11","ps":["Пі́ніє ра́достні творя́ще, святі́ї А́нгели вознесо́ша на не́бо ду́шу твою́, пра́ведниче Па́вле, да уві́дять тя ізбра́нника Бо́жия всі сумня́щіїся, і прозре́вше возопію́ть Вседержи́телю: Аллилу́я!"]},{"h":"Ікос 11","ps":["Світозаре́нієм со́лнця сликовству́єть небе́сная Це́рков Це́ркві земно́й о пренесе́нії честни́х моще́й твої́х, святи́й Па́вле, і прославля́юще просла́вльшаго тя Бо́га, воспіва́ють ті А́нгели і челові́ци:","Ра́дуйся, звіздо́, на тве́рди церко́вній явле́нная;","ра́дуйся, сві́том Со́лнця пра́вди Христа́ озаре́нний.","Ра́дуйся, я́ко в тебі́ благода́ть Бо́жия яви́ся;","ра́дуйся, я́ко лик святи́х і́менем твої́м украси́ся.","Ра́дуйся, Небе́сния Трапе́зи прича́стниче;","ра́дуйся, на землі́ оста́вльшихся печа́льниче.","Ра́дуйся, гра́да при мо́рі покрови́телю;","ра́дуйся, Гра́да Небе́снаго жи́телю.","Ра́дуйся, пла́чущим обетова́нноє утіше́ніє;","ра́дуйся, сі́тованія в ра́дость претворе́ніє.","Ра́дуйся, наде́ждо, проше́нія предваря́ющая;","ра́дуйся, упова́ніє, тьму уни́нія разгоня́ющеє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 12","ps":["Благода́тния по́мощі кла́дязь неізсяка́ємий ти єси́, святи́й Па́вле, животворя́щую бо твою́ к нам любо́в і по успе́нії твоє́м явля́єши, неуста́нно моля́ся о нас пред Престо́лом Госпо́днім, да попече́нієм такови́м во ві́рі укріпля́ємі, Бо́гу непреста́нно сла́ву возсила́єм: Аллилу́я!"]},{"h":"Ікос 12","ps":["Поє́м многосла́вимия по́двиги твоя́, земни́й а́нгеле, поєли́ку чудеса́ твоя́ умно́жишася зіло́, і, ублажа́юще тебі́ я́ко многомо́щнаго о нас предста́теля, восхваля́єм тя:","Ра́дуйся, умире́нія оби́льний істо́чниче;","ра́дуйся, благоуві́тливий в ско́рбіх помо́щниче.","Ра́дуйся, духо́вних болі́зней ісціле́ніє;","ра́дуйся, тіле́сних неду́гов врачева́ніє.","Ра́дуйся, сосу́де єле́я освяще́ннаго;","ра́дуйся, пшени́ці чи́стая, благослове́нная.","Ра́дуйся, цві́те цілому́дрія богоро́сний;","ра́дуйся, дре́во доброді́телей плодоно́сноє.","Ра́дуйся, отча́янних крі́пкоє наді́яніє;","ра́дуйся, путе́й непра́ведних ісправле́ніє.","Ра́дуйся, неосла́бноє о ча́діх твої́х предста́ніє;","ра́дуйся, Го́спода ві́рноє достоя́ніє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 13","ps":["О, чудотво́рче преди́вний і пресла́вний, святи́й пра́ведний Па́вле! Ни́нішнєє на́ше приє́м приноше́ніє, не оста́ви нас, в не́мощіх і нестроє́ніїх су́щих, гріхи́ мно́гими обремене́нних, бу́ди нам помо́щник необори́мий, моли́твенник дерзнове́нний і хода́тай усе́рдний, на Стра́шнім же суди́щі Христо́ві іспроси́ нам удела ізбра́нних, да сподо́бимся с тобо́ю воспіва́ти Бо́гу: Аллилу́я!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом уподо́битися возжелі́вий, на землі́ живи́й, богому́дре Па́вле, от ю́ности твоєя́ кра́сная ми́ра сего́ отве́ргл єси́; Христа́ ра́ди земна́я расточи́вий, небе́сная преумно́жил єси́. Ті́мже ни́ні сли́шиши от всіх похвалу́ сицеву́ю:","Ра́дуйся, ві́тве благопло́днаго дре́ва земна́го;","ра́дуйся, сонаслі́дниче Ца́рствія Небе́снаго.","Ра́дуйся, путі́ ті́снаго ко спасе́нію ізбра́ніє;","ра́дуйся, неуси́пноє благода́ті стяжа́ніє.","Ра́дуйся, єва́нгельськаго житія́ о́браз яви́вий;","ра́дуйся, пре́лесть ми́ра тім обличи́вий.","Ра́дуйся, фимія́ме чистоти́ благоуха́нний;","ра́дуйся, сві́том Бо́жия любве́ осія́нний.","Ра́дуйся, утіше́ніє люде́й благочести́вих;","ра́дуйся, похвало́ ієре́єв боголюби́вих.","Ра́дуйся, моли́тви непреста́нноє ді́ланіє;","ра́дуйся, моле́ній ско́роє усли́шаніє.","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і уго́дниче Христо́в, путі́ небла́зненнаго ко спасе́нію о́браз подава́яй і ду́ха теплото́ю ми́ра хлад согрева́яй, благода́рно воспіва́єм ті, о́тче Па́вле; ти же, імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́кия ско́рби свободи́ ві́рою зову́щих ті:","Ра́дуйся, святи́й пра́ведний Па́вле, преди́вний чудотво́рче!"]},{"h":"Молитва","ps":["О, вели́кий уго́дниче Бо́жий і чудотво́рче, о́тче Па́вле! Ти, на висоту́ доброді́телей возше́д, я́ко пресві́тлая звізда́, житіє́м твої́м возсія́л єси́ і, стра́нничеськоє жи́тельство ізбра́в, ми́ра сего́ кра́сная ні во что́же вміни́л єси́. Ті́мже Всепра́ведний Судія́ мно́гими чудеси́ тя просла́ви, ду́шу же твою́ святу́ю в небе́сния оби́телі всели́, іді́же, любве́ Бо́жия наслажда́яся, на́ша ну́жди зри́ши і проше́нія сли́шиши. Сего́ ра́ди бу́ди нам в неду́зіх ціли́тель, по мо́рю пла́вающим ко́рмчий, і утопа́ющим благонаде́жноє ізбавле́ніє. О, Па́влі блаже́нне, іспроси́ всем, во вся́цій ну́жді су́щим, і ко твоєму́ засту́пленію прибега́ющим, вся́кий дар коєму́ждо благопотре́бен: ві́ри і любве́ преспі́яніє, благоче́стія умноже́ніє, ми́ра утвержде́ніє, больни́м ісціле́ніє, печа́льним утіше́ніє, бе́дствующим по́мощ, оби́димим заступле́ніє. І сподо́би ни, уго́дниче Бо́жий, моли́твами твої́ми благоче́стно житіє́ земно́є сконча́ти, Небе́сноє Ца́рствіє і живо́т ві́чний унаслі́дити со всі́ми святи́ми во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Взиску́я Оте́чества Небе́снаго, / дом роди́телей твої́х оста́вил єси́ / і, тлі́нная бога́тства ми́ра презрі́в, / воздержа́нієм і труди́ моли́тву у́мную стяжа́л єси́. / Ті́мже, мно́гими чудеси́ і зна́меньми от Го́спода просла́вився, / с ві́рою приходя́щим к тебі́ во вся́ціх напа́стіх помога́єши: / пра́ведне о́тче Па́вле, / моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Си́лу Бо́жию в не́мощі стяжа́л єси́ / і боже́ственния благода́ті сосу́д ізбра́нний яви́лся єси́, / ті́мже от Небе́сного Врача́ дар ісціле́нія приї́м, / неду́ги на́ша тіле́сния і душе́вния врачу́єши, / пра́ведне о́тче Па́вле, моли́ Христа́ Бо́га / спасти́ град і лю́ди, тя почита́ющия."]},{"h":"Величання","ps":["Ублажа́єм тя, святи́й блаже́нний о́тче Па́вле, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому преподобному Феодосію Кавказькому","e":"Akathist to our Venerable Father Theodosius of the Caucasus","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і пресла́вний чудотво́рче, преподо́бне о́тче Феодо́сіє, по́двиги твої́ми А́нгели удиви́вий і челові́ки мно́гія із глубини́ гріхо́вния ізведи́й, умоли́ і о нас просла́вльшаго тя Го́спода і от бід і напа́стей нас свободи́, любо́вію зову́щих ті:","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ тя от чре́ва ма́тере твоєя́ і в рождестві́ твоє́м показа́ зна́меніє бу́дущаго і́ночеськаго житія́ твоєго́, да бу́деши, богоблаже́нне Феодо́сіє, моли́твенник ко Го́споду і Пречи́стій єго́ Ма́тері за весь мир. Ми же, грі́шнії, упова́юще на ско́рую по́мощ твою́, взива́єм ті си́це:","Ра́дуйся, от чре́ва ма́тере Господом ізбра́нний;","ра́дуйся, єще́ в детстві к служе́нію Бо́гу преднареченний.","Ра́дуйся, в рождестві́ твоє́м чу́дноє зна́меніє мона́шеськаго житія́ яви́вий;","ра́дуйся, в ю́ності строгость і́ночеськаго житія́ показа́вий.","Ра́дуйся, Христа́ всім се́рдцем возлюби́вий;","ра́дуйся, ум і се́рдце Го́споду преда́вий.","Ра́дуйся, наро́да россі́йськаго моли́твенноє огражде́ніє;","ра́дуйся, землі́ Кавкаськия свяще́нноє украше́ніє.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь благо́є се́рдця твоєго́ ізволе́ніє, я́ко от младе́нчества імі́л єси́ ве́лію любо́в к Нему́ і немо́лчно прославля́л єси́ І́м'я Госпо́днє, угото́ва ті а́нгельськоє житіє́ во Святі́й Горі́ Афо́нстій, іді́же во смире́нії і послуша́нії научался єси́ Єди́наго Бо́га люби́ти і Того́ ра́ди вся земна́я презира́ти, вопія́ Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́н імі́я, преподо́бне о́тче Феодо́сіє, на Раєвом ка́мні от младе́нчества моли́тися Бо́гу нави́кл єси́, ві́ру крі́пкую, наде́жду несумні́нную, любо́в і́стинную к Нему́ стяжа́л єси́ і стопи́ своя́ ко Святі́й Горі́ Афо́нстій направи́л єси́, тім же ублажа́єм тя си́це:","Ра́дуйся, от младе́нчества моли́тву ко Го́споду творивий;","ра́дуйся, ви́ну любо́вію пла́менною к Нему́ горевий.","Ра́дуйся, на Свято́й Горі́ Афо́нстій во отро́честві чин а́нгельський принявий;","ра́дуйся, та́мо мно́гая послуша́нія понеси́й.","Ра́дуйся, усе́рдний к Бо́гу і Ма́тері Бо́жієй моли́твенниче;","ра́дуйся, покая́нія пропові́дниче.","Ра́дуйся, скорб'я́щим ско́роє утіше́ніє і вразумле́ніє;","ра́дуйся, при́сноє і нело́жноє їх умире́ніє.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лу, да́нную ті сви́ше, принял єси́, преподо́бне о́тче Феодо́сіє, ізгоня́ти вся́кую си́лу вра́жию. І того́ ра́ди с кро́тостію і смире́нієм уврачева́л єси́ одержи́мую бісо́м жену́ знатную, да сіє́ чу́до ви́дяще, всі лю́діє просла́виша Бо́га, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще тя, ізря́дний уго́дниче Христо́во Феодо́сіє, воітеля проти́ву си́ли бісо́вськия, те́плаго моли́твенника і предста́теля пред Го́сподем о нас, недосто́йних, любо́вію твоє́ю побіжда́єми, со умиле́нієм зове́м ті:","Ра́дуйся, мно́гія да́ри духо́вния от Го́спода получи́вий;","ра́дуйся, ті́миже ко́зні дия́вольськия побіди́вий.","Ра́дуйся, жену́, бісо́м одержи́мую, во отро́честві твоє́м ісціли́вий;","ра́дуйся, плотські́я по́хоті умертви́вий.","Ра́дуйся, си́лу чуде́с Бо́жиїх яви́вий;","ра́дуйся во́їне Христо́в добропобі́дний.","Ра́дуйся, предста́телю о нас к Бо́гу і Богоро́дице непости́дний;","ра́дуйся, Небе́снаго Царя́ ізбра́нниче преди́вний.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю гні́ва непра́веднаго от бра́тії претерпі́л єси́, блаже́нне Феодо́сіє, і́миже в нечистоти́ вве́ржен, Пречи́стою же Богоро́дицею чуде́сно ізвлече́н бил єси́. Сего́ ра́ди, зря́ще о тебі́ таково́є Ма́тере Бо́жия благоволе́ніє, вопіє́м Всеви́шнему Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о би́вшем на тебі́ чуде́снім ізлія́нії ми́лости Пресвяти́я Ді́ви Марі́ї і Архистрати́га Бо́жия Михаї́ла, ми, грі́шнії, прославля́єм ди́внаго во святи́х Свої́х Го́спода і Єго́ Пречи́стую Ма́тер со Арха́нгелом і вопіє́м ті:","Ра́дуйся, Цари́цею Небе́сною от сме́рти спасе́нний;","ра́дуйся, Архистрати́гом Михаї́лом от посрамле́нія ізба́вленний.","Ра́дуйся, ті́сний путь спасе́нія возлюби́вий;","ра́дуйся, яре́м Госпо́день на ви́ю свою́ возложи́вий.","Ра́дуйся, от бра́тії в монастирі́ вся́чеськая поноше́нія претерпі́вий;","ра́дуйся, незло́біє младе́нчеськоє імі́вий.","Ра́дуйся, ра́бе Госпо́день благи́й і ві́рний;","ра́дуйся, ско́рий помо́щниче всім скорб'я́щим і обремене́нним.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 5","ps":["Боже́ственний Огнь благода́тний ви́дя, на Гро́бі Госпо́днем во Вели́кую Суббо́ту чуде́сно возгораємий, і сим Огне́м освяще́нний, мно́гіє годи послужи́л єси́, преподо́бне о́тче Феодо́сіє, во Святі́й Земле́, ви́ну взива́я Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще тя оча́ми ві́ри ча́да твоя́, преподо́бне о́тче Феодо́сіє, со благогові́нієм у Гро́ба Госпо́дня служа́ща і со дерзнове́нієм Єму́ мольби́ о страні́ Росси́йстій принося́ща, удивле́нієм об'яти, благода́рно вопіє́м ті:","Ра́дуйся, во Землі́ Святі́й благода́тно пожи́вий;","ра́дуйся, по стопа́м Спаси́теля ходи́вий.","Ра́дуйся, Огне́м благода́тним освятивийся;","ра́дуйся, любовю к Бо́гу воспламенивийся.","Ра́дуйся, пред Гробо́м Госпо́днім служи́телю усе́рдний;","ра́дуйся, моли́твенниче к Бо́гу і Богоро́дице о нас неуси́пний.","Ра́дуйся, ві́ру Христо́ву ми́ру явля́яй;","ра́дуйся, всю́ду Христа́ прославля́яй.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник смире́нія і покая́нія бил єси́, о́тче, приме́ром житія́ твоєго́ незло́біє і всепроще́ніє показу́я, я́коже світи́ло многосві́тлоє тьму неві́дінія і уни́нія от приходя́щих к тебі́ отгонял єси́ і всіх увіщева́л плоть ду́хові покоря́ти і чи́стим се́рдцем пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Приє́мий от Го́спода благода́ть разумі́нія о Пресвяті́й Тро́йце на Афо́нстій Го́ре, во Ієрусали́мі і Царграде, в землі́ Росси́йстій Правосла́вния ві́ри пропові́дник яви́лся єси́. Ми же, ві́рующе правосла́вно во Святу́ю Тро́йцю, с любо́вію вопіє́м ті:","Ра́дуйся, ві́ри Правосла́вния пропові́дниче;","ра́дуйся, преди́вний Бо́жий ізбра́нниче.","Ра́дуйся, усе́рдно призива́ющим тя помо́щниче;","ра́дуйся, до́брий стада́ своєго́ наста́вниче.","Ра́дуйся, люде́й землі́ Россі́йськия усе́рдний засту́пниче;","ра́дуйся, к Бо́гу і Богоро́дице непреста́нний о них моли́твенниче.","Ра́дуйся, Ца́рствія Небе́снаго наслі́дниче;","ра́дуйся, ві́ри Христо́вой дерзнове́нний іспові́дниче.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти в тебі́, преподо́бне, Своє́ неізрече́нноє к людям милосе́рдіє, показа́ тя, я́ко воі́стину світи́ло богосві́тлоє: ско́рим твої́м хода́тайством чудеса́ мно́гая і пресла́вная соверша́ються. Ти же, ста́рче, і при жи́зні дости́г посіще́нія небе́сних служи́телей, благода́рні прославля́я Всеви́шняго Бо́га: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго ви́дяще тя ізбра́нника Бо́жия, іздале́ча притека́ху к тебі́ ві́рнії в ско́рбіх і болі́зніх, єгда́ істо́чник в пусти́ні іскопа́л єси́, ста́рче Феодо́сіє, і благода́ть на во́ду сію́ у Пресвяти́я Тро́йці іспроси́л єси́ ісціля́ти тіле́сния і душе́вния неду́ги. Сего́ ра́ди взива́єм ті:","Ра́дуйся, ста́рче, ра́бе Госпо́день;","ра́дуйся, ві́рний істо́чниче благода́тний.","Ра́дуйся, духо́вною пи́щею а́лчущия пита́яй;","ра́дуйся, свято́ю водо́ю із істо́чника твоєго́ ві́рним жа́жду утоля́яй.","Ра́дуйся, при жи́зні посіще́нія Цари́ці Небе́сния сподо́бивийся;","ра́дуйся, і святи́ми небожи́телями не оста́вленний.","Ра́дуйся, я́ко благослове́нієм і сові́ти людям ві́рующим помога́яй;","ра́дуйся, всіх с ві́рою к тебі́ притека́ющих на путь спасе́нія наставля́яй.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до дарова́л ті Госпо́дь, преподо́бне о́тче Феодо́сіє, дар моли́твенний, живи́х заступающий і от а́да спаса́ющий. Ми же Го́споду на́шему, дарова́вшему нам, на Кавказі живу́щим, такова́го моли́твенника і хода́тая о нас, вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ Христу́ от чре́ва ма́терняго пре́дал єси́, блаже́нне Феодо́сіє, умиле́нним се́рдцем і сокруше́нною душе́ю Тому́ всегда́ предстоя́ і духо́вная ча́да твоя́ науча́я храни́ти смире́ніє і самоукоре́ніє і дар умиле́нія стяжа́ти. Сія́ ві́дяще, восхваля́єм тя си́це:","Ра́дуйся, Безкро́вния Же́ртви досто́йний соверши́телю;","ра́дуйся, Алтаря Госпо́дня благогові́йний служи́телю.","Ра́дуйся, дарова́ній духо́вних світи́льниче;","ра́дуйся, но́вия оби́телі і́ночеськия нача́льниче.","Ра́дуйся, заточе́ніє Христа́ ра́ди претерпі́вий;","ра́дуйся, ізгна́ніє бли́жнім предсказавий.","Ра́дуйся, лю́б'ящим і чту́щим тя хода́таю спасе́нія;","ра́дуйся, приводя́й грі́шников ко ісправле́нію.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 9","ps":["Всі лю́діє удивля́хуся тебі́, ста́рче Феодо́сіє, я́ко призива́нієм Го́спода і моли́твенним твої́м хода́тайством бі́си ізгоня́ються і одержимиє ісціля́ються. Та́ко і ми, к моще́м твої́м приходя́ще, умиле́нно возглаша́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ра́зум челові́чеський не мо́жеть ізрещи́ оби́ліє благода́ті духо́вния, є́юже ти, о́тче Феодо́сіє, преіспо́лнен, ю́же і ми получа́єм, в моли́тві к тебі́ прибіга́юще. Сего́ ра́ди сицево́є пі́ніє прино́сим тебі́:","Ра́дуйся, моли́твами твої́ми тьму напа́стей от нас отгоня́яй;","ра́дуйся, на путь отріше́нія от ми́ра нас наставля́яй.","Ра́дуйся, страданіями ду́шу обогати́вий;","ра́дуйся, утіше́ніє ча́дам духо́вним яви́вий.","Ра́дуйся, Господом укрепленний;","ра́дуйся, Ду́хом Святи́м просвіще́нний.","Ра́дуйся, среди́ го́рських наро́дов пожи́вий;","ра́дуйся, с інові́рними в ми́рі жи́ти учи́вий.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 10","ps":["Богобо́рная гоне́нія на Це́рков Правосла́вную ви́дя, ти, о́тче Феодо́сіє, ві́рних ра́ди по́двиг юро́дства прия́л єси́, да яви́ши лю́дем прему́дрости Бо́жієй ве́лія да́ри, вопія́ Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ ти єси́ і тве́рдоє прибі́жище к заступле́нію твоєму́ прибегающим, чудотво́рче Феодо́сіє. Ті́мже в біда́х, ско́рбіх, обстоя́ніїх і лише́ніїх мно́гих пребива́юще, ра́дуяся твоєму́ о нас заступле́нію, благода́рно вопіє́м ті:","Ра́дуйся, в юро́дстві си́лу Бо́жию лю́дем правосла́вним яви́вий;","ра́дуйся, гряду́щая, я́ко настоя́щая, прови́дівий.","Ра́дуйся, прегріше́ній сокрове́нних обличи́телю прозорли́вий;","ра́дуйся, жи́телем гра́да Минводи ско́рби в при́тчах предсказавий.","Ра́дуйся, діте́й ма́лих от о́гненнаго запале́нія чуде́сно ізба́вивий;","ра́дуйся, призива́ющим тя ско́рий помо́щниче.","Ра́дуйся, любві́ і смире́нію свою́ па́ству науча́яй;","ра́дуйся, от по́мисла гріхо́внаго упавших ду́хом отвраща́яй.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє Пресвяті́й Тро́йце прине́сл єси́, єгда́ ду́шу свою́ Спаси́телю ми́ра в ру́ці пре́дал єси́ і с ли́ки А́нгел в небе́сния селе́нія всели́лся єси́, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Ви́дівше лю́діє, уго́дниче Бо́жий Феодо́сіє, ми́рную кончи́ну твою́ і чудеса́ на гро́бі твоє́м твори́мая, возра́довашася. Ті́мже в упова́нії всеси́льнаго предста́тельства твоєго́ у Престо́ла Пресвяти́я Тро́йці уві́ришася, с любо́вію взива́ють ті:","Ра́дуйся, я́ко Госпо́дь тя в оби́телі небе́сния всели́;","ра́дуйся, я́ко кончи́ну твою́ колокольний звон чуде́сно возвісти́.","Ра́дуйся, я́ко гроб твой А́нгели сопровождаша;","ра́дуйся, я́ко на могилі твоє́й столп о́гненний лю́діє ви́діша.","Ра́дуйся, я́ко от моще́й твої́х верниє получа́ють ісціле́ніє;","ра́дуйся, притека́ющих ко гро́бу твоєму́ крі́пкоє заступле́ніє.","Ра́дуйся, Та́їн Бо́жиїх ві́чний зри́телю;","ра́дуйся, от бід і го́ря ско́рий ізба́вителю.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию прия́л єси́, пресла́вне Феодо́сіє, я́ко при жи́зні твоє́й світи́льник бил єси́ приходящим к тебі́ с ві́рою, і по сме́рті своє́й возсія́л єси́ сві́том чуде́с твої́х. Лю́діє же, див'я́щеся о сла́ві твоє́й, взива́ють Бо́гу со умиле́нієм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́внаго во святи́х Свої́х, восхваля́єм тя, преподо́бне о́тче Феодо́сіє, ти бо єси́ о́браз житія́ ю́ним, пра́вило ві́ри муже́м, учи́тель ста́рцев, нам же всім моли́твенник і предста́тель. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, долголі́тієм от Бо́га одаренний;","ра́дуйся, і по сме́рті чад свої́х не оста́вивий.","Ра́дуйся, оби́ліє чуде́с ві́рним яви́вий;","ра́дуйся, всім с ві́рою приходящим к моще́м твої́м помога́яй.","Ра́дуйся, на стезю́ спасе́нія всіх наставля́яй;","ра́дуйся, Це́рков Святу́ю от неві́рія і раско́лов сохраня́яй.","Ра́дуйся, в обстаяніїх і напа́стіх ві́рний о нас моли́твенниче;","ра́дуйся, па́стирей землі́ Кавкаськия покрови́телю і ско́рий помо́щниче.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 13","ps":["О, пречу́дний уго́дниче Бо́жий і чудотво́рче, преподо́бне о́тче Феодо́сіє! Ти воі́стину дар Бо́жий єси́ нам, і́же во і́ночестві, і во свяще́нстві, і во юро́дстві Триіпоста́снаго Бо́га просла́вил єси́. Прийми́ ма́лоє сіє́ моле́ніє на́ше і умоли́ Го́спода Бо́га, да поми́луєть нас твої́ми мольба́ми і на путь покая́нія всіх наста́вить, вопію́щих Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ тя от чре́ва ма́тере твоєя́ і в рождестві́ твоє́м показа́ зна́меніє бу́дущаго і́ночеськаго житія́ твоєго́, да бу́деши, богоблаже́нне Феодо́сіє, моли́твенник ко Го́споду і Пречи́стій єго́ Ма́тері за весь мир. Ми же, грі́шнії, упова́юще на ско́рую по́мощ твою́, взива́єм ті си́це:","Ра́дуйся, от чре́ва ма́тере Господом ізбра́нний;","ра́дуйся, єще́ в детстві к служе́нію Бо́гу преднареченний.","Ра́дуйся, в рождестві́ твоє́м чу́дноє зна́меніє мона́шеськаго житія́ яви́вий;","ра́дуйся, в ю́ності строгость і́ночеськаго житія́ показа́вий.","Ра́дуйся, Христа́ всім се́рдцем возлюби́вий;","ра́дуйся, ум і се́рдце Го́споду преда́вий.","Ра́дуйся, наро́да россі́йськаго моли́твенноє огражде́ніє;","ра́дуйся, землі́ Кавкаськия свяще́нноє украше́ніє.","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і пресла́вний чудотво́рче, преподо́бне о́тче Феодо́сіє, по́двиги твої́ми А́нгели удиви́вий і челові́ки мно́гія із глубини́ гріхо́вния ізведи́й, умоли́ і о нас просла́вльшаго тя Го́спода і от бід і напа́стей нас свободи́, любо́вію зову́щих ті:","Ра́дуйся, преподо́бне Феодо́сіє, Кавкаський чудотво́рче."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, преподо́бне о́тче Феодо́сіє!","Ти, от ю́ности Христа́ возлюби́вий і Єди́ному Єму́ послі́довавий, удали́лся єси́ в уді́л Ма́тері Бо́жия, на Святу́ю Го́ру Афо́нськую, і отту́ду ко Гро́бу Госпо́дню прите́кл єси́. Та́мо во свяще́нном чи́ні мно́гая лі́та пребива́я, соверша́л усе́рдная моле́нія за зе́млю Россі́йськую, за Це́рков Правосла́вную і за наро́д ру́ський. Єгда́ же пости́же Русь Святу́ю лихолетіє безбо́жия, ти, оста́вив Афо́н і Ієрусали́м, вернулся єси́ во Оте́чество своє́, разділя́я ско́рби наро́да своєго́ і Це́ркві на́шея Святи́я, я́коже мона́х і священнослужи́тель, да́же до темни́чнаго заточе́нія. Ві́ра твоя́, кро́тость, смире́ніє і терпі́ніє умиляху огрубевшая се́рдця в заточе́нії с тобо́ю пребивавших. В годи бра́ні ти, о́тче, помога́л наро́ду правосла́вному одолі́ти врага́ і супоста́та, і мно́гих, от уни́нія, го́ря і отча́янія самово́льне живо́т свой сконча́ти желавших, спасл єси́. По́мощію твоє́ю укріпля́хуся ві́рнії во упова́нії своє́м, я́ко не оста́вить Госпо́дь Оте́чество на́ше, Ма́тер Бо́жия сохрани́ть уді́л Свой, і гнів Бо́жий Єя́ моли́твами на ми́лость претвори́ться. Многотрудний твой по́двиг юро́дства Христа́ ра́ди удиви́, о́тче, не то́кмо нас, земни́х, но і небожи́телей, являвшихся тебі́. Вся бо мо́жеть сотвори́ти моли́тва пра́ведника, ві́рою крі́пкою поспішеству́ємая.","Ти ві́си ну́жди і печа́лі на́ша, преподо́бне о́тче Феодо́сіє, ві́си і жела́ніє на́ше со Христо́м би́ти. Пройдя ті́сний і терни́стий путь земна́го битія́, ти несл яре́м тя́жкий от бра́тій свої́х, от неві́рних і соплеменников. Пом'яни́ нас, ста́рче Бо́жий, у Престо́ла Госпо́дня, я́ко обіща́лся єси́ помога́ти всім, і́же обрати́ться к тебі́.","Па́м'ять твоя́, о́тче, на землі́ Кавказстей не оскудіва́єть і понине: се бо с ві́рою і упова́нієм притека́ють правосла́внії лю́діє к моще́м твої́м, прося́ще заступле́нія і по́мощі. Про́сим тя, преподо́бне о́тче Феодо́сіє: помози́ нам в тру́дний час жи́зні на́шея, в минути скорбе́й і страда́ній, умоли́ Нача́льника ми́ра Го́спода, да ум'ягчи́ть Он зла́я і огрубевшая се́рдця челові́чеськая і умири́ть наро́ди Кавказа, да разори́ть нечестивиє сові́ти раскольников і єретико́в, возстаю́щих на Святу́ю Це́рков Ру́ськую.","Твої́ми моли́твами, свя́тче Бо́жий, да прости́ть нам Госпо́дь вся́кая прегріше́нія, да мину́ють нас стрі́ли вра́жія і ко́зні дия́вольськия. Іспроси́ у Творця́ і Промисли́теля жи́зні на́шея вре́м'я на покая́ніє, от па́губи ізбавле́ніє, боля́щим здра́віє, падшим возстановле́ніє, скорб'я́щим утіше́ніє, ча́дом в стра́хі Бо́жиєм воспита́ніє, отходящим к ві́чності благо́є уготовле́ніє, отшедшим упокоє́ніє і Небе́снаго Ца́рствія наследованіє.","Бу́ди, о́тче Феодо́сіє, покровителем і помо́щником всім ві́рним землі́ Кавкаськия. Да укріпи́ться і умно́житься на ней і во всей Русі́ Вели́цій Свято́є Правосла́віє. Ми же, святи́ми твої́ми моли́твами укріпля́ємі, просла́вим Живонача́льную Тро́йцю і твоє́ освяще́нноє Бо́гом і́м'я, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, блаже́нне, і Єго́ ра́ди на Свято́й Афо́н і ко Гро́бу Госпо́дню удали́лся єси́, і та́мо благода́тію і да́ром чуде́с обогати́вся, в страну́ Россі́йськую к лю́дем свої́м возврати́лся єси́. Наро́ди Кавказа в годи́ну гоне́ній моли́твами, по́двигом юро́дства і чудеси́ мно́гими во Правосла́вії укріпи́вий, преподо́бне о́тче Феодо́сіє, моли́ Христа́ Бо́га, да укріпи́ть Госпо́дь лю́ди, зді живу́щия, во Правосла́вії, і огради́ть зе́млю на́шу ми́ром, і спасе́ть всіх, я́ко милосе́рд."]},{"h":"Кондак, глас 4","ps":["Всю жизнь Христу́ Бо́гу отда́л єси́, преподо́бне о́тче Феодо́сіє, по́двиги моли́тви, стоя́нія у Гро́ба Госпо́дня, поста́, воздержа́нія, юро́дства, темни́чнаго заточе́нія Єго́ ра́ди претерпі́л єси́ до конця́. Ті́мже і Христо́с долголі́тієм і чудеса́ми тя обогати́, я́ко і дони́ні лю́діє землі́ на́шея к моще́м твої́м притека́ють с ві́рою і получа́ють проси́моє. О́тче наш Феодо́сіє преди́вний, моли́ Го́спода Бо́га і Влади́ку всіх о сохране́нії в страні́ Росси́йстій Правосла́вія, умиреніїї ми́ра і спасе́нії душ на́ших."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Феодо́сіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]}];
